INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (20, 'AFMC', 'ETF', 'us', 'DWS RREEF Real Assets Fund - Cl', 'DWS RREEF Real Assets Fund - Class T', 'Usd', 'Value', 'Medium', 'DWS', 'PCX', 'Mid-Cap Blend', 1268811, 0.0079, '2019-12-04', NULL, 'The investment seeks total return in excess of inflation through capital growth and current income. The fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in a combination of investments that the Advisor believes offer exposure to "real assets." It generally invests between 25% and 75% of fund assets in securities of foreign issuers, including up to 10% of fund assets in issuers located in countries with new or emerging markets.', 0.0065, 0.0047, 717, 2470, 26.057, 25.309, 0.9982, 0, 2.44, 9.69, 15.98, 1.24, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 1268811, "Yield_Rate": 0.0079, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0047, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 717, "Vol_Recent": 2470}, "moving_averages": {"MA_50": 26.057, "MA_200": 25.309}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9982}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.44, "PE_Ratio": 15.98, "PS_Ratio": 1.24, "PCF_Ratio": 9.69}}');
