INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (61, 'ARKX', 'ETF', 'usa', 'American Beacon Balanced Fund I', 'American Beacon Balanced Fund R5 Class', 'Usd', 'Growth', 'Large', 'American Beacon', 'BTS', NULL, 669418624, NULL, '2021-03-30', NULL, 'The investment seeks income and capital appreciation. Under normal circumstances, between 50% and 70% of the fund''s total assets are invested in equity securities and between 30% and 50% of the fund''s total assets are invested in debt securities. The fund''s equity investments may include common stocks, convertible securities, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs") and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively referred to as "stocks"). It may invest in companies of all market capitalizations.', 0.0075, NULL, 274227, 294090, 20.102, 20.393, 0.9976, 0, 4.86, 20.85, 33.93, 2.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 669418624, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 274227, "Vol_Recent": 294090}, "moving_averages": {"MA_50": 20.102, "MA_200": 20.393}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.86, "PE_Ratio": 33.93, "PS_Ratio": 2.84, "PCF_Ratio": 20.85}}');
