INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (72, 'AUSF', 'ETF', 'America', NULL, 'American Century One Choice Blend+ 2050 Portfolio R6 Class', 'USD', 'Value', 'Medium', 'American Century Investments', 'PCX', NULL, 177803584, 0.0235, '2018-08-24', NULL, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other mutual funds and exchange-traded funds (ETFs) advised by American Century (collectively, the underlying funds) that represent a variety of asset classes and investment styles. The underlying stock funds draw on growth, value and quantitative investment techniques and diversify investments among small, medium and large U.S. and foreign companies.', 0.0027, NULL, 5217, 3290, 30.602, 29.795, 0.9995, 0, 2.07, 9.98, 16.48, 1.36, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 177803584, "Yield_Rate": 0.0235, "Expense_Net": 0.0027, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5217, "Vol_Recent": 3290}, "moving_averages": {"MA_50": 30.602, "MA_200": 29.795}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.07, "PE_Ratio": 16.48, "PS_Ratio": 1.36, "PCF_Ratio": 9.98}}');
