INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (84, 'AWTM', 'ETF', 'America', 'The Alger Fds II, Alger Emergin', 'Alger Emerging Markets Fund Class A', 'US Dollar', NULL, NULL, 'Alger', 'PCX', 'Ultrashort Bond', 155644032, 0.0123, '2019-01-28', 1.94, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities, including common stocks, American Depositary Receipts and Global Depositary Receipts, of emerging country issuers. It generally invests in at least three emerging countries, and, at times, may invest a substantial portion of its assets in a single emerging country. The fund may invest in companies of any market capitalization, from larger, well-established companies to small, emerging growth companies.', 0.0025, 0.0022, 39072, 3620, 49.669, 49.779, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 155644032, "Yield_Rate": 0.0123, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 1.94}', '{"volume_metrics": {"Vol_3M": 39072, "Vol_Recent": 3620}, "moving_averages": {"MA_50": 49.669, "MA_200": 49.779}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (85, 'AZAA', 'ETF', 'U.S.A.', 'Strategic Enhanced Yield Fund C', 'Cavanal Hill Strategic Enhanced Yield Fund Class A', 'Dollar', 'Blend', 'Large', 'Cavanal Hill funds', 'PCX', 'Large Blend', 18157956, NULL, '2020-05-28', NULL, 'The investment seeks current income and, secondarily, the opportunity for capital appreciation to produce total return. The fund seeks total return by allocating assets among various fixed income sectors, with no more than 65% of its net assets in any one sector. The Adviser will employ a strategy to enhance the fund''s yield by shifting assets among higher yielding and lower yielding debt securities across sectors and different maturities based on its view of the relative value of each sector or maturity. Under normal circumstances, the fund invests at least 80% of its net assets in bonds.', 0.0074, 0.0036, 2035, 270, 28.692, 27.835, 0.9987, 0, 4.26, 17.31, 25.99, 2.88, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 18157956, "Yield_Rate": null, "Expense_Net": 0.0074, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2035, "Vol_Recent": 270}, "moving_averages": {"MA_50": 28.692, "MA_200": 27.835}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.26, "PE_Ratio": 25.99, "PS_Ratio": 2.88, "PCF_Ratio": 17.31}}');
