INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (112, 'BCD', 'ETF', 'U.S.A.', 'American Funds 2055 Target Date', 'American Funds 2055 Target Date Retirement Fund Class A', 'DOLLAR', NULL, NULL, 'American Funds', 'PCX', 'Commodities Broad Basket', 36874288, 0.0107, '2017-03-30', NULL, 'The investment seeks growth, income and conservation of capital. The fund normally invests a greater portion of its assets in fixed income, equity-income and balanced funds as it approaches and passes its target date. The advisor attempts to achieve its investment objectives by investing in a mix of American Funds in different combinations and weightings. The underlying American Funds represent a variety of fund categories, including growth funds, growth-and-income funds, equity-income funds, balanced funds and fixed income funds. The fund categories represent differing investment objectives.', 0.0029, 0.0081, 23309, 43550, 33.57, 30.649, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 36874288, "Yield_Rate": 0.0107, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 23309, "Vol_Recent": 43550}, "moving_averages": {"MA_50": 33.57, "MA_200": 30.649}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
