INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (121, 'BFOR', 'ETF', 'USA', 'Cavanal Hill Limited Duration F', 'Cavanal Hill Limited Duration Fund Class A', 'Usd', 'Blend', 'Medium', 'Cavanal Hill funds', 'PCX', 'Mid-Cap Growth', 142525216, 0.0082, '2013-06-03', NULL, 'The investment seeks income and secondarily seeks capital appreciation. The fund invests primarily in debt obligations such as bonds, notes and debentures, and bills issued by U.S. corporations or by the U.S. government, its agencies or instrumentalities, municipal securities, mortgage-backed securities, asset-backed securities, and collateralized mortgage obligations and fixed income ETFs. It ivests at least 80% of its net assets in bonds and maintains an average portfolio duration of less than three and one-half years. The fund normally invests at least 65% of its net assets in interest-bearing bonds.', 0.007, 0.0046, 2943, 3000, 62.631, 59.488, 0.993, 0, 3.42, 12.55, 15.7, 1.63, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 142525216, "Yield_Rate": 0.0082, "Expense_Net": 0.007, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2943, "Vol_Recent": 3000}, "moving_averages": {"MA_50": 62.631, "MA_200": 59.488}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.42, "PE_Ratio": 15.7, "PS_Ratio": 1.63, "PCF_Ratio": 12.55}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (122, 'BFTR', 'ETF', 'USA', 'Ancora/Thelen Small Mid-Cap Fun', 'Ancora/Thelen Small-Mid Cap Fund Class I', 'DOLLAR', 'Growth', 'Medium', 'Ancora', 'PCX', 'Mid-Cap Growth', 23180106, NULL, '2020-09-29', NULL, 'The investment seeks to obtain capital appreciation. The fund normally will invest at least 80% of its net assets in the equity securities of "small to mid cap" companies. Currently, the adviser defines a small to mid-cap company to be one whose market capitalization either falls within the capitalization range of the Russell 2500 Index, an index that tracks stocks of 2,500 of the smallest U.S. companies, or is $10 billion or less at the time of investment.', 0.008, 0.0046, 2243, 3480, 50.546, 49.828, 0.9978, 0, 8.49, 37.19, NULL, 7.67, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 23180106, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2243, "Vol_Recent": 3480}, "moving_averages": {"MA_50": 50.546, "MA_200": 49.828}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9978}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.49, "PE_Ratio": null, "PS_Ratio": 7.67, "PCF_Ratio": 37.19}}');
