INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (124, 'BIB', 'ETF', 'U.S.A.', 'Ultra Short Tax-Free Income Fun', 'Cavanal Hill Ultra Short Tax-Free Income Fund Class A', 'US_DOLLAR', 'Growth', 'Medium', 'Cavanal Hill funds', 'NGM', 'Trading--Leveraged Equity', 270422208, NULL, '2010-04-06', 0.37, 'The investment seeks to generate current income exempt from federal income taxes consistent with the preservation of capital. The fund invests in a diversified portfolio of municipal bonds and debentures. As a matter of fundamental policy, it invests, under normal circumstances, at least 80% of its net assets in municipal securities, the income from which is both exempt from federal income tax and not subject to federal alternative minimum tax for individuals. The fund invests at least 80% of its net assets in tax-free bonds and maintains a dollar-weighted average maturity between 1 day to 1 year.', 0.0095, 0.009, 60682, 51860, 89.285, 91.997, NULL, NULL, NULL, NULL, NULL, 3.4, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 270422208, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.37}', '{"volume_metrics": {"Vol_3M": 60682, "Vol_Recent": 51860}, "moving_averages": {"MA_50": 89.285, "MA_200": 91.997}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 3.4, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (125, 'BIBL', 'ETF', 'US', 'Thrivent Large Cap Value Fund C', 'Thrivent Large Cap Value Fund Class A', 'US_DOLLAR', 'Blend', 'Large', 'Thrivent Funds', 'PCX', 'Large Blend', 247182752, 0.0142, '2017-10-30', 0.6, 'The investment seeks to achieve long-term growth of capital. The fund invests at least 80% of its net assets (plus the amount of any borrowing for investment purposes) in equity securities of large companies. The Adviser focuses mainly on the equity securities of large domestic and international companies which have market capitalizations equivalent to those included in widely known indices such as the Russell 1000 Value Index, S&P 500 Index, or the large company market capitalization classifications published by Lipper, Inc. These companies typically have a market capitalization of approximately $8 billion or more.', 0.0035, 0.0036, 31775, 25720, 44.66, 42.465, 0.9942, 0, 4.97, 18.64, 32.87, 2.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 247182752, "Yield_Rate": 0.0142, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.6}', '{"volume_metrics": {"Vol_3M": 31775, "Vol_Recent": 25720}, "moving_averages": {"MA_50": 44.66, "MA_200": 42.465}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9942}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.97, "PE_Ratio": 32.87, "PS_Ratio": 2.84, "PCF_Ratio": 18.64}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (126, 'BICK', 'ETF', 'United States', 'Cavanal Hill World Energy Fund ', 'Cavanal Hill World Energy Fund A', 'US$', 'Blend', 'Large', 'Cavanal Hill funds', 'NGM', 'Diversified Emerging Mkts', 93996840, 0.0039, '2010-04-12', 0.58, 'The investment seeks growth and income. The fund invests at least 80% of its net assets in a wide range of energy-related financial instruments issued in the U.S. and markets around the world. Investments typically include a combination of common stock, bonds, exchange traded funds ("ETFs") and exchange traded notes ("ETNs") but may also include other asset types that are related to energy industry activities. It will invest at least 40%, but may invest up to 100%, of its net assets in the securities of issuers organized or having their principal place of business outside the U.S. or doing a substantial amount of business outside the U.S.', 0.0064, 0.0056, 33709, 2860, 34.35, 37.238, 0.9973, 0, 2.33, 10.23, 18.42, 1.12, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 93996840, "Yield_Rate": 0.0039, "Expense_Net": 0.0064, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.58}', '{"volume_metrics": {"Vol_3M": 33709, "Vol_Recent": 2860}, "moving_averages": {"MA_50": 34.35, "MA_200": 37.238}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9973}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.33, "PE_Ratio": 18.42, "PS_Ratio": 1.12, "PCF_Ratio": 10.23}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (127, 'BIL', 'ETF', 'US', 'MID CAP CORE EQUITY FUND - CLAS', 'Cavanal Hill Mid Cap Diverse Leadership Fund Class A', 'USD', NULL, NULL, 'Cavanal Hill funds', 'PCX', 'Ultrashort Bond', 11959208960, NULL, '2007-05-25', 6.35, 'The investment seeks total return. To pursue its objective, under normal circumstances, the fund invests at least 80% of its net assets in a diversified portfolio of common stocks of Mid Cap U.S. companies that demonstrate governance diversity and leadership. It may also invest up to 20% of its net assets in preferred stocks and cash equivalents, and without regard to governance diversity and leadership ESG criteria.', 0.00136, 0.0022, 1155830, 1.2309e+06, 91.443, 91.47, NULL, NULL, NULL, NULL, NULL, NULL, 0.07, 0.07, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 11959208960, "Yield_Rate": null, "Expense_Net": 0.00136, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 6.35}', '{"volume_metrics": {"Vol_3M": 1155830, "Vol_Recent": 1230900}, "moving_averages": {"MA_50": 91.443, "MA_200": 91.47}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.07, "Duration_Yrs": 0.07}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (128, 'BILS', 'ETF', 'UNITED_STATES', 'AB Municipal Income Fund II - A', 'AB Municipal Income Fund II Arizona Portfolio Class A', 'USD', NULL, NULL, 'AllianceBernstein', 'PCX', NULL, 10007506, NULL, '2020-09-24', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Arizona personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund principally invests in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax.', 0.00136, NULL, 1495, 5420, 100.028, 100.056, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 10007506, "Yield_Rate": null, "Expense_Net": 0.00136, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1495, "Vol_Recent": 5420}, "moving_averages": {"MA_50": 100.028, "MA_200": 100.056}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
