INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (131, 'BIV', 'ETF', 'usa', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class A', 'US_DOLLAR', NULL, NULL, 'AllianceBernstein', 'PCX', 'Intermediate-Term Bond', 39047475200, 0.0206, '2007-04-03', 0.55, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.0005, 0.0023, 940987, 1.20169e+06, 88.908, 89.624, NULL, NULL, NULL, NULL, NULL, NULL, 7.3, 6.63, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 39047475200, "Yield_Rate": 0.0206, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.55}', '{"volume_metrics": {"Vol_3M": 940987, "Vol_Recent": 1201690}, "moving_averages": {"MA_50": 88.908, "MA_200": 89.624}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.3, "Duration_Yrs": 6.63}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, 