INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (156, 'BND', 'ETF', 'U.S.A.', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class I', 'Usd', NULL, NULL, 'AllianceBernstein', 'NGM', 'Intermediate-Term Bond', 312150884352, 0.0202, '2007-04-03', 0.79, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.00035, 0.0023, 5682791, 6.71921e+06, 85.263, 85.58, 0, 0.9902, NULL, NULL, NULL, NULL, 8.6, 6.79, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 312150884352, "Yield_Rate": 0.0202, "Expense_Net": 0.00035, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.79}', '{"volume_metrics": {"Vol_3M": 5682791, "Vol_Recent": 6719210}, "moving_averages": {"MA_50": 85.263, "MA_200": 85.58}}', '{"asset_allocation": {"Bond_Weight": 0.9902, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.6, "Duration_Yrs": 6.79}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (157, 'BNDC', 'ETF', 'United States', 'AB Corporate Shares - AB Impact', 'AB Impact Municipal Income Shares', 'Dollar', NULL, NULL, 'AllianceBernstein', 'PCX', 'Intermediate-Term Bond', 119968144, 0.0214, '2016-11-18', 0.91, 'The investment seeks to earn the highest level of current income, exempt from federal taxation, that is available consistent with what the Adviser considers to be an appropriate level of risk. The fund pursues its objective by investing principally in high-yielding municipal securities of any credit quality that (i) score highly on the Adviser''s environmental, social and governance ("ESG") criteria and (ii) are deemed by the Adviser to have an environmental or social impact in underserved or low socio-economic communities. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax.', 0.0035, 0.0023, 9370, 10260, 26.197, 26.261, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7.07, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 119968144, "Yield_Rate": 0.0214, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.91}', '{"volume_metrics": {"Vol_3M": 9370, "Vol_Recent": 10260}, "moving_averages": {"MA_50": 26.197, "MA_200": 26.261}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 7.07}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (158, 'BNDX', 'ETF', 'US', 'American Century Balanced Fund ', 'American Century Balanced Fund I Class', 'Usd', NULL, NULL, 'American Century Investments', 'NGM', NULL, 116407050240, 0.0094, '2013-05-31', 0.31, 'The investment seeks long-term capital growth and current income. For the equity portion of the fund, the portfolio managers select stocks using quantitative management techniques in a multi-step process. For the fixed-income portion of the fund, the portfolio managers invest in a diversified portfolio of high- and medium-grade non-money market debt securities. These securities, which may be payable in U.S. or foreign currencies, may include corporate bonds and notes, government securities, bank loans, securities backed by mortgages or other assets and collateralized debt obligations.', 0.0008, NULL, 2296838, 2.27619e+06, 56.911, 57.209, NULL, NULL, NULL, NULL, NULL, NULL, 9.7, 8.38, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 116407050240, "Yield_Rate": 0.0094, "Expense_Net": 0.0008, "Benchmark_Exp": null, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 2296838, "Vol_Recent": 2276190}, "moving_averages": {"MA_50": 56.911, "MA_200": 57.209}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 9.7, "Duration_Yrs": 8.38}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
