INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (162, 'BOCT', 'ETF', 'U.S.', 'Alger Portfolios - Alger Balanc', 'Alger Balanced Portfolio Class I-2', 'US_DOLLAR', 'Blend', 'Large', 'Alger', 'BTS', NULL, 81503288, NULL, '2018-09-28', NULL, 'The investment seeks current income and long-term capital appreciation. The manager focuses on stocks of companies that the advisor believes demonstrate growth potential and on fixed-income securities, with emphasis on income-producing securities that appear to have potential for capital appreciation. It normally will invest at least 25% of its net assets in fixed-income securities and at least 25% of its net assets in equity securities. The fund also may invest up to 10% of its net assets in lower-rated securities, rated "B" (or the equivalent) or better by any one of those rating agencies.', 0.008, NULL, 26601, 5040, 33.621, 32.311, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 81503288, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 26601, "Vol_Recent": 5040}, "moving_averages": {"MA_50": 33.621, "MA_200": 32.311}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (163, 'BOIL', 'ETF', 'us', 'American Beacon Balanced Fund A', 'American Beacon Balanced Fund Advisor Class', 'USD', NULL, NULL, 'American Beacon', 'PCX', 'Trading--Leveraged Commodities', 70214528, NULL, '2011-10-04', NULL, 'The investment seeks income and capital appreciation. Under normal circumstances, between 50% and 70% of the fund''s total assets are invested in equity securities and between 30% and 50% of the fund''s total assets are invested in debt securities. The fund''s equity investments may include common stocks, convertible securities, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs") and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively referred to as "stocks"). It may invest in companies of all market capitalizations.', 0.0131, 0.009, 1827085, 2.5572e+06, 64.969, 41.076, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 70214528, "Yield_Rate": null, "Expense_Net": 0.0131, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1827085, "Vol_Recent": 2557200}, "moving_averages": {"MA_50": 64.969, "MA_200": 41.076}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (166, 'BOTZ', 'ETF', 'UNITED_STATES', 'AMG Managers Fairpointe Mid Cap', 'AMG River Road Mid Cap Value Fund - Class I', 'Usd', 'Growth', 'Large', 'AMG Funds', 'NGM', 'Miscellaneous Sector', 2581059840, 0.0017, '2016-09-12', NULL, 'The investment seeks long-term total return through capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in securities of mid-capitalization companies. The adviser currently considers mid-cap companies to be those with market capitalizations at the time of acquisition within the capitalization range of the Russell Midcap© Index.', 0.0068, 0.0067, 635325, 572480, 37.321, 35.321, 0.9995, 0, 4.14, 23.35, 47.48, 3.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 2581059840, "Yield_Rate": 0.0017, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0067, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 635325, "Vol_Recent": 572480}, "moving_averages": {"MA_50": 37.321, "MA_200": 35.321}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.14, "PE_Ratio": 47.48, "PS_Ratio": 3.63, "PCF_Ratio": 23.35}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (167, 'BOUT', 'ETF', 'U.S.A.', 'AB Bond Fund, Inc. - AB Bond In', 'AB Bond Inflation Strategy Class A', 'US Dollar', 'Blend', 'Medium', 'AllianceBernstein', 'PCX', NULL, 19716544, NULL, '2018-09-12', 16.37, 'The investment seeks to maximize real return without assuming what the Adviser considers to be undue risk. The fund pursues its objective by investing principally in inflation-indexed securities (such as Treasury Inflation-Protected Securities ("TIPS") or inflation-indexed securities from issuers other than the U.S. Treasury) or by gaining inflation protection through derivatives transactions, such as inflation (CPI) swaps or total return swaps linked to TIPS. Under normal circumstances, it invests at least 80% of its net assets in fixed-income securities.', 0.008, NULL, 13388, 12350, 36.444, 34.604, 0.9912, 0, 2.43, 13.34, 19.72, 3.52, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 19716544, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": 16.37}', '{"volume_metrics": {"Vol_3M": 13388, "Vol_Recent": 12350}, "moving_averages": {"MA_50": 36.444, "MA_200": 34.604}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9912}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.43, "PE_Ratio": 19.72, "PS_Ratio": 3.52, "PCF_Ratio": 13.34}}');
