INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (171, 'BSBE', 'ETF', 'USA', 'Aberdeen International Small Ca', 'Aberdeen International Small Cap Fund Institutional Class', 'Dollar', NULL, NULL, 'Aberdeen', 'NGM', 'Emerging Markets Bond', 38571416, 0.0323, '2018-10-04', 0.07, 'The investment seeks long-term growth of capital. The fund seeks to achieve its objective by investing primarily in equity securities of small non-U.S. companies. Equity securities include, but are not limited to, common stock, preferred stock and depositary receipts. As a non-fundamental policy, under normal market conditions, it will invest at least 80% of the value of its net assets, plus any borrowings for investment purposes, in equity securities of non-U.S. small companies.', 0.0029, 0.0046, 5416, 4510, 25.555, 25.709, 0, 0.9989, NULL, NULL, NULL, NULL, 1.51, 1.22, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 38571416, "Yield_Rate": 0.0323, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.07}', '{"volume_metrics": {"Vol_3M": 5416, "Vol_Recent": 4510}, "moving_averages": {"MA_50": 25.555, "MA_200": 25.709}}', '{"asset_allocation": {"Bond_Weight": 0.9989, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 1.51, "Duration_Yrs": 1.22}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
