INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (178, 'BSCQ', 'ETF', 'usa', 'The AB Portfolios - AB Conserva', 'AB Conservative Wealth Strategy Class A', 'DOLLAR', NULL, NULL, 'AllianceBernstein', 'NGM', NULL, 535562560, 0.0213, '2016-09-13', 0.07, 'The investment seeks to achieve a high total return without, in the opinion of the Adviser, undue risk to principal. The Adviser allocates the fund''s investments among a number of asset classes, including fixed-income securities, equity securities, and alternative asset classes and alternative investment strategies. The fund seeks to have generally greater exposure to fixed-income securities than equity securities or alternative asset classes and alternative investment strategies.', 0.001, NULL, 178477, 160510, 21.272, 21.448, 0, 0.992, NULL, NULL, NULL, NULL, 5.14, 4.67, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 535562560, "Yield_Rate": 0.0213, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.07}', '{"volume_metrics": {"Vol_3M": 178477, "Vol_Recent": 160510}, "moving_averages": {"MA_50": 21.272, "MA_200": 21.448}}', '{"asset_allocation": {"Bond_Weight": 0.992, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 5.14, "Duration_Yrs": 4.67}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
