INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (180, 'BSCS', 'ETF', 'America', 'AB Large Cap Growth Fund, Inc. ', 'AB Large Cap Growth Fund Class R', 'Dollar', NULL, NULL, 'AllianceBernstein', 'NGM', NULL, 290933280, 0.0233, '2018-08-09', 0.03, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of a limited number of large, carefully selected, high-quality U.S. companies. It invests primarily in the domestic equity securities of companies selected by the fund''s Adviser for their growth potential within various market sectors. The fund emphasizes investments in large, seasoned companies. Under normal circumstances, the fund will invest at least 80% of its net assets in common stocks of large-capitalization companies. It may, at times, invest in shares of exchange-traded funds in lieu of making direct investments in securities.', 0.001, NULL, 39987, 28170, 22.827, 22.934, 0, 0.9992, NULL, NULL, NULL, NULL, 7.04, 6.11, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 290933280, "Yield_Rate": 0.0233, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 39987, "Vol_Recent": 28170}, "moving_averages": {"MA_50": 22.827, "MA_200": 22.934}}', '{"asset_allocation": {"Bond_Weight": 0.9992, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.04, "Duration_Yrs": 6.11}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
