INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (193, 'BSML', 'ETF', 'usa', 'ABR Dynamic Short Volatility Fu', 'ABR 50/50 Volatility Fund Investor Shares', 'US$', NULL, NULL, 'ABR', 'NGM', NULL, 40390524, 0.0057, '2019-09-25', 0.02, 'The investment seeks long-term capital appreciation. Under normal market conditions, manage the fund''s assets so that fifty percent (50%) of its net assets are managed in accordance with the Adviser''s proprietary "long" volatility strategy, and the remaining fifty percent (50%) of its net assets are managed in accordance with the Adviser''s proprietary "short" volatility strategy. The fund is non-diversified.', 0.0018, NULL, 3296, 7550, 25.235, 25.272, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 40390524, "Yield_Rate": 0.0057, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": 0.02}', '{"volume_metrics": {"Vol_3M": 3296, "Vol_Recent": 7550}, "moving_averages": {"MA_50": 25.235, "MA_200": 25.272}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
