INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (196, 'BSMO', 'ETF', 'USA', 'ABR DYNAMIC BLEND EQUITY & VOLA', 'ABR Dynamic Blend Equity & Volatility Fund Investor Shares', 'Usd', NULL, NULL, 'ABR', 'NGM', NULL, 28300248, 0.0093, '2019-09-25', NULL, 'The investment seeks investment results that correspond generally to the performance, before the fund''s fees and expenses, of the ABR Dynamic Blend Equity & Volatility Index. The fund will invest at least 80% of the value of its net assets (plus borrowing for investment purposes) in securities and instruments, including derivatives, that provide exposure to the constituents of the index powered by Wilshire. The index is designed to capture favorable volatility movements in the equity markets while maintaining equity exposure to preserve positive performance during extended periods of rising markets.', 0.0018, NULL, 3367, 2700, 25.752, 25.788, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 28300248, "Yield_Rate": 0.0093, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3367, "Vol_Recent": 2700}, "moving_averages": {"MA_50": 25.752, "MA_200": 25.788}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
