INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (199, 'BSMR', 'ETF', 'U.S.', 'AmericaFirst Monthly Risk-On Ri', 'AmericaFirst Monthly Risk-On Risk-Off Fund Class I', 'US Dollar', NULL, NULL, 'AmericaFirst Funds', 'NGM', NULL, 17843824, 0.0132, '2019-09-25', NULL, 'The investment seeks to achieve capital appreciation with a focus on producing positive returns regardless of the direction of the financial markets. The fund seeks to achieve its investment objective through long positions in global equity markets and U.S. interest rate markets. It will invest in equity securities regardless of market capitalization and regardless of industry sector. With regard to fixed income securities, the fund invests primarily in U.S. Treasury bonds with a mid-term maturity.', 0.0018, NULL, 1382, 720, 25.735, 25.803, 0, 0.9942, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 17843824, "Yield_Rate": 0.0132, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1382, "Vol_Recent": 720}, "moving_averages": {"MA_50": 25.735, "MA_200": 25.803}}', '{"asset_allocation": {"Bond_Weight": 0.9942, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (200, 'BSMS', 'ETF', 'USA', 'Invesco Balanced-Risk Allocatio', 'Invesco Balanced-Risk Allocation Fund Class Y', 'usd', NULL, NULL, 'Invesco', 'NGM', NULL, 13023086, 0.0166, '2019-09-25', NULL, 'The investment seeks to provide total return with a low to moderate correlation to traditional financial market indices. The fund''s investment strategy is designed to provide capital loss protection during down markets by investing in multiple asset classes. Its exposure to these three asset classes will be achieved primarily through investments in derivative instruments (generally having aggregate notional exposure exceeding 65% of the fund''s net assets), including but not limited to futures, options, currency forward contracts and swap agreements.', 0.0018, NULL, 2448, 1620, 26.08, 26.173, 0, 0.9908, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 13023086, "Yield_Rate": 0.0166, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2448, "Vol_Recent": 1620}, "moving_averages": {"MA_50": 26.08, "MA_200": 26.173}}', '{"asset_allocation": {"Bond_Weight": 0.9908, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
