INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (226, 'CBTG', 'ETF', 'America', 'Abbey Capital Futures Strategy ', 'Abbey Capital Futures Strategy Fund Class A', 'US Dollar', 'Growth', 'Small', 'Abbey Capital', 'BTS', NULL, 38130772, NULL, '2020-12-29', NULL, 'The investment seeks long-term capital appreciation; current income is a secondary objective. The fund allocates its assets between a Managed Futures strategy and a Fixed Income strategy. The Managed Futures strategy will be achieved by investing a portion of its assets in the Onshore Subsidiary and up to 25% of its total assets in the Cayman Subsidiary. The Fixed Income strategy invests its assets primarily in investment grade fixed income securities (of all durations and maturities) in order to generate interest income and capital appreciation, which may add diversification to the returns generated by its Managed Futures strategy. It is non-diversified.', 0.0075, NULL, 4822, 1640, 23.137, 26.936, 0.9994, 0, 8.1, NULL, NULL, 0.9, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 38130772, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4822, "Vol_Recent": 1640}, "moving_averages": {"MA_50": 23.137, "MA_200": 26.936}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.1, "PE_Ratio": null, "PS_Ratio": 0.9, "PCF_Ratio": null}}');
