INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (228, 'CCRV', 'ETF', 'USA', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Advisor Class', 'US_DOLLAR', NULL, NULL, 'AllianceBernstein', 'PCX', 'Commodities Broad Basket', 35836652, NULL, '2020-09-01', NULL, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.004, 0.0081, 4225, 4680, 28.072, 25.592, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 35836652, "Yield_Rate": null, "Expense_Net": 0.004, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4225, "Vol_Recent": 4680}, "moving_averages": {"MA_50": 28.072, "MA_200": 25.592}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": nu