INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (229, 'CDC', 'ETF', 'USA', 'Abbey Capital Futures Strategy ', 'Abbey Capital Futures Strategy Fund Class I', 'Dollar', 'Value', 'Large', 'Abbey Capital', 'NGM', NULL, 866048960, 0.0227, '2014-07-01', NULL, 'The investment seeks long-term capital appreciation; current income is a secondary objective. The fund allocates its assets between a Managed Futures strategy and a Fixed Income strategy. The Managed Futures strategy will be achieved by investing a portion of its assets in the Onshore Subsidiary and up to 25% of its total assets in the Cayman Subsidiary. The Fixed Income strategy invests its assets primarily in investment grade fixed income securities (of all durations and maturities) in order to generate interest income and capital appreciation, which may add diversification to the returns generated by its Managed Futures strategy. It is non-diversified.', 0.0037, NULL, 77932, 45480, 66.575, 64.873, 0.9988, 0, 2.4, 10.35, 18.83, 1.6, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 866048960, "Yield_Rate": 0.0227, "Expense_Net": 0.0037, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 77932, "Vol_Recent": 45480}, "moving_averages": {"MA_50": 66.575, "MA_200": 64.873}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.4, "PE_Ratio": 18.83, "PS_Ratio": 1.6, "PCF_Ratio": 10.35}}');
