INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (241, 'CHB', 'ETF', 'usa', 'American Century Strategic Allo', 'American Century Strategic Allocation: Conservative Fund A Class', 'US_DOLLAR', 'Growth', 'Large', 'American Century Investments', 'NGM', 'China Region', 6541478, NULL, '2020-09-22', NULL, 'The investment seeks the highest level of total return consistent with its asset mix. The fund''s asset allocation strategy diversifies investments among equity securities, bonds and money market instruments. It usually invests 45% of its assets in equities, 49% of its assets in bonds, and 6% of its assets in cash equivalents. The fund also invests in a variety of debt securities payable in U.S. and foreign currencies. It may invest in any type of U.S. or foreign equity security that meets certain fundamental and technical standards. The fund may invest up to 10% of its assets in below investment-grade securities.', 0.0067, 0.0068, 1241, 1160, 15.586, 17.058, 0.9972, 0, 7.63, 27.92, 39.86, 6.34, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 6541478, "Yield_Rate": null, "Expense_Net": 0.0067, "Benchmark_Exp": 0.0068, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1241, "Vol_Recent": 1160}, "moving_averages": {"MA_50": 15.586, "MA_200": 17.058}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9972}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.63, "PE_Ratio": 39.86, "PS_Ratio": 6.34, "PCF_Ratio": 27.92}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (242, 'CHGX', 'ETF', 'usa', 'Invesco Corporate Bond Fund Cla', 'Invesco Corporate Bond Fund Class A', 'DOLLAR', 'Growth', 'Large', 'Invesco', 'PCX', 'Large Blend', 74164888, 0.0051, '2017-10-09', 1.2, 'The investment seeks current income with preservation of capital; capital appreciation is a secondary objective. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in corporate bonds, and in derivatives and other instruments that have economic characteristics similar to such securities. At least 65% of the fund''s net assets must be, and up to 100% may be, invested in investment grade securities; securities issued or guaranteed by the U.S. government, its agencies or instrumentalities; commercial paper rated Prime by Moody''s or A- or higher by S&P; and cash and cash equivalents.', 0.0049, 0.0036, 15306, 26080, 34.108, 32.684, 1, 0, 5.13, 16.04, 28.18, 3.22, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 74164888, "Yield_Rate": 0.0051, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 1.2}', '{"volume_metrics": {"Vol_3M": 15306, "Vol_Recent": 26080}, "moving_averages": {"MA_50": 34.108, "MA_200": 32.684}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.13, "PE_Ratio": 28.18, "PS_Ratio": 3.22, "PCF_Ratio": 16.04}}');
