INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1240, 'MINT', 'ETF', 'United States', 'Arrow Dynamic Income Fund - A S', 'Arrow DWA Tactical: Income Fund Class A', 'Usd', NULL, NULL, 'Arrow Funds', 'PCX', 'Ultrashort Bond', 14024233984, 0.0056, '2009-11-16', 0.81, 'The investment seeks income and long-term capital appreciation with an emphasis on absolute (positive) returns, low volatility and low correlation to the equity and fixed income markets. The fund primarily invests in fixed income securities of any maturity issued by the U.S. government or its agencies, collateralized or corporate debt of any credit rating.', 0.0036, 0.0022, 868755, 1.09315e+06, 101.785, 101.925, NULL, NULL, NULL, NULL, NULL, NULL, 0.69, 0.53, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 14024233984, "Yield_Rate": 0.0056, "Expense_Net": 0.0036, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 0.81}', '{"volume_metrics": {"Vol_3M": 868755, "Vol_Recent": 1093150}, "moving_averages": {"MA_50": 101.785, "MA_200": 101.925}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.69, "Duration_Yrs": 0.53}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (267, 'CMDY', 'ETF', 'US', 'American Century International ', 'American Century International Value Fund Investor Class', 'US$', 'Value', 'Small', 'American Century Investments', 'PCX', NULL, 86107560, 0.0012, '2018-04-03', NULL, 'The investment seeks long-term capital growth. In selecting stocks for the fund, the portfolio managers will normally invest at least 65% of net assets in securities of issuers from a minimum of three countries outside the United States. The portfolio managers generally look for securities from issuers that have characteristics similar to those of the companies that comprise the MSCI EAFE© Value Index. Characteristics the portfolio managers may consider include industry sector and geographic location, among others. The portfolio managers will normally invest at least 80% of the value of the fund''s net assets in equity securities.', 0.0028, NULL, 29072, 26060, 59.308, 54.695, NULL, NULL, 1.15, 2.24, 4.06, 0.15, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 86107560, "Yield_Rate": 0.0012, "Expense_Net": 0.0028, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 29072, "Vol_Recent": 26060}, "moving_averages": {"MA_50": 59.308, "MA_200": 54.695}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.15, "PE_Ratio": 4.06, "PS_Ratio": 0.15, "PCF_Ratio": 2.24}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (269, 'CN', 'ETF', 'us', 'American Century Inv, Focused D', 'American Century Investments Focused Dynamic Growth Fund R Class', 'Dollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'China Region', 34825720, 0.0075, '2014-04-29', 0.14, 'The investment seeks long-term capital growth. The portfolio managers look for stocks of early and rapid stage growth companies they believe will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.005, 0.0068, 3308, 580, 41.053, 43.642, 0.9948, 0, 2.23, 13.93, 16.66, 1.2, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 34825720, "Yield_Rate": 0.0075, "Expense_Net": 0.005, "Benchmark_Exp": 0.0068, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 3308, "Vol_Recent": 580}, "moving_averages": {"MA_50": 41.053, "MA_200": 43.642}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9948}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.23, "PE_Ratio": 16.66, "PS_Ratio": 1.2, "PCF_Ratio": 13.93}}');
