INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (277, 'COMT', 'ETF', 'usa', 'Disciplined Core Value Fund - C', 'American Century Disciplined Core Value Fund C Class', 'US$', 'Value', 'Small', 'American Century Investments', 'NGM', 'Commodities Broad Basket', 2454140928, 0.0028, '2014-10-15', 0.05, 'The investment seeks long-term capital growth; income is a secondary consideration. In selecting stocks for the fund, the managers use quantitative and qualitative management techniques in a multi-step process. The managers evaluate stocks, primarily large capitalization, publicly traded U.S. companies based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use quantitative models to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0048, 0.0081, 573766, 390580, 36.903, 33.844, NULL, NULL, 1.29, 2.52, 4.56, 0.17, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 2454140928, "Yield_Rate": 0.0028, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0081, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 573766, "Vol_Recent": 390580}, "moving_averages": {"MA_50": 36.903, "MA_200": 33.844}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.29, "PE_Ratio": 4.56, "PS_Ratio": 0.17, "PCF_Ratio": 2.52}}');
