INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (290, 'CSF', 'ETF', 'America', 'American Century Inflation Adju', 'American Century Inflation Adjusted Bond Fund Investor Class', 'DOLLAR', 'Blend', 'Small', 'American Century Investments', 'NGM', 'Small Blend', 63572452, 0.0101, '2014-07-31', NULL, 'The investment seeks total return and inflation protection consistent with investment in inflation-indexed securities. Under normal market conditions, the fund invests at least 80% of its net assets in inflation-adjusted bonds. It also may invest in derivative instruments such as futures contracts and swap agreements (including, but not limited to, inflation swap agreements and credit default swap agreements), bank loans, securities backed by mortgages or other assets and collateralized debt obligations. The fund may invest in U.S. Treasury futures, inflation swap agreements and credit default swap agreements to manage duration, inflation and credit exposure.', 0.0038, 0.004, 5351, 7070, 62.842, 60.743, 0.9958, 0, 1.94, 8.54, 15.86, 1, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 63572452, "Yield_Rate": 0.0101, "Expense_Net": 0.0038, "Benchmark_Exp": 0.004, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5351, "Vol_Recent": 7070}, "moving_averages": {"MA_50": 62.842, "MA_200": 60.743}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9958}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_