INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (294, 'CURE', 'ETF', 'U.S.', 'American Century Mid Cap Value ', 'American Century Mid Cap Value Fund A Class', 'US_DOLLAR', 'Value', 'Large', 'American Century Investments', 'PCX', 'Trading--Leveraged Equity', 167176864, 0.0002, '2011-06-15', 2.28, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s net assets in medium size companies. The portfolio managers consider medium size companies to include those whose market capitalizations at the time of purchase are within the capitalization range of the Russell 3000© Index, excluding the largest 100 such companies.', 0.0101, 0.009, 88516, 86190, 115.98, 105.661, NULL, NULL, 4.99, 15.97, 27.2, 1.85, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 167176864, "Yield_Rate": 0.0002, "Expense_Net": 0.0101, "Benchmark_Exp": 0.009, "Turnover_Ratio": 2.28}', '{"volume_metrics": {"Vol_3M": 88516, "Vol_Recent": 86190}, "moving_averages": {"MA_50": 115.98, "MA_200": 105.661}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.99, "PE_Ratio": 27.2, "PS_Ratio": 1.85, "PCF_Ratio": 15.97}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (295, 'CUT', 'ETF', 'United States', 'American Century Value - C Cl', 'American Century Value Fund C Class', 'USD', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Natural Resources', 110709920, 0.0147, '2007-11-09', 0.1, 'The investment seeks long-term capital growth; income is a secondary objective. In selecting stocks for the fund, the portfolio managers look for companies of all sizes whose stock price may not reflect the company''s value. The managers attempt to purchase the stocks of these undervalued companies and hold each stock until the price has increased to, or is higher than, a level the managers believe more accurately reflects the fair value of the company. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0061, 0.0048, 12275, 8850, 36.559, 37.394, 0.9964, 0, 2.12, 8.61, 18.07, 1.29, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 110709920, "Yield_Rate": 0.0147, "Expense_Net": 0.0061, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 12275, "Vol_Recent": 8850}, "moving_averages": {"MA_50": 36.559, "MA_200": 37.394}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9964}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.12, "PE_Ratio": 18.07, "PS_Ratio": 1.29, "PCF_Ratio": 8.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (296, 'CVY', 'ETF', 'U.S.', 'American Century Inv, NT Divers', 'American Century NT Diversified Bond Fund G Class', 'US_DOLLAR', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Allocation--70% to 85% Equity', 133014936, 0.0268, '2006-09-21', 1.76, 'The investment seeks a high level of income by investing in non-money market debt securities. Under normal market conditions, the fund invests at least 80% of its net assets in high- and medium-grade, non-money market debt securities. It invests most of its assets in investment-grade securities. The weighted average maturity of the fund''s portfolio must be three and one-half years or longer.', 0.0094, 0.0052, 7461, 8630, 24.407, 24.057, NULL, NULL, 1.44, 6.15, 10.65, 0.95, 8.15, 3.61, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 133014936, "Yield_Rate": 0.0268, "Expense_Net": 0.0094, "Benchmark_Exp": 0.0052, "Turnover_Ratio": 1.76}', '{"volume_metrics": {"Vol_3M": 7461, "Vol_Recent": 8630}, "moving_averages": {"MA_50": 24.407, "MA_200": 24.057}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.15, "Duration_Yrs": 3.61}}', '{"valuation_metrics": {"PB_Ratio": 1.44, "PE_Ratio": 10.65, "PS_Ratio": 0.95, "PCF_Ratio": 6.15}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (297, 'CWB', 'ETF', 'U.S.', 'American Century Inv, NT Equity', 'American Century NT Equity Growth Fund G Class', 'USD', NULL, NULL, 'American Century Investments', 'PCX', 'Convertibles', 6802137600, 0.0219, '2009-04-14', 0.41, 'The investment seeks long-term capital growth. In selecting stocks for the fund, the portfolio managers use quantitative and qualitative management techniques in a multi-step process. Under normal market conditions, at least 80% of the fund''s net assets will be invested in equity securities. The portfolio managers generally sell a stock when they believe it has become less attractive relative to other opportunities, its risk characteristics outweigh its return opportunity or specific events alter its prospects.', 0.004, 0.0057, 878659, 1.09961e+06, 86.981, 85.728, NULL, NULL, NULL, NULL, NULL, NULL, 4.24, 1.72, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 6802137600, "Yield_Rate": 0.0219, "Expense_Net": 0.004, "Benchmark_Exp": 0.0057, "Turnover_Ratio": 0.41}', '{"volume_metrics": {"Vol_3M": 878659, "Vol_Recent": 1099610}, "moving_averages": {"MA_50": 86.981, "MA_200": 85.728}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.24, "Duration_Yrs": 1.72}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (299, 'CWS', 'ETF', 'U.S.', 'American Century Inv, NT Large ', 'American Century NT Focused Large Cap Value Fund G Class', 'Usd', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Mid-Cap Growth', 28921190, 0.0026, '2016-09-20', NULL, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s assets in securities of large capitalization companies. For purposes of this 80% test, the advisors define large capitalization companies as those with capitalizations within the range of the Russell 1000© Index. In selecting stocks for the fund, the portfolio managers look for companies whose stock price may not adequately reflect the company''s value.', 0.0077, 0.0046, 1551, 1550, 48.888, 47.147, NULL, NULL, 4.7, 18.13, 27.32, 3.19, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 28921190, "Yield_Rate": 0.0026, "Expense_Net": 0.0077, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1551, "Vol_Recent": 1550}, "moving_averages": {"MA_50": 48.888, "MA_200": 47.147}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.7, "PE_Ratio": 27.32, "PS_Ratio": 3.19, "PCF_Ratio": 18.13}}');
