INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (320, 'DBJP', 'ETF', 'America', 'American Century Short Duration', 'American Century Short Duration Fund C Class', 'AmericanDollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Japan Stock', 196448480, 0.0239, '2011-06-09', 0.12, 'The investment seeks to maximize total return; as a secondary objective, the fund seeks a high level of income. The fund invests at least 65% of its assets in investment-grade, non-money market debt securities. No more than 10% of the fund''s assets may be invested in non-dollar denominated debt securities. The weighted average duration of the fund''s portfolio must be three years or shorter.', 0.0046, 0.004, 12011, 25660, 50.587, 49.504, NULL, NULL, 1.46, 9.93, 17.28, 1.16, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 196448480, "Yield_Rate": 0.0239, "Expense_Net": 0.0046, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 12011, "Vol_Recent": 25660}, "moving_averages": {"MA_50": 50.587, "MA_200": 49.504}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.46, "PE_Ratio": 17.28, "PS_Ratio": 1.16, "PCF_Ratio": 9.93}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (321, 'DBLV', 'ETF', 'U.S.A.', 'American Century Select - Class', 'American Century Select Fund C Class', 'US Dollar', 'Value', 'Large', 'American Century Investments', 'PCX', 'Large Value', 48242588, 0.0107, '2011-10-04', NULL, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.0091, 0.0034, 701, 430, 97.267, 94.469, NULL, NULL, 2.15, 13.91, 19.58, 1.76, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 48242588, "Yield_Rate": 0.0107, "Expense_Net": 0.0091, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 701, "Vol_Recent": 430}, "moving_averages": {"MA_50": 97.267, "MA_200": 94.469}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.15, "PE_Ratio": 19.58, "PS_Ratio": 1.76, "PCF_Ratio": 13.91}}');
