INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (322, 'DBMF', 'ETF', 'U.S.A.', NULL, 'Advisors Capital Small/Mid Cap Fund', 'US$', 'Blend', 'Large', 'Advisors Capital', 'PCX', 'Managed Futures', 53879924, 0.0071, '2019-05-07', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its assets (defined as net assets plus borrowing for investment purposes) in the securities of small- capitalization and mid-capitalization companies. It invests primarily in companies located in the United States, but may invest in foreign issuers. The Sub-Advisor''s philosophy is to invest long-term in what the advisor believes are relatively attractively-valued, conservatively-structured, competitively-advantaged, dynamic companies with growing free cash flow and honest, competent leadership.', 0.0085, 0.0087, 10116, 8180, 28.462, 28.195, NULL, NULL, 2.43, 12.86, 24.5, 1.9, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 53879924, "Yield_Rate": 0.0071, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10116, "Vol_Recent": 8180}, "moving_averages": {"MA_50": 28.462, "MA_200": 28.195}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.43, "PE_Ratio": 24.5, "PS_Ratio": 1.9, "PCF_Ratio": 12.86}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (324, 'DBOC', 'ETF', 'us', 'American Century Short Duration', 'American Century Short Duration Fund R Class', 'AmericanDollar', 'Blend', 'Large', 'American Century Investments', 'BTS', 'Large Blend', 38711632, NULL, '2020-09-30', NULL, 'The investment seeks to maximize total return; as a secondary objective, the fund seeks a high level of income. The fund invests at least 65% of its assets in investment-grade, non-money market debt securities. No more than 10% of the fund''s assets may be invested in non-dollar denominated debt securities. The weighted average duration of the fund''s portfolio must be three years or shorter.', 0.0079, 0.0036, 11164, 1240, 29.561, 28.718, 0.9953, 0, 4.85, 18.34, 27.73, 3.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 38711632, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11164, "Vol_Recent": 1240}, "moving_averages": {"MA_50": 29.561, "MA_200": 28.718}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.85, "PE_Ratio": 27.73, "PS_Ratio": 3.04, "PCF_Ratio": 18.34}}');
