INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (333, 'DDWM', 'ETF', 'us', 'American Century Capital Value ', 'Advisors Capital Tactical Fixed Income Fund', 'Usd', 'Value', 'Large', 'Advisors Capital', 'BTS', 'Foreign Large Value', 161666384, 0.0352, '2016-01-07', 0.17, 'The investment seeks total return with capital preservation as a secondary objective. Under normal circumstances, the fund invests at least 80% of its assets (defined as net assets plus borrowing for investment purposes) in fixed-income securities. Fixed income securities are selected without restriction as to maturity, credit quality (including high yield or junk bonds), currency, issuer country or capitalization. However, preferred stocks are limited to 30% of the fund''s portfolio.', 0.004, 0.0046, 15204, 11330, 30.421, 30.556, 0.9994, 0, 1.7, 8.68, 17.29, 1.27, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 161666384, "Yield_Rate": 0.0352, "Expense_Net": 0.004, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.17}', '{"volume_metrics": {"Vol_3M": 15204, "Vol_Recent": 11330}, "moving_averages": {"MA_50": 30.421, "MA_200": 30.556}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.7, "PE_Ratio": 17.29, "PS_Ratio": 1.27, "PCF_Ratio": 8.68}}');
