INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (353, 'DFNL', 'ETF', 'USA', 'Catalyst Multi-Strategy Fund Cl', 'Catalyst Multi-Strategy Fund Class A', 'US$', 'Value', 'Large', 'Catalyst Mutual Funds', 'BTS', 'Financial', 208101856, 0.0116, '2017-01-11', 0.2, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective (i) by entering into both long and short positions in futures contracts to implement a diversified managed futures program, (ii) by holding cash, cash equivalents, and investment grade short-term fixed income securities primarily as collateral to these derivative positions and (iii) by using monies in excess of collateral requirements to invest, either directly or indirectly through affiliated and non-affiliated mutual funds and exchange traded funds ("ETFs"), in fixed income securities.', 0.0064, 0.0038, 11909, 9260, 31.691, 30.185, 1, 0, 1.33, NULL, 12.55, 1.24, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 208101856, "Yield_Rate": 0.0116, "Expense_Net": 0.0064, "Benchmark_Exp": 0.0038, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 11909, "Vol_Recent": 9260}, "moving_averages": {"MA_50": 31.691, "MA_200": 30.185}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.33, "PE_Ratio": 12.55, "PS_Ratio": 1.24, "PCF_Ratio": null}}');
