INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (377, 'DJUN', 'ETF', 'United States', 'Aperture Discover Equity Fund I', 'Aperture Discover Equity Fund Institutional Shares', 'US_DOLLAR', 'Blend', 'Large', 'Aperture Investors', 'BTS', NULL, 33544088, NULL, '2020-06-19', NULL, 'The investment seeks a return in excess of the Russell 2000 Total Return Index. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities. The equity securities in which it primarily invests are common stocks of North American companies, including initial public offerings ("IPOs"). The fund may invest in both small capitalization companies and medium capitalization companies, and may invest in companies located in both the U.S. and non-U.S. developed market countries. It is non-diversified.', 0.0085, NULL, 6327, 23200, 34.044, 33.49, NULL, NULL, 4.43, 17.58, 26.49, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 33544088, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6327, "Vol_Recent": 23200}, "moving_averages": {"MA_50": 34.044, "MA_200": 33.49}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.43, "PE_Ratio": 26.49, "PS_Ratio": 2.96, "PCF_Ratio": 17.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (378, 'DMAR', 'ETF', 'U.S.A.', 'Azzad Ethical Fund', 'Azzad Ethical Fund', 'usd', 'Blend', 'Large', 'Azzad Fund', 'BTS', NULL, 50773844, NULL, '2021-03-18', NULL, 'The investment seeks to provide shareholders with long-term total returns using means that are consistent with the Adviser''s ethical principles. The ethical fund seeks to achieve its objective by investing primarily in common stocks of mid-capitalization companies that the Adviser believes are high quality and/or exhibit above-average growth potential, which, for the purposes of this ethical fund, typically are companies with market capitalizations similar to those issuers included in the index over the last 13 months at the time of purchase. It will invest at least 80% of its assets in securities meeting the fund''s ethical investment criteria.', 0.0085, NULL, 6096, 12150, 31.496, 31.023, NULL, NULL, 4.32, 17.19, 26.07, 2.9, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 50773844, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6096, "Vol_Recent": 12150}, "moving_averages": {"MA_50": 31.496, "MA_200": 31.023}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.32, "PE_Ratio": 26.07, "PS_Ratio": 2.9, "PCF_Ratio": 17.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (380, 'DMCY', 'ETF', 'usa', 'The Adirondack Small Cap Fund', 'Adirondack Small Cap Fund', 'US Dollar', 'Blend', 'Large', 'Adirondack Funds', 'PCX', NULL, 1288778, NULL, '2021-03-25', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its objective by investing in a diversified portfolio of undervalued common stocks of small capitalization companies as determined by the fund''s investment advisor. Small capitalization companies are defined by the investment advisor as issuers that, have a market capitalization that is within or below the range of companies in the Russell 2000 Index. Under normal circumstances, at least 80% of the fund''s total assets will be invested in common stocks of small capitalization companies. The fund may invest up to 15% of its total assets in sponsored ADRs issued by foreign companies.', 0.005, NULL, 548, 300, 26.216, 26.375, 0.9937, 0, 1.86, 10.57, 20.56, 1.52, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 1288778, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 548, "Vol_Recent": 300}, "moving_averages": {"MA_50": 26.216, "MA_200": 26.375}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9937}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.86, "PE_Ratio": 20.56, "PS_Ratio": 1.52, "PCF_Ratio": 10.57}}');
