INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (391, 'DPST', 'ETF', 'U.S.', 'ACM Dynamic Opportunity Fund - ', 'ACM Dynamic Opportunity Fund Class A', 'AmericanDollar', 'Value', 'Small', 'ACM', 'PCX', 'Trading--Leveraged Equity', 477719424, 0.006, '2015-08-19', 3.31, 'The investment seeks long-term capital appreciation with a short-term focus on capital preservation. To pursue its investment objective, the fund invests in domestic and foreign (including emerging markets) equity securities of any market capitalization. It may also take long or short positions in index exchange traded funds ("ETFs") to hedge the fund''s equity portfolio. The fund''s adviser, Ascendant Capital Management, LLC (the "Adviser"), selects equity securities for the fund''s portfolio that are experiencing meaningful breakouts.', 0.01, 0.009, 1203285, 988400, 52.741, 47.107, NULL, NULL, 1.36, NULL, 14.36, 3.6, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 477719424, "Yield_Rate": 0.006, "Expense_Net": 0.01, "Benchmark_Exp": 0.009, "Turnover_Ratio": 3.31}', '{"volume_metrics": {"Vol_3M": 1203285, "Vol_Recent": 988400}, "moving_averages": {"MA_50": 52.741, "MA_200": 47.107}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.36, "PE_Ratio": 14.36, "PS_Ratio": 3.6, "PCF_Ratio": null}}');
