INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (397, 'DRW', 'ETF', 'usa', 'American Century Disciplined Gr', 'American Century Disciplined Growth Fund Class R', 'AmericanDollar', 'Value', 'Large', 'American Century Investments', 'PCX', 'Global Real Estate', 60848824, 0.0587, '2007-06-05', 0.39, 'The investment seeks long-term capital growth. In selecting stocks for the fund, the portfolio managers initially identify an eligible universe of growth stocks then use quantitative and qualitative management techniques in a multi-step process. First, the managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures. Second, the portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0058, 0.0053, 11361, 9110, 25.23, 26.367, 0.9918, 0, 0.97, 10.46, 10.44, 1.44, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 60848824, "Yield_Rate": 0.0587, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.39}', '{"volume_metrics": {"Vol_3M": 11361, "Vol_Recent": 9110}, "moving_averages": {"MA_50": 25.23, "MA_200": 26.367}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9918}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.97, "PE_Ratio": 10.44, "PS_Ratio": 1.44, "PCF_Ratio": 10.46}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (399, 'DSJA', 'ETF', 'UNITED_STATES', 'American Century Disciplined Gr', 'American Century Disciplined Growth Fund Investor Class', 'USD', 'Blend', 'Large', 'American Century Investments', 'BTS', 'Large Blend', 4987178, NULL, '2020-12-31', NULL, 'The investment seeks long-term capital growth. In selecting stocks for the fund, the portfolio managers initially identify an eligible universe of growth stocks then use quantitative and qualitative management techniques in a multi-step process. First, the managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures. Second, the portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0079, 0.0036, 433, 320, 29.676, 28.39, NULL, NULL, 4.7, 18.08, 27.31, 3.01, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 4987178, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 433, "Vol_Recent": 320}, "moving_averages": {"MA_50": 29.676, "MA_200": 28.39}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.7, "PE_Ratio": 27.31, "PS_Ratio": 3.01, "PCF_Ratio": 18.08}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (400, 'DSOC', 'ETF', 'US', 'Aperture Discover Equity Fund C', 'Aperture Discover Equity Fund Class X Shares', 'DOLLAR', 'Blend', 'Large', 'Aperture Investors', 'BTS', 'Large Blend', 22197800, NULL, '2020-09-30', NULL, 'The investment seeks a return in excess of the Russell 2000 Total Return Index. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities. The equity securities in which it primarily invests are common stocks of North American companies, including initial public offerings ("IPOs"). The fund may invest in both small capitalization companies and medium capitalization companies, and may invest in companies located in both the U.S. and non-U.S. developed market countries. It is non-diversified.', 0.008, 0.0036, 7124, 290, 32.223, 30.682, 0.9947, 0, 4.85, 18.34, 27.74, 3.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 22197800, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7124, "Vol_Recent": 290}, "moving_averages": {"MA_50": 32.223, "MA_200": 30.682}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9947}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.85, "PE_Ratio": 27.74, "PS_Ratio": 3.04, "PCF_Ratio": 18.34}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (401, 'DSPC', 'ETF', 'US', 'Aberdeen Dynamic Dividend Fund ', 'Aberdeen Dynamic Dividend Fund Institutional Class', 'usd', NULL, NULL, 'Aberdeen', 'PCX', NULL, NULL, NULL, '2021-05-18', NULL, 'The investment seeks high current dividend income that qualifies for the reduced U.S. federal income tax rates created by the "Jobs and Growth Tax Relief Reconciliation Act of 2003," while also focusing on total return for long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets in the equity securities of certain domestic and foreign corporations that pay dividend income that the advisor believes are undervalued relative to the market and to the securities'' historic valuations.', 0.0075, NULL, 1279, 1340, 23.418, 24.98, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1279, "Vol_Recent": 1340}, "moving_averages": {"MA_50": 23.418, "MA_200": 24.98}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (402, 'DSTL', 'ETF', 'usa', 'North Square Advisory Research ', 'North Square Advisory Research All Cap Value Fund I', 'Usd', 'Blend', 'Large', 'North Square', 'PCX', 'Large Blend', 357571968, 0.012, '2018-10-23', 0.58, 'The investment seeks long term capital appreciation. Under normal circumstances, the fund will invest in at least 80% of its net assets in equity securities of companies of any size including small, mid and large-capitalization companies. The fund''s investments in equity securities may include common stock, preferred securities and convertible securities. While the fund invests primarily in equity securities of U.S. issuers, it may invest in securities of foreign issuers, including those in emerging markets, in keeping with the fund''s investment objective, is not expected to exceed 20% of its net assets.', 0.0039, 0.0036, 69066, 65360, 43.025, 41.557, 0.9995, 0, 5, 14.29, 24.04, 2.06, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 357571968, "Yield_Rate": 0.012, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.58}', '{"volume_metrics": {"Vol_3M": 69066, "Vol_Recent": 65360}, "moving_averages": {"MA_50": 43.025, "MA_200": 41.557}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5, "PE_Ratio": 24.04, "PS_Ratio": 2.06, "PCF_Ratio": 14.29}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (403, 'DSTX', 'ETF', 'USA', 'Vaughan Nelson International Sm', 'Vaughan Nelson International Small Cap Fund Investor Class', 'US$', 'Blend', 'Large', 'Vaughan Nelson', 'PCX', NULL, 20610714, NULL, '2020-12-14', NULL, 'The investment seeks long term capital appreciation. Under normal circumstances, the fund will invest at least 80% of its net assets (including amounts borrowed for investment purposes) in equity securities of small capitalization companies and will invest at least 75% of its net assets in securities of companies located outside of the United States. The fund''s manager considers small capitalization companies to be companies with market capitalizations within the range of those companies included in the MSCI EAFE Small Cap Index at the time of purchase.', 0.0055, NULL, 3270, 9480, 25.632, 26.558, 0.9982, 0, 2.57, 8.97, 19.96, 1.19, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 20610714, "Yield_Rate": null, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3270, "Vol_Recent": 9480}, "moving_averages": {"MA_50": 25.632, "MA_200": 26.558}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9982}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.57, "PE_Ratio": 19.96, "PS_Ratio": 1.19, "PCF_Ratio": 8.97}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (404, 'DTEC', 'ETF', 'usa', 'Vaughan Nelson Emerging Markets', 'Vaughan Nelson Emerging Markets Opportunities Fund Investor Class', 'usd', 'Growth', 'Large', 'Vaughan Nelson', 'PCX', 'Technology', 230687152, 0.0035, '2017-12-28', NULL, 'The investment seeks long term capital appreciation. Under normal circumstances, the fund will invest at least 80% of its net assets (including amounts borrowed for investment purposes) in equity securities of companies that are either listed, domiciled, or conduct a meaningful amount of business in emerging markets. The fund''s advisor defines companies conducting a meaningful amount of business in emerging markets as those companies that derive at least 50% of revenues or net profits from, or have at least 50% of assets or production capacities in, emerging market countries.', 0.005, 0.0053, 16246, 17590, 50.13, 48.193, 0.9984, 0, 5.65, 24.67, 39.59, 5.54, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 230687152, "Yield_Rate": 0.0035, "Expense_Net": 0.005, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 16246, "Vol_Recent": 17590}, "moving_averages": {"MA_50": 50.13, "MA_200": 48.193}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9984}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.65, "PE_Ratio": 39.59, "PS_Ratio": 5.54, "PCF_Ratio": 24.67}}');
