INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (431, 'DYNF', 'ETF', 'us', 'AB Global Real Estate Investmen', 'AB Global Real Estate Investment Fund Class I', 'Dollar', 'Blend', 'Large', 'AllianceBernstein', 'PCX', NULL, 77945936, 0.0141, '2019-03-19', 1.75, 'The investment seeks total return from long-term growth of capital and income. Under normal circumstances, the fund invests at least 80% of its net assets in the equity securities of real estate investment trusts, or REITs, and other real estate industry companies, such as real estate operating companies, or REOCs. It invests in U.S. and non-U.S. issuers. Under normal circumstances, it invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. In addition, the fund invests, under normal circumstances, in the equity securities of companies located in at least three countries.', 0.003, NULL, 5416, 8700, 38.288, 36.405, 0.9956, 0, 3.51, 13.77, 26.07, 2.16, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 77945936, "Yield_Rate": 0.0141, "Expense_Net": 0.003, "Benchmark_Exp": null, "Turnover_Ratio": 1.75}', '{"volume_metrics": {"Vol_3M": 5416, "Vol_Recent": 8700}, "moving_averages": {"MA_50": 38.288, "MA_200": 36.405}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9956}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.51, "PE_Ratio": 26.07, "PS_Ratio": 2.16, "PCF_Ratio": 13.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (432, 'DZZ', 'ETF', 'us', 'Water Island Diversified Event-', 'Water Island Event-Driven Fund Class C', 'US Dollar', NULL, NULL, 'Arbitrage Fund', 'PCX', 'Trading--Inverse Commodities', 7408969, NULL, '2008-02-27', NULL, 'The investment seeks to achieve capital growth. The fund invests in equity and debt and debt-like instruments (including high yield bonds commonly known as "junk bonds") of companies whose prices the fund''s investment adviser believes are or will be impacted by a corporate event. Specifically, the fund employs investment strategies designed to capture price movements generated by corporate events such as mergers, acquisitions, asset sales, restructurings, refinancings, recapitalizations, reorganizations or other special situations (referred to as "event-driven opportunities"). It is non-diversified.', 0.0075, 0.0085, 6824, 6570, 2.794, 2.839, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 7408969, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0085, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6824, "Vol_Recent": 6570}, "moving_averages": {"MA_50": 2.794, "MA_200": 2.839}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (433, 'EAGG', 'ETF', 'U.S.A.', 'American Funds EuroPacific Grow', 'American Funds EuroPacific Growth Fund Class F-1', 'Usd', 'Blend', 'Medium', 'American Funds', 'PCX', NULL, 1274424320, 0.0133, '2018-10-18', 3.84, 'The investment seeks long-term growth of capital. The fund invests primarily in common stocks of issuers in Europe and the Pacific Basin that the investment adviser believes have the potential for growth. Growth stocks are stocks that the investment adviser believes have the potential for above-average capital appreciation. It normally will invest at least 80% of its net assets in securities of issuers in Europe and the Pacific Basin. The fund may invest a portion of its assets in common stocks and other securities of companies in emerging markets.', 0.001, NULL, 155448, 144820, 55.047, 55.151, NULL, NULL, NULL, NULL, NULL, NULL, 8.01, 6.33, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1274424320, "Yield_Rate": 0.0133, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 3.84}', '{"volume_metrics": {"Vol_3M": 155448, "Vol_Recent": 144820}, "moving_averages": {"MA_50": 55.047, "MA_200": 55.151}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.01, "Duration_Yrs": 6.33}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (434, 'EAOA', 'ETF', 'UNITED_STATES', 'American Century Emerging Marke', 'American Century Emerging Markets Fund R5 Class', 'US_DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 19857928, NULL, '2020-06-12', NULL, 'The investment seeks capital growth. The fund invests at least 80% of its net assets in equity securities of companies located in emerging market countries. The manager considers an emerging market country to be any country other than a developed country. The fund invests in securities denominated in foreign currencies and in foreign securities that are represented in the U.S. securities markets by American Depositary Receipts (ADRs) or similar depositary arrangements.', 0.0018, NULL, 1601, 1650, 34.044, 33.229, NULL, NULL, 2.86, 14.58, 24.46, 2.09, 7.97, 6.34, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 19857928, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1601, "Vol_Recent": 1650}, "moving_averages": {"MA_50": 34.044, "MA_200": 33.229}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.34}}', '{"valuation_metrics": {"PB_Ratio": 2.86, "PE_Ratio": 24.46, "PS_Ratio": 2.09, "PCF_Ratio": 14.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (435, 'EAOK', 'ETF', 'U.S.A.', 'Invesco European Growth Fund Cl', 'Invesco European Growth Fund Class R6', 'US Dollar', 'Blend', 'Large', 'Invesco', 'BTS', NULL, 5504113, NULL, '2020-06-12', NULL, 'The investment seeks long-term growth of capital. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in securities of European issuers, and in derivatives and other instruments that have economic characteristics similar to such securities. It invests primarily in equity securities and depositary receipts. The fund may invest in the securities of issuers of all capitalization sizes and may invest a significant amount of its net assets in the securities of small- and mid-capitalization issuers.', 0.0018, NULL, 5733, 930, 27.859, 27.632, NULL, NULL, 2.86, 14.58, 24.46, 2.09, 7.97, 6.34, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 5504113, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5733, "Vol_Recent": 930}, "moving_averages": {"MA_50": 27.859, "MA_200": 27.632}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.34}}', '{"valuation_metrics": {"PB_Ratio": 2.86, "PE_Ratio": 24.46, "PS_Ratio": 2.09, "PCF_Ratio": 14.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (436, 'EAOM', 'ETF', 'usa', 'American Century Emerging Marke', 'American Century Emerging Markets Debt Fund I Class', 'US Dollar', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 5721704, NULL, '2020-06-12', NULL, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in fixed income instruments of issuers that are economically tied to emerging markets. It will invest in debt instruments issued by foreign governments and corporations. The fund may invest without limitation in both investment grade and high-yield ("junk bonds") debt securities. It also invests in derivative instruments. The fund may use foreign currency exchange contracts to shift its investment exposure from one currency into another, for hedging purposes or to enhance returns.', 0.0018, NULL, 1100, 780, 29.049, 28.722, NULL, NULL, 2.86, 14.58, 24.46, 2.09, 7.97, 6.34, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 5721704, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1100, "Vol_Recent": 780}, "moving_averages": {"MA_50": 29.049, "MA_200": 28.722}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.34}}', '{"valuation_metrics": {"PB_Ratio": 2.86, "PE_Ratio": 24.46, "PS_Ratio": 2.09, "PCF_Ratio": 14.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (437, 'EAOR', 'ETF', 'us', 'Equity Income Fund Class G', 'American Century Equity Income Fund G Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 7702439, NULL, '2020-06-12', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The portfolio managers look for equity securities of companies with a favorable income-paying history that have prospects for income payments to continue or increase. The portfolio managers also look for equity securities of companies that they believe are undervalued and have the potential for an increase in price. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0018, NULL, 1508, 860, 31.491, 30.93, NULL, NULL, 2.86, 14.58, 24.46, 2.09, 7.97, 6.34, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 7702439, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1508, "Vol_Recent": 860}, "moving_averages": {"MA_50": 31.491, "MA_200": 30.93}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.34}}', '{"valuation_metrics": {"PB_Ratio": 2.86, "PE_Ratio": 24.46, "PS_Ratio": 2.09, "PCF_Ratio": 14.58}}');
