INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (496, 'EMTY', 'ETF', 'usa', 'AllianzGI International Value F', 'Virtus NFJ International Value Fund Class A', 'usd', NULL, NULL, 'Virtus', 'PCX', 'Trading--Inverse Equity', 6380121, NULL, '2017-11-14', NULL, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 65% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities (such as preferred stocks, convertible securities and warrants) of non-U.S. companies with market capitalizations greater than $1 billion. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends).', 0.0066, 0.0092, 6532, 5690, 15.178, 16.231, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 6380121, "Yield_Rate": null, "Expense_Net": 0.0066, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6532, "Vol_Recent": 5690}, "moving_averages": {"MA_50": 15.178, "MA_200": 16.231}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
