INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (441, 'EBIZ', 'ETF', 'United States', 'Acadian Emerging Markets Portfo', 'Acadian Emerging Markets Portfolio Investor Class', 'AmericanDollar', 'Growth', 'Large', 'Acadian Funds', 'NGM', NULL, 229761552, 0.0079, '2018-11-27', 0.4201, 'The investment seeks long-term capital appreciation by investing primarily in common stocks of emerging market country issuers. The fund will invest primarily in common stocks but also may invest in other types of equity securities, including preferred stock. Under normal circumstances, it invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of issuers. The fund may also invest in securities of issuers located in industrialized countries.', 0.005, NULL, 19608, 22030, 31.119, 32.893, 0.9983, 0, 5.32, 10.76, 24.18, 2.16, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 229761552, "Yield_Rate": 0.0079, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": 0.4201}', '{"volume_metrics": {"Vol_3M": 19608, "Vol_Recent": 22030}, "moving_averages": {"MA_50": 31.119, "MA_200": 32.893}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.32, "PE_Ratio": 24.18, "PS_Ratio": 2.16, "PCF_Ratio": 10.76}}');
