INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (453, 'EDUT', 'ETF', 'America', 'American Century Equity Income ', 'American Century Equity Income Fund R6 Class', 'US_DOLLAR', 'Growth', 'Medium', 'American Century Investments', 'NGM', NULL, 13103614, NULL, '2020-07-10', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The portfolio managers look for equity securities of companies with a favorable income-paying history that have prospects for income payments to continue or increase. The portfolio managers also look for equity securities of companies that they believe are undervalued and have the potential for an increase in price. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.005, NULL, 4320, 4680, 10.648, 13.756, 0.9987, 0, 4.29, 21.21, 37.33, 3.27, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 13103614, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4320, "Vol_Recent": 4680}, "moving_averages": {"MA_50": 10.648, "MA_200": 13.756}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.29, "PE_Ratio": 37.33, "PS_Ratio": 3.27, "PCF_Ratio": 21.21}}');
