INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (475, 'EGIS', 'ETF', 'U.S.A.', 'American Century Sustainable Eq', 'American Century Sustainable Equity Fund A Class', 'usd', 'Blend', 'Large', 'American Century Investments', 'BTS', 'Large Blend', 16199240, NULL, '2020-11-17', NULL, 'The investment seeks long-term capital growth; income is a secondary objective. The fund will generally invest in large capitalization companies the advisor believes show sustainable business improvement using a proprietary multi-factor model that combines fundamental measures of a stock''s value and growth potential with ESG metrics. The model assigns each security a financial metrics score and an ESG score that are combined to create an overall score. To measure growth, the managers may use the rate of growth of a company''s earnings and cash flow and changes in its earnings estimates.', 0.0075, 0.0036, 5109, 10130, 34.521, 32.651, NULL, NULL, 3.57, 15.29, 22.45, 2.33, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 16199240, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5109, "Vol_Recent": 10130}, "moving_averages": {"MA_50": 34.521, "MA_200": 32.651}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.57, "PE_Ratio": 22.45, "PS_Ratio": 2.33, "PCF_Ratio": 15.29}}');
