INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (489, 'EMIF', 'ETF', 'us', 'AllianzGI Focused Growth Fund C', 'Virtus AllianzGI Focused Growth Fund R6', 'DOLLAR', 'Value', 'Large', 'Virtus', 'NGM', 'Diversified Emerging Mkts', 15940076, 0.0409, '2009-06-16', 0.27, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by normally investing primarily in equity securities of U.S. companies with market capitalizations of at least $1 billion. It may also invest up to 20% of its assets in non-U.S. securities (but no more than 10% in any one non-U.S. country or 10% in emerging market securities). The fund is non-diversified.', 0.006, 0.0056, 3332, 3820, 24.253, 24.381, NULL, NULL, 0.91, 5.07, 12.32, 1.05, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 15940076, "Yield_Rate": 0.0409, "Expense_Net": 0.006, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.27}', '{"volume_metrics": {"Vol_3M": 3332, "Vol_Recent": 3820}, "moving_averages": {"MA_50": 24.253, "MA_200": 24.381}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.91, "PE_Ratio": 12.32, "PS_Ratio": 1.05, "PCF_Ratio": 5.07}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (490, 'EMLC', 'ETF', 'UNITED_STATES', 'Yorktown Growth Fund Class A', 'Yorktown Growth Fund Class A', 'US$', NULL, NULL, 'Yorktown Funds', 'PCX', 'Emerging-Markets Local-Currency Bond', 3553029120, 0.0492, '2010-07-22', 0.4, 'The investment seeks growth of capital. The fund invests in securities that, in the opinion of Yorktown Management & Research Company, Inc. (the "Adviser"), offer the opportunity for growth of capital. It can include stocks of any size, within any sector, and at times the Adviser may emphasize one or more particular sectors. The fund may also invest in other U.S. and foreign securities, including securities convertible into common stock and securities issued through private placements, and securities issued by investment companies ("underlying funds").', 0.003, 0.0055, 2093629, 1.88909e+06, 29.459, 30.773, 0, 0.9991, NULL, NULL, NULL, NULL, 7.25, 5.09, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 3553029120, "Yield_Rate": 0.0492, "Expense_Net": 0.003, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.4}', '{"volume_metrics": {"Vol_3M": 2093629, "Vol_Recent": 1889090}, "moving_averages": {"MA_50": 29.459, "MA_200": 30.773}}', '{"asset_allocation": {"Bond_Weight": 0.9991, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.25, "Duration_Yrs": 5.09}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (508, 'EQL', 'ETF', 'US', 'Archer Focus Fund', 'Archer Focus Fund', 'DOLLAR', 'Blend', 'Large', 'Archer', 'PCX', 'Large Blend', 210116528, 0.0177, '2009-07-06', NULL, 'The investment seeks long-term growth of capital. The fund is a "non-diversified" portfolio investing in equity securities, primarily in common stocks of domestic companies and ADRs of foreign companies, that are selected for their long-term growth potential. It may invest in companies of any size. Under normal conditions, the fund will normally hold a core position of 50 common stocks, although the number of securities held by it may occasionally exceed this range. It is non-diversified.', 0.0028, 0.0036, 3358, 2870, 104.735, 100.158, 0.998, 0, 3.45, 15.95, 26.06, 2.64, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 210116528, "Yield_Rate": 0.0177, "Expense_Net": 0.0028, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3358, "Vol_Recent": 2870}, "moving_averages": {"MA_50": 104.735, "MA_200": 100.158}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.45, "PE_Ratio": 26.06, "PS_Ratio": 2.64, "PCF_Ratio": 15.95}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (491, 'EMLP', 'ETF', 'U.S.', 'Alger Global Focus Fund Class I', 'Alger Global Focus Fund Class I', 'Usd', 'Value', 'Medium', 'Alger', 'PCX', 'Energy Limited Partnership', 2059332096, 0.0354, '2012-06-20', 0.46, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities, including common stocks, American Depositary Receipts and Global Depositary Receipts, of global companies, which include both U.S. and foreign companies, and invests significantly (at least 40% - unless market conditions are not deemed favorable, in which case the fund would invest at least 30%) in foreign companies. It may invest in companies of any market capitalization, from large, well-established companies to small, emerging growth companies.', 0.0096, 0.0074, 195035, 176130, 24.696, 24.118, 0.9948, 0, 2.26, 7.78, 17.75, 1.66, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 2059332096, "Yield_Rate": 0.0354, "Expense_Net": 0.0096, "Benchmark_Exp": 0.0074, "Turnover_Ratio": 0.46}', '{"volume_metrics": {"Vol_3M": 195035, "Vol_Recent": 176130}, "moving_averages": {"MA_50": 24.696, "MA_200": 24.118}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9948}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.26, "PE_Ratio": 17.75, "PS_Ratio": 1.66, "PCF_Ratio": 7.78}}');
