INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (512, 'ERM', 'ETF', 'usa', 'Ariel Focus Fund Instl Cl', 'Ariel Focus Fund Institutional Class', 'DOLLAR', 'Value', 'Large', 'Ariel Investments', 'PCX', 'Large Value', 11289620, 0.0108, '2017-04-10', NULL, 'The investment seeks long-term capital appreciation. The fund invests primarily in equity securities of companies of any size in order to provide investors access to superior opportunities in companies of all market capitalizations. The essence of the fund''s strategy is a combination of patience and stock selection. The fund seeks to hold investments for a relatively long period of time-generally three to five years or more. It is non-diversified.', 0.0068, 0.0034, 1154, 1080, 25.506, 24.839, 0.9969, 0, 2.96, 12.41, 23.21, 1.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 11289620, "Yield_Rate": 0.0108, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1154, "Vol_Recent": 1080}, "moving_averages": {"MA_50": 25.506, "MA_200": 24.839}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9969}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.96, "PE_Ratio": 23.21, "PS_Ratio": 1.98, "PCF_Ratio": 12.41}}');
