INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (517, 'ESCR', 'ETF', 'UNITED_STATES', 'Alpha Fiduciary Quantitative St', 'Alpha Fiduciary Quantitative Strategy Fund', 'Usd', NULL, NULL, 'Alpha Fiduciary', 'BTS', 'Corporate Bond', 7784243, 0.0238, '2015-03-03', 0.57, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by investing primarily in a portfolio of exchange-traded funds ("ETFs") and equity index futures. It implements a quantitative trend-following strategy by generally holding long positions in S&P 500© Index ETF(s) and equity index futures that provide either long and/or short exposure to the equity markets. The Adviser''s quantitative strategy seeks to identify price trends in the equity markets as indicated by the S&P 500© reference index. It is non-diversified.', 0.0015, 0.0017, 683, 1740, 22.022, 22.038, NULL, NULL, NULL, NULL, NULL, NULL, 11.85, 8.29, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 7784243, "Yield_Rate": 0.0238, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.57}', '{"volume_metrics": {"Vol_3M": 683, "Vol_Recent": 1740}, "moving_averages": {"MA_50": 22.022, "MA_200": 22.038}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.85, "Duration_Yrs": 8.29}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (518, 'ESEB', 'ETF', 'U.S.A.', 'Invesco Floating Rate ESG Fund ', 'Invesco Floating Rate ESG Fund Class A', 'usd', NULL, NULL, 'Invesco', 'BTS', 'Emerging Markets Bond', 30574756, 0.0376, '2015-03-03', 0.26, 'The investment seeks total return, comprised of current income and capital appreciation. The fund invests under normal circumstances at least 80% of its net assets (plus any borrowings for investment purposes) in senior secured floating rate loans made by banks and other lending institutions and in senior secured floating rate debt instruments, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest up to 100% of its net assets in floating rate loans and floating rate debt securities that are determined to be below investment grade.', 0.0035, 0.0046, 1393, 3700, 21.182, 21.536, NULL, NULL, NULL, NULL, NULL, NULL, 12.58, 8.06, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 30574756, "Yield_Rate": 0.0376, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.26}', '{"volume_metrics": {"Vol_3M": 1393, "Vol_Recent": 3700}, "moving_averages": {"MA_50": 21.182, "MA_200": 21.536}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 12.58, "Duration_Yrs": 8.06}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
