INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (527, 'ESGY', 'ETF', 'U.S.', 'AllianzGI International Value F', 'Virtus NFJ International Value Fund Class P', 'US Dollar', 'Growth', 'Large', 'Virtus', 'PCX', 'Large Blend', 5204632, NULL, '2021-06-29', NULL, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 65% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities (such as preferred stocks, convertible securities and warrants) of non-U.S. companies with market capitalizations greater than $1 billion. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends).', 0.0039, 0.0036, 466, 1060, 43.885, 39.48, 1, 0, 11.32, 25.5, 37.84, 5.47, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 5204632, "Yield_Rate": null, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 466, "Vol_Recent": 1060}, "moving_averages": {"MA_50": 43.885, "MA_200": 39.48}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 11.32, "PE_Ratio": 37.84, "PS_Ratio": 5.47, "PCF_Ratio": 25.5}}');
