INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (566, 'FAPR', 'ETF', 'U.S.A.', 'AllianzGI Global Dynamic Alloca', 'Virtus AllianzGI Global Dynamic Allocation Fund Administrative Class', 'AmericanDollar', 'Blend', 'Large', 'Virtus', 'BTS', NULL, 121963960, NULL, '2021-04-15', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective through a combination of active allocation between asset classes and actively managed strategies within those asset classes. It allocates the fund''s investments among asset classes in response to changing market, economic, and political factors and events that the portfolio managers responsible for allocation believe may affect the value of the fund''s investments.', 0.0085, NULL, 8691, 9950, 31.779, 31.088, NULL, NULL, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 121963960, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8691, "Vol_Recent": 9950}, "moving_averages": {"MA_50": 31.779, "MA_200": 31.088}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (567, 'FAS', 'ETF', 'usa', 'Alger Funds II - Alger Responsi', 'Alger Responsible Investing Fund Class C', 'Dollar', 'Value', 'Large', 'Alger', 'PCX', 'Trading--Leveraged Equity', 3609033728, 0.0036, '2008-11-06', 2.47, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies of any size with an environmental, social and governance ("ESG") rating of average or above by a third-party ESG rating agency (an "ESG Rating Agency") that also demonstrate, in the view of the Manager, promising growth potential.', 0.0099, 0.009, 1647916, 2.0832e+06, 134.781, 114.353, NULL, NULL, 1.64, NULL, 12.67, 2.23, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 3609033728, "Yield_Rate": 0.0036, "Expense_Net": 0.0099, "Benchmark_Exp": 0.009, "Turnover_Ratio": 2.47}', '{"volume_metrics": {"Vol_3M": 1647916, "Vol_Recent": 2083200}, "moving_averages": {"MA_50": 134.781, "MA_200": 114.353}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.64, "PE_Ratio": 12.67, "PS_Ratio": 2.23, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (569, 'FAUG', 'ETF', 'US', 'The AB Portfolios - AB Growth F', 'AB Growth Fund Class I', 'US Dollar', 'Blend', 'Large', 'AllianceBernstein', 'BTS', NULL, 81310960, NULL, '2019-11-07', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in a domestic equity securities of companies selected by the fund''s Adviser for their growth potential with in various market sectors. When selecting securities, the Adviser looks for companies that have experienced management teams, strong market positions, and the potential to deliver greater-than-expected earnings growth rates. The fund has the flexibility to invest across the capitalization spectrum. It may enter into derivatives transactions, such as options, futures contracts, forwards and swaps.', 0.0085, NULL, 38637, 72590, 37.65, 36.822, 0.9936, 0, 4.43, 17.58, 26.49, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 81310960, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 38637, "Vol_Recent": 72590}, "moving_averages": {"MA_50": 37.65, "MA_200": 36.822}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9936}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.43, "PE_Ratio": 26.49, "PS_Ratio": 2.96, "PCF_Ratio": 17.58}}');
