INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (572, 'FBCV', 'ETF', 'usa', 'Invesco Global Growth Fund Clas', 'Invesco Global Growth Fund Class A', 'US$', 'Value', 'Large', 'Invesco', 'BTS', 'Large Value', 96075136, 0.0084, '2020-06-02', 0.2, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities and depositary receipts of domestic and foreign issuers. It will provide exposure to investments that are economically tied to at least three different countries, including the U.S. and at least 40%, unless market conditions are not deemed favorable, in which case at least 30%, of its net assets will provide exposure to investments that are economically tied to countries other than the U.S. The fund may invest up to 20% of its net assets in securities of issuers located in emerging markets countries.', 0.0059, 0.0034, 26317, 29730, 28.909, 28.253, 1, 0, 2.47, 11.49, 18.04, 1.47, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 96075136, "Yield_Rate": 0.0084, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 26317, "Vol_Recent": 29730}, "moving_averages": {"MA_50": 28.909, "MA_200": 28.253}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.47, "PE_Ratio": 18.04, "PS_Ratio": 1.47, "PCF_Ratio": 11.49}}');
