INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (591, 'FDIS', 'ETF', 'U.S.A.', 'American Century Ginnie Mae Fun', 'American Century Ginnie Mae Fund I Class', 'AmericanDollar', 'Growth', 'Large', 'American Century Investments', 'PCX', 'Consumer Cyclical', 1568050048, 0.0049, '2013-10-21', 0.6, 'The investment seeks high current income while maintaining liquidity and safety of principal by investing primarily in GNMA certificates. Under normal market conditions, the fund invests at least 80% of its net assets in securities issued by the Government National Mortgage Association (GNMA). GNMA certificates represent interests in pools of mortgage loans and in the cash flows from these loans. To generate additional income, the fund may purchase securities, including mortgage dollar rolls, in advance through when-issued and forward commitment transactions. It may commit up to 35% of its total assets to such transactions.', 0.00084, 0.0045, 98740, 121080, 86.401, 81.183, 0.9984, 0, 7.19, 15.6, 29.64, 2.07, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 1568050048, "Yield_Rate": 0.0049, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0045, "Turnover_Ratio": 0.6}', '{"volume_metrics": {"Vol_3M": 98740, "Vol_Recent": 121080}, "moving_averages": {"MA_50": 86.401, "MA_200": 81.183}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9984}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.19, "PE_