INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (609, 'FEUZ', 'ETF', 'U.S.A.', 'AllianzGI Global Dynamic Alloca', 'Virtus AllianzGI Global Dynamic Allocation Fund Class P', 'US Dollar', 'Value', 'Large', 'Virtus', 'NGM', 'Europe Stock', 27742792, 0.0239, '2014-10-21', 0.93, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective through a combination of active allocation between asset classes and actively managed strategies within those asset classes. It allocates the fund''s investments among asset classes in response to changing market, economic, and political factors and events that the portfolio managers responsible for allocation believe may affect the value of the fund''s investments.', 0.008, 0.0044, 23582, 4040, 46.818, 46.615, 0.9997, 0, 1.1, 6.09, 14.3, 0.71, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 27742792, "Yield_Rate": 0.0239, "Expense_Net": 0.008, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.93}', '{"volume_metrics": {"Vol_3M": 23582, "Vol_Recent": 4040}, "moving_averages": {"MA_50": 46.818, "MA_200": 46.615}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.1, "PE_Ratio": 14.3, "PS_Ratio": 0.71, "PCF_Ratio": 6.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (610, 'FEVR', 'ETF', 'America', 'The Growth Fund of America Clas', 'American Funds The Growth Fund of America Class A', 'DOLLAR', 'Growth', 'Large', 'American Funds', 'PCX', 'Large Growth', 39202184, NULL, '2020-12-07', NULL, 'The investment seeks growth of capital. The fund invests primarily in common stocks and seeks to invest in companies that appear to offer superior opportunities for growth of capital. It may invest up to 25% of its assets in securities of issuers domiciled outside the United States. The investment adviser uses a system of multiple portfolio managers in managing the fund''s assets. Under this approach, the portfolio of the fund is divided into segments managed by individual managers.', 0.0085, 0.0039, 19127, 3070, 30.146, 27.851, 0.9904, 0, 5.34, 20.04, 27.25, 3.09, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 39202184, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0039, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19127, "Vol_Recent": 3070}, "moving_averages": {"MA_50": 30.146, "MA_200": 27.851}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9904}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.34, "PE_Ratio": 27.25, "PS_Ratio": 3.09, "PCF_Ratio": 20.04}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (611, 'FEX', 'ETF', 'United States', 'AB Sustainable Global Thematic ', 'AB Sustainable Global Thematic Fund Class I', 'AmericanDollar', 'Blend', 'Large', 'AllianceBernstein', 'NGM', 'Large Blend', 1188681216, 0.0082, '2007-05-08', 1.04, 'The investment seeks long-term growth of capital. The fund pursues opportunistic growth by investing in a global universe of companies that are positively exposed to sustainable investment themes. The Adviser employs a combination of "top-down" and "bottom-up" investment processes with the goal of identifying securities of companies worldwide, fitting into sustainable investment themes. The Adviser identifies sustainable investment themes that are broadly consistent with achieving the United Nations Sustainable Development Goals.', 0.0059, 0.0036, 27064, 19400, 89.614, 85.728, 0.9997, 0, 3, 13.52, 20.03, 1.93, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 1188681216, "Yield_Rate": 0.0082, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 1.04}', '{"volume_metrics": {"Vol_3M": 27064, "Vol_Recent": 19400}, "moving_averages": {"MA_50": 89.614, "MA_200": 85.728}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3, "PE_Ratio": 20.03, "PS_Ratio": 1.93, "PCF_Ratio": 13.52}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (612, 'FFEB', 'ETF', 'UNITED_STATES', 'American Beacon Frontier Market', 'American Beacon Frontier Markets Income Fund A Class', 'US_DOLLAR', 'Blend', 'Large', 'American Beacon', 'BTS', NULL, 266498672, NULL, '2020-02-21', NULL, 'The investment seeks income with capital appreciation as a secondary objective. Under normal circumstances, the fund will invest at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in investments that are economically tied to frontier market countries. Investments economically tied to frontier market countries may include securities, currencies, and derivative investments.', 0.0085, NULL, 24770, 15710, 37.579, 36.258, NULL, NULL, 4.43, 17.58, 26.49, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 266498672, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 24770, "Vol_Recent": 15710}, "moving_averages": {"MA_50": 37.579, "MA_200": 36.258}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.43, "PE_Ratio": 26.49, "PS_Ratio": 2.96, "PCF_Ratio": 17.58}}');
