INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (624, 'FICS', 'ETF', 'America', 'American Century Global Gold Fu', 'American Century Global Gold Fund C Class', 'usd', 'Growth', 'Large', 'American Century Investments', 'NGM', 'Foreign Large Growth', 3431355, NULL, '2020-12-15', NULL, 'The investment seeks to realize a total return (capital growth and dividends) consistent with investment in securities of companies that are engaged in mining, processing, fabricating or distributing gold or other precious metals throughout the world. The fund invests at least 80% of its net assets in companies that are engaged in mining, processing, fabricating, distributing, exploring for or otherwise dealing in gold. It is non-diversified.', 0.007, 0.0066, 3882, 4060, 35.278, 34.265, 0.994, 0, 5.07, 16.95, 20.3, 1.85, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 3431355, "Yield_Rate": null, "Expense_Net": 0.007, "Benchmark_Exp": 0.0066, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3882, "Vol_Recent": 4060}, "moving_averages": {"MA_50": 35.278, "MA_200": 34.265}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.07, "PE_Ratio": 20.3, "PS_Ratio": 1.85, "PCF_Ratio": 16.95}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (625, 'FID', 'ETF', 'United States', 'Focused Global Growth Fund Clas', 'American Century Focused Global Growth Fund Y Class', 'USD', 'Value', 'Large', 'American Century Investments', 'NGM', 'Foreign Large Value', 43324756, 0.0333, '2013-08-23', 0.81, 'The investment seeks capital growth. The fund invests primarily in companies located in developed countries world-wide (including the United States). Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.006, 0.0046, 7016, 11170, 17.759, 18.027, NULL, NULL, 1.2, 7.71, 13.92, 0.88, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 43324756, "Yield_Rate": 0.0333, "Expense_Net": 0.006, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.81}', '{"volume_metrics": {"Vol_3M": 7016, "Vol_Recent": 11170}, "moving_averages": {"MA_50": 17.759, "MA_200": 18.027}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.2, "PE_Ratio": 13.92, "PS_Ratio": 0.88, "PCF_Ratio": 7.71}}');
