INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (632, 'FIVA', 'ETF', 'us', 'Invesco High Yield Fund Class Y', 'Invesco High Yield Fund Class Y', 'US_DOLLAR', 'Value', 'Large', 'Invesco', 'PCX', 'Foreign Large Value', 31373592, 0.0285, '2018-01-16', 0.76, 'The investment seeks total return through growth of capital and current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in debt securities that are determined to be below investment grade quality, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest in preferred stocks and convertible securities, which are securities that generally pay interest and may be converted into common stock. The fund may invest up to 25% of its net assets in foreign securities.', 0.0039, 0.0046, 7348, 8670, 24.256, 24.272, 0.9903, 0, 1.38, 7.37, 13.38, 1.01, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 31373592, "Yield_Rate": 0.0285, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.76}', '{"volume_metrics": {"Vol_3M": 7348, "Vol_Recent": 8670}, "moving_averages": {"MA_50": 24.256, "MA_200": 24.272}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9903}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.38, "PE_Ratio": 13.38, "PS_Ratio": 1.01, "PCF_Ratio": 7.37}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (633, 'FIVG', 'ETF', 'U.S.', 'High Income Fund - A Class', 'American Century High Income Fund A Class', 'USD', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Communications', 1281323904, 0.0094, '2019-03-04', 0.28, 'The investment seeks current yield and capital growth. The fund invests primarily in high-yield corporate bonds and other debt instruments with an emphasis on those that are rated below investment-grade. A high-yield security, or junk bond, is one that has been rated below the four highest categories used by a nationally recognized statistical rating organization, or, if unrated, determined by the investment advisor to be of similar quality. It may invest up to 20% of its net assets in bank loan investments. The fund may invest in fixed-income instruments of foreign issuers, including emerging market issuers.', 0.003, 0.0035, 161329, 227880, 38.557, 37.206, 0.9977, 0, 3.76, 12.22, 29.59, 2.68, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1281323904, "Yield_Rate": 0.0094, "Expense_Net": 0.003, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 161329, "Vol_Recent": 227880}, "moving_averages": {"MA_50": 38.557, "MA_200": 37.206}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9977}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.76, "PE_Ratio": 29.59, "PS_Ratio": 2.68, "PCF_Ratio": 12.22}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (634, 'FIW', 'ETF', 'UNITED_STATES', 'American Fds, American High-In', 'American High-Income Municipal Bond Fund Class C', 'US Dollar', 'Growth', 'Medium', 'American Funds', 'PCX', 'Natural Resources', 1039176832, 0.0045, '2007-05-08', 0.15, 'The investment seeks a high level of current income exempt from regular federal income tax. Under normal circumstances, the fund will invest at least 80% of its assets in, or derive at least 80% of its income from, securities that are exempt from regular federal income tax and may subject the investors to alternative minimum tax. It may invest, without limitation, in securities that may subject the investors to federal alternative minimum tax. The fund invests at least 50% of its portfolio in debt securities rated BBB+ or below or Baa1 or below, or unrated but determined by the fund''s investment adviser to be of equivalent quality.', 0.0054, 0.0048, 88800, 76910, 89.936, 84.895, 0.9997, 0, 4.25, 20.02, 33.6, 3.02, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 1039176832, "Yield_Rate": 0.0045, "Expense_Net": 0.0054, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 88800, "Vol_Recent": 76910}, "moving_averages": {"MA_50": 89.936, "MA_200": 84.895}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.25,