INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (657, 'FLHK', 'ETF', 'USA', 'Invesco High Yield Fund Class C', 'Invesco High Yield Fund Class C', 'US_DOLLAR', 'Value', 'Large', 'Invesco', 'PCX', NULL, 17868312, 0.0273, '2017-11-02', 0.1484, 'The investment seeks total return through growth of capital and current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in debt securities that are determined to be below investment grade quality, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest in preferred stocks and convertible securities, which are securities that generally pay interest and may be converted into common stock. The fund may invest up to 25% of its net assets in foreign securities.', 0.0009, NULL, 5308, 980, 25.902, 27.801, 0.9988, 0, 1.34, 9.61, 21.82, 2.61, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 17868312, "Yield_Rate": 0.0273, "Expense_Net": 0.0009, "Benchmark_Exp": null, "Turnover_Ratio": 0.1484}', '{"volume_metrics": {"Vol_3M": 5308, "Vol_Recent": 980}, "moving_averages": {"MA_50": 25.902, "MA_200": 27.801}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.34, "PE_Ratio": 21.82, "PS_Ratio": 2.61, "PCF_Ratio": 9.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (658, 'FLHY', 'ETF', 'U.S.', 'American Century High-Yield Fun', 'American Century High-Yield Fund R6 Class', 'US Dollar', 'Value', 'Small', 'American Century Investments', 'BTS', 'High Yield Bond', 358595104, 0.0501, '2018-05-30', 0.5318, 'The investment seeks high current income; capital appreciation is the secondary objective. The portfolio managers will maintain at least 80% of the fund''s net assets in high-yield corporate bonds and other debt instruments. The remaining assets may be invested in common stocks or other equity-related securities. Up to 40% of the fund''s total assets may be invested in fixed-income obligations of foreign issuers. It may invest up to 20% of its assets in short-term money market instruments and U.S. government securities. The fund has no average maturity limitations, but it typically invests in intermediate-term and long-term debt securities.', 0.004, 0.0047, 30658, 11690, 26.284, 26.414, NULL, NULL, 13.72, 9.58, 21.69, 0.6, 4.28, 3.92, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 358595104, "Yield_Rate": 0.0501, "Expense_Net": 0.004, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.5318}', '{"volume_metrics": {"Vol_3M": 30658, "Vol_Recent": 11690}, "moving_averages": {"MA_50": 26.284, "MA_200": 26.414}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.28, "Duration_Yrs": 3.92}}', '{"valuation_metrics": {"PB_Ratio": 13.72, "PE_Ratio": 21.69, "PS_Ratio": 0.6, "PCF_Ratio": 9.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (659, 'FLIA', 'ETF', 'United States', 'American Century High-Yield Fun', 'American Century High-Yield Fund I Class', 'Usd', NULL, NULL, 'American Century Investments', 'BTS', 'World Bond', 170669152, 0.0026, '2018-05-30', 0.7221, 'The investment seeks high current income; capital appreciation is the secondary objective. The portfolio managers will maintain at least 80% of the fund''s net assets in high-yield corporate bonds and other debt instruments. The remaining assets may be invested in common stocks or other equity-related securities. Up to 40% of the fund''s total assets may be invested in fixed-income obligations of foreign issuers. It may invest up to 20% of its assets in short-term money market instruments and U.S. government securities. The fund has no average maturity limitations, but it typically invests in intermediate-term and long-term debt securities.', 0.0025, 0.0042, 112975, 4420, 25.102, 25.13, NULL, NULL, NULL, NULL, NULL, NULL, 7.36, 6.87, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 170669152, "Yield_Rate": 0.0026, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0042, "Turnover_Ratio": 0.7221}', '{"volume_metrics": {"Vol_3M": 112975, "Vol_Recent": 4420}, "moving_averages": {"MA_50": 25.102, "MA_200": 25.13}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.36, "Duration_Yrs": 6.87}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (660, 'FLIN', 'ETF', 'UNITED_STATES', 'Aberdeen Short Duration High Yi', 'Aberdeen Short Duration High Yield Municipal Fund Institutional Class', 'DOLLAR', 'Blend', 'Large', 'Aberdeen', 'PCX', NULL, 27966498, 0.0061, '2018-02-06', 0.2348, 'The investment seeks a high level of current income exempt from federal income tax. Under normal circumstances, the fund invests at least 80% of its net assets in municipal obligations that are exempt from federal income tax (including securities subject to the federal alternative minimum tax ("AMT")). It invests at least 50% of its assets in municipal bonds rated BBB or lower by S&P Global Ratings or Baa or lower by Moody''s Investors Service, Inc., at the time of investment, or the equivalent by another independent rating agency or the unrated equivalent as determined by the Adviser.', 0.0019, NULL, 13546, 9900, 33.167, 30.381, 0.9992, 0, 3.17, 14.73, 27.29, 2.79, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 27966498, "Yield_Rate": 0.0061, "Expense_Net": 0.0019, "Benchmark_Exp": null, "Turnover_Ratio": 0.2348}', '{"volume_metrics": {"Vol_3M": 13546, "Vol_Recent": 9900}, "moving_averages": {"MA_50": 33.167, "MA_200": 30.381}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.17, "PE_Ratio": 27.29, "PS_Ratio": 2.79, "PCF_Ratio": 14.73}}');
