INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (869, 'GYLD', 'ETF', 'U.S.', 'American Growth Fund, Inc. - Cl', 'American Growth Fund Series One Class A', 'US_DOLLAR', 'Value', 'Medium', 'American Growth', 'PCX', 'World Allocation', 42417316, 0.0552, '2012-05-08', 0.8, 'The investment seeks growth of capital. The fund uses a consistent approach to build the fund''s security portfolio which is made up primarily of common stocks and securities convertible into common stock. These securities are issued by large companies, and to a lesser extent, small and mid-sized companies. When a company''s fundamentals are strong, the managers believe earnings growth will follow.', 0.0075, 0.0058, 5680, 4650, 14.818, 14.835, NULL, NULL, 1.04, 4.99, 10.08, 1.04, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 42417316, "Yield_Rate": 0.0552, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0058, "Turnover_Ratio": 0.8}', '{"volume_metrics": {"Vol_3M": 5680, "Vol_Recent": 4650}, "moving_averages": {"MA_50": 14.818, "MA_200": 14.835}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.04, "PE_Ratio": 10.08, "PS_Ratio": 1.04, "PCF_Ratio": 4.99}}');
