INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (682, 'FLRT', 'ETF', 'usa', 'Disciplined Core Value Fund - R', 'American Century Disciplined Core Value Fund R5 Class', 'US_DOLLAR', NULL, NULL, 'American Century Investments', 'PCX', 'Bank Loan', 31787812, 0.0319, '2015-02-18', 0.48, 'The investment seeks long-term capital growth; income is a secondary consideration. In selecting stocks for the fund, the managers use quantitative and qualitative management techniques in a multi-step process. The managers evaluate stocks, primarily large capitalization, publicly traded U.S. companies based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use quantitative models to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0069, 0.0077, 5882, 2380, 49.008, 48.963, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.42, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 31787812, "Yield_Rate": 0.0319, "Expense_Net": 0.0069, "Benchmark_Exp": 0.0077, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 5882, "Vol_Recent": 2380}, "moving_averages": {"MA_50": 49.008, "MA_200": 48.963}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 0.42}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
