INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (684, 'FLSA', 'ETF', 'us', 'Sanford C. Bernstein Fund, Inc.', 'AB Intermediate California Municipal Portfolio Advisor Class', 'USD', 'Blend', 'Large', 'AllianceBernstein', 'PCX', NULL, 3230397, 0.0176, '2018-10-09', 0.1674, 'The investment seeks to provide safety of principal and maximize total return after taking account of federal and state taxes for California residents. The fund invests at least 80% of its net assets in a portfolio of municipal securities issued by the State of California or its political subdivisions, or otherwise exempt from California state income tax. It seeks to maintain an effective duration of three and one-half years to seven years. The fund may invest up to 20% of its total assets in fixed-income securities rated BB or B by national rating agencies, which are not investment-grade (commonly known as "junk bonds"). It is non-diversified.', 0.0039, NULL, 490, 410, 36.256, 33.225, 0.9946, 0, 2.25, 12.41, 26.13, 4.36, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 3230397, "Yield_Rate": 0.0176, "Expense_Net": 0.0039, "Benchmark_Exp": null, "Turnover_Ratio": 0.1674}', '{"volume_metrics": {"Vol_3M": 490, "Vol_Recent": 410}, "moving_averages": {"MA_50": 36.256, "MA_200": 33.225}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9946}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.25, "PE_Ratio": 26.13, "PS_Ratio": 4.36, "PCF_Ratio": 12.41}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (721, 'FPA', 'ETF', 'UNITED_STATES', 'American Century International ', 'American Century International Opportunities Fund Class R', 'AmericanDollar', 'Value', 'Large', 'American Century Investments', 'NGM', 'Pacific/Asia ex-Japan Stk', 21880288, 0.021, '2011-04-18', 1.03, 'The investment seeks capital growth. The fund invests primarily in equity securities of companies that are small-sized at the time of purchase and are located in foreign developed countries or emerging market countries. Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.008, 0.0054, 7220, 1080, 32.233, 34.405, 0.9963, 0, 0.93, 5.83, 12.25, 0.81, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 21880288, "Yield_Rate": 0.021, "Expense_Net": 0.008, "Benchmark_Exp": 0.0054, "Turnover_Ratio": 1.03}', '{"volume_metrics": {"Vol_3M": 7220, "Vol_Recent": 1080}, "moving_averages": {"MA_50": 32.233, "MA_200": 34.405}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9963}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.93, "PE_Ratio": 12.25, "PS_Ratio": 0.81, "PCF_Ratio": 5.83}}');
