INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (693, 'FLZA', 'ETF', 'USA', 'Strategic Enhanced Yield Fund I', 'Cavanal Hill Strategic Enhanced Yield Fund Institutional', 'US$', 'Value', 'Medium', 'Cavanal Hill funds', 'PCX', NULL, 2854566, 0.0333, '2018-10-10', 0.1108, 'The investment seeks current income and, secondarily, the opportunity for capital appreciation to produce total return. The fund seeks total return by allocating assets among various fixed income sectors, with no more than 65% of its net assets in any one sector. The Adviser will employ a strategy to enhance the fund''s yield by shifting assets among higher yielding and lower yielding debt securities across sectors and different maturities based on its view of the relative value of each sector or maturity. Under normal circumstances, the fund invests at least 80% of its net assets in bonds.', 0.0019, NULL, 995, 1140, 25.658, 26.246, 0.9992, 0, 1.85, NULL, 16.82, 1.39, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 2854566, "Yield_Rate": 0.0333, "Expense_Net": 0.0019, "Benchmark_Exp": null, "Turnover_Ratio": 0.1108}', '{"volume_metrics": {"Vol_3M": 995, "Vol_Recent": 1140}, "moving_averages": {"MA_50": 25.658, "MA_200": 26.246}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 16.82, "PS_Ratio": 1.39, "PCF_Ratio": null}}');
