INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (747, 'FTGC', 'ETF', 'us', 'Akre Focus - Retail', 'Akre Focus Fund Retail Class', 'US$', NULL, NULL, 'Akre', 'NGM', 'Commodities Broad Basket', 1621286912, NULL, '2013-10-21', NULL, 'The investment seeks long-term capital appreciation. The fund invests primarily in securities of companies listed on U.S. stock exchanges. Investments consist primarily of common stocks of companies of any size market capitalization. It may also invest in preferred stocks, warrants, options, and other equity-like instruments, such as partnership interests, limited liability company interests, business trust shares and rights, REITs, and other securities that are convertible into equity securities. The fund is non-diversified.', 0.0095, 0.0081, 462272, 433560, 24.856, 23.318, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 1621286912, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 462272, "Vol_Recent": 433560}, "moving_averages": {"MA_50": 24.856, "MA_200": 23.318}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (716, 'FNX', 'ETF', 'USA', 'Columbia Income Opportunities F', 'Columbia Income Opportunities Fund Class A', 'Dollar', 'Blend', 'Medium', 'Columbia Threadneedle', 'NGM', 'Mid-Cap Blend', 1034784704, 0.0078, '2007-05-08', 1.15, 'The investment seeks a high total return through current income and capital appreciation. Under normal market conditions, the fund''s assets are invested primarily in income-producing debt securities, with an emphasis on the higher rated segment of the high-yield (junk bond) market. These income-producing debt instruments include corporate debt securities as well as bank loans. The fund will purchase only debt instruments rated B or above, or if unrated, determined to be of comparable quality. It may invest in debt instruments of any maturity and does not seek to maintain a particular dollar-weighted average maturity.', 0.006, 0.0047, 29970, 21370, 102.624, 98.932, 0.9997, 0, 2.48, 10.78, 16.81, 1.51, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 1034784704, "Yield_Rate": 0.0078, "Expense_Net": 0.006, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 1.15}', '{"volume_metrics": {"Vol_3M": 29970, "Vol_Recent": 21370}, "moving_averages": {"MA_50": 102.624, "MA_200": 98.932}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.48, "PE_Ratio": 16.81, "PS_Ratio": 1.51, "PCF_Ratio": 10.78}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (717, 'FNY', 'ETF', 'us', 'American Century International ', 'American Century International Opportunities Fund Class C', 'USD', 'Growth', 'Medium', 'American Century Investments', 'NGM', 'Mid-Cap Growth', 444588448, 0.0021, '2011-04-19', 1.35, 'The investment seeks capital growth. The fund invests primarily in equity securities of companies that are small-sized at the time of purchase and are located in foreign developed countries or emerging market countries. Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.007, 0.0046, 22966, 9900, 75.302, 72.252, 1, 0, 5.65, 15.66, 26.01, 2.4, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 444588448, "Yield_Rate": 0.0021, "Expense_Net": 0.007, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 1.35}', '{"volume_metrics": {"Vol_3M": 22966, "Vol_Recent": 9900}, "moving_averages": {"MA_50": 75.302, "MA_200": 72.252}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.65, "PE_Ratio": 26.01, "PS_Ratio": 2.4, "PCF_Ratio": 15.66}}');
