INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (750, 'FTLS', 'ETF', 'U.S.', 'Invesco Income Allocation Fund ', 'Invesco Income Allocation Fund Class A', 'usd', 'Blend', 'Large', 'Invesco', 'PCX', 'Long-Short Equity', 374086784, 0.003, '2014-09-08', 2.5, 'The investment seeks current income and, secondarily, growth of capital. The fund is a "fund of funds," and invests its assets in other underlying mutual funds advised by the Adviser and ETFs and other pooled investment vehicles. It invests its assets in a selection of underlying funds which invest primarily in international or domestic equities, fixed-income securities or real estate investment trusts. The fund''s target allocation is to invest 60%-70% of its total assets in underlying funds that invest primarily in fixed-income securities and 30%-40% of its total assets in underlying funds that invest primarily in equity securities, including REITs.', 0.0155, 0.0095, 33629, 27760, 50.187, 48.375, NULL, NULL, 3.73, 14.55, 24.01, 2.01, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 374086784, "Yield_Rate": 0.003, "Expense_Net": 0.0155, "Benchmark_Exp": 0.0095, "Turnover_Ratio": 2.5}', '{"volume_metrics": {"Vol_3M": 33629, "Vol_Recent": 27760}, "moving_averages": {"MA_50": 50.187, "MA_200": 48.375}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.73, "PE_Ratio": 24.01, "PS_Ratio": 2.01, "PCF_Ratio": 14.55}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (751, 'FTRI', 'ETF', 'USA', 'ALPS/Smith Balanced Opportunity', 'ALPS/Smith Balanced Opportunity Fund Class A', 'Dollar', 'Value', 'Large', 'ALPS', 'NGM', 'Natural Resources', 35869808, 0.028, '2010-03-11', 0.66, 'The investment seeks long-term capital growth, consistent with preservation of capital and balanced by current income. The fund pursues its investment objective by normally investing 60% of its assets in equity securities and 40% of its assets in fixed-income securities and cash equivalents. Equity securities in which the fund may invest include common stocks and preferred stocks. Its fixed-income investments may reflect a broad range of credit qualities and may include corporate debt securities, U.S. government obligations, agency mortgage-backed securities, asset-backed securities, and bank loans.', 0.007, 0.0048, 19338, 17990, 13.177, 14.021, 0.9998, 0, 2.1, 6.15, 12.98, 1.37, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 35869808, "Yield_Rate": 0.028, "Expense_Net": 0.007, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.66}', '{"volume_metrics": {"Vol_3M": 19338, "Vol_Recent": 17990}, "moving_averages": {"MA_50": 13.177, "MA_200": 14.021}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.1, "PE_Ratio": 12.98, "PS_Ratio": 1.37, "PCF_Ratio": 6.15}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (752, 'FTSD', 'ETF', 'usa', 'Alger Focus Equity Fund Class A', 'Alger Focus Equity Fund Class A', 'DOLLAR', NULL, NULL, 'Alger', 'PCX', 'Short Government', 472083744, 0.0125, '2013-11-04', 2.1016, 'The investment seeks long-term capital appreciation. The advisor intends to invest a substantial portion of its assets in a small number of issuers, and may focus its portfolio in fewer business sectors or industries. Generally, the fund will own approximately 50 holdings. Fund holdings may occasionally exceed this number for a variety of reasons. The fund may engage in active trading of portfolio securities.', 0.0025, 0.0013, 23351, 21970, 94.451, 94.942, NULL, NULL, NULL, NULL, NULL, NULL, 4.45, 1.22, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 472083744, "Yield_Rate": 0.0125, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0013, "Turnover_Ratio": 2.1016}', '{"volume_metrics": {"Vol_3M": 23351, "Vol_Recent": 21970}, "moving_averages": {"MA_50": 94.451, "MA_200": 94.942}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.45, "Duration_Yrs": 1.22}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
