INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (761, 'FTXR', 'ETF', 'United States', 'AB Large Cap Growth Fund, Inc. ', 'AB Large Cap Growth Fund Class K', 'US$', 'Blend', 'Medium', 'AllianceBernstein', 'NGM', 'Industrials', 1186244096, 0.0035, '2016-09-20', 1.29, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of a limited number of large, carefully selected, high-quality U.S. companies. It invests primarily in the domestic equity securities of companies selected by the fund''s Adviser for their growth potential within various market sectors. The fund emphasizes investments in large, seasoned companies. Under normal circumstances, the fund will invest at least 80% of its net assets in common stocks of large-capitalization companies. It may, at times, invest in shares of exchange-traded funds in lieu of making direct investments in securities.', 0.006, 0.0046, 92583, 56470, 33.474, 32.893, 0.9995, 0, 4.11, 10.43, 24.42, 1.87, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 1186244096, "Yield_Rate": 0.0035, "Expense_Net": 0.006, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 1.29}', '{"volume_metrics": {"Vol_3M": 92583, "Vol_Recent": 56470}, "moving_averages": {"MA_50": 33.474, "MA_200": 32.893}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.11, "PE_Ratio": 24.42, "PS_Ratio": 1.87, "PCF_Ratio": 10.43}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (762, 'FUMB', 'ETF', 'usa', 'AllianzGI Large-Cap Value Fund ', 'Virtus NFJ Large-Cap Value Fund Class P', 'DOLLAR', NULL, NULL, 'Virtus', 'PCX', 'Muni National Short', 154286784, 0.0065, '2018-11-01', 1.49, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 80% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities of companies with large market capitalizations. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends). In addition to common stocks and other equity securities, the fund may invest in real estate investment trusts (REITs) and in non-U.S. securities (including through American Depositary Receipts (ADRs)), including emerging market securities.', 0.0025, 0.0023, 47350, 78440, 20.155, 20.175, NULL, NULL, NULL, NULL, NULL, NULL, 1.27, 0.86, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 154286784, "Yield_Rate": 0.0065, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 1.49}', '{"volume_metrics": {"Vol_3M": 47350, "Vol_Recent": 78440}, "moving_averages": {"MA_50": 20.155, "MA_200": 20.175}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.27, "Duration_Yrs": 0.86}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (763, 'FUNL', 'ETF', 'United States', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund California Portfolio Advisor Class', 'AmericanDollar', 'Value', 'Large', 'AllianceBernstein', 'BTS', NULL, 102563488, NULL, '2020-08-19', NULL, 'The investment seeks to earn the highest level of current income, exempt from federal income tax and California personal income tax, which is available without assuming what the Adviser considers to be undue risk to income or principal. The fund invests principally in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers.', 0.005, NULL, 7075, 1960, 34.663, 33.569, NULL, NULL, 2.52, 11.96, 19.22, 1.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 102563488, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7075, "Vol_Recent": 1960}, "moving_averages": {"MA_50": 34.663, "MA_200": 33.569}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.52, "PE_Ratio": 19.22, "PS_Ratio": 1.84, "PCF_Ratio": 11.96}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (765, 'FUTY', 'ETF', 'USA', 'Columbia Limited Duration Credi', 'Columbia Limited Duration Credit Fund Class A', 'Usd', 'Value', 'Medium', 'Columbia Threadneedle', 'PCX', 'Utilities', 1031806208, 0.0304, '2013-10-21', 0.05, 'The investment seeks to provide shareholders with a level of current income consistent with preservation of capital. Under normal circumstances, the fund invests at least 80% of its net assets (including the amount of any borrowings for investment purposes) in corporate bonds. It will primarily invest in debt securities with short- and intermediate-term maturities generally similar to those included in the fund''s benchmark index, the Bloomberg Barclays U.S. 1-5 Year Corporate Index (the index).', 0.00084, 0.0042, 138383, 93170, 42.815, 42.4, 0.998, 0, 2.13, 11.75, 22.69, 2.62, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 1031806208, "Yield_Rate": 0.0304, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0042, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 138383, "Vol_Recent": 93170}, "moving_averages": {"MA_50": 42.815, "MA_200": 42.4}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.13, "PE_Ratio": 22.69, "PS_Ratio": 2.62, "PCF_Ratio": 11.75}}');
