INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (794, 'GAZ', 'ETF', 'USA', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund National Portfolio Class C', 'US$', NULL, NULL, 'AllianceBernstein', 'PCX', NULL, 5230272, NULL, '2017-03-08', NULL, 'The investment seeks to earn the highest level of current income, exempt from federal income tax, which is available without assuming what the Adviser considers to be undue risk to principal or income. The fund invests principally in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. The fund may invest more than 25% of its assets in a single state.', 0.0045, NULL, 31698, 20170, 27.992, 21.038, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 5230272, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 31698, "Vol_Recent": 20170}, "moving_averages": {"MA_50": 27.992, "MA_200": 21.038}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
