INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (806, 'GDXJ', 'ETF', 'United States', 'AMG River Road Long-Short Fund ', 'AMG River Road International Value Equity Fund Class I', 'USD', 'Blend', 'Medium', 'AMG Funds', 'PCX', 'Equity Precious Metals', 5234781696, 0.0184, '2009-11-10', 0.34, 'The investment seeks to provide absolute return while minimizing volatility over a full market cycle. The fund pursues its investment objective primarily by taking long and short positions in equity securities. Its subadviser believes that a combination of long and short positions may provide positive returns through a complete market cycle and may offer reduced risk. The allocation between long and short positions is a result of the subadviser''s fundamental investment process. The fund is non-diversified.', 0.0052, 0.0057, 6430150, 7.07959e+06, 43.084, 46.017, 0.9977, 0, 1.74, 6.91, 15.81, 1.97, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 5234781696, "Yield_Rate": 0.0184, "Expense_Net": 0.0052, "Benchmark_Exp": 0.0057, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 6430150, "Vol_Recent": 7079590}, "moving_averages": {"MA_50": 43.084, "MA_200": 46.017}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9977}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.74, "PE_Ratio": 15.81, "PS_Ratio": 1.97, "PCF_Ratio": 6.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (807, 'GDXU', 'ETF', 'UNITED_STATES', 'Archer Multi Cap Fund', 'Archer Multi Cap Fund', 'USD', 'Blend', 'Medium', 'Archer', 'PCX', 'Trading--Leveraged Commodities', 31711902, NULL, '2020-12-02', NULL, 'The investment seeks long-term growth of capital. The fund is a "non-diversified" portfolio investing in equity securities, primarily common stocks, of U.S. companies and may also invest, from time to time, in exchange traded funds ("ETFs") that primarily invest in these companies that are selected for their long-term growth potential. It is a "multi-cap" fund in that it may invest in issuers of any market capitalization. Under normal market conditions, the fund will hold a core position of up to 100 common stocks. It is non-diversified.', 0.0095, 0.009, 413793, 423170, 11.798, 15.894, 0.9972, 0, 1.89, 7.99, 16.61, 2.6, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 31711902, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 413793, "Vol_Recent": 423170}, "moving_averages": {"MA_50": 11.798, "MA_200": 15.894}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9972}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.89, "PE_Ratio": 16.61, "PS_Ratio": 2.6, "PCF_Ratio": 7.99}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (870, 'HACK', 'ETF', 'USA', 'American Growth Fund, Inc. - Cl', 'American Growth Fund Series One Class B', 'USD', 'Growth', 'Medium', 'American Growth', 'PCX', 'Technology', 2270508032, 0.001, '2014-11-11', 0.33, 'The investment seeks growth of capital. The fund uses a consistent approach to build the fund''s security portfolio which is made up primarily of common stocks and securities convertible into common stock. These securities are issued by large companies, and to a lesser extent, small and mid-sized companies. When a company''s fundamentals are strong, the managers believe earnings growth will follow.', 0.006, 0.0053, 190151, 186070, 64.096, 60.695, 1, 0, 5.18, 21.05, NULL, 3.7, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 2270508032, "Yield_Rate": 0.001, "Expense_Net": 0.006, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 190151, "Vol_Recent": 186070}, "moving_averages": {"MA_50": 64.096, "MA_200": 60.695}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.18, "PE_Ratio": null, "PS_Ratio": 3.7, "PCF_Ratio": 21.05}}');
