INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (835, 'GOEX', 'ETF', 'UNITED_STATES', 'American Century Mid Cap Value ', 'American Century Mid Cap Value Fund R6 Class', 'USD', 'Blend', 'Small', 'American Century Investments', 'PCX', 'Equity Precious Metals', 51993808, 0.0338, '2010-11-03', 0.1881, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s net assets in medium size companies. The portfolio managers consider medium size companies to include those whose market capitalizations at the time of purchase are within the capitalization range of the Russell 3000© Index, excluding the largest 100 such companies.', 0.0065, 0.0057, 8393, 5770, 30.026, 30.9, 0.9986, 0, 1.71, 6.46, 14.36, 1.75, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 51993808, "Yield_Rate": 0.0338, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0057, "Turnover_Ratio": 0.1881}', '{"volume_metrics": {"Vol_3M": 8393, "Vol_Recent": 5770}, "moving_averages": {"MA_50": 30.026, "MA_200": 30.9}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.71, "PE_Ratio": 14.36, "PS_Ratio": 1.75, "PCF_Ratio": 6.46}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (836, 'GOVT', 'ETF', 'U.S.', 'Amana Developing World Fund', 'Amana Mutual Funds Trust Developing World Fund Investor', 'AmericanDollar', NULL, NULL, 'Amana', 'BTS', 'Intermediate Government', 17065084928, 0.01, '2012-02-14', 0.91, 'The investment seeks long-term capital growth, consistent with Islamic principles. The fund invests only in common stocks of companies with significant exposure (50% or more of production assets, or revenues) to countries with developing economies and/or markets. Investment decisions are made in accordance with Islamic principles. It diversifies its investments across the industries, companies, and countries of the developing world, and principally follows a large-cap value investment style.', 0.0005, 0.0011, 4497216, 4.41027e+06, 26.467, 26.524, 0, 0.9948, NULL, NULL, NULL, NULL, 8.25, 6.77, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 17065084928, "Yield_Rate": 0.01, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0011, "Turnover_Ratio": 0.91}', '{"volume_metrics": {"Vol_3M": 4497216, "Vol_Recent": 4410270}, "moving_averages": {"MA_50": 26.467, "MA_200": 26.524}}', '{"asset_allocation": {"Bond_Weight": 0.9948, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.25, "Duration_Yrs": 6.77}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (837, 'GOVZ', 'ETF', 'us', 'The Income Fund of America, Cla', 'American Funds The Income Fund of America Class A', 'US_DOLLAR', NULL, NULL, 'American Funds', 'BTS', 'Long Government', 399090208, NULL, '2020-09-22', 0.36, 'The investment seeks to provide investors with current income while secondarily striving for capital growth. Normally the fund invests primarily in income-producing securities. These include equity securities, such as dividend-paying common stocks, and debt securities, such as interest-paying bonds. Generally at least 60% of the fund''s assets will be invested in common stocks and other equity-type securities. The fund may also invest up to 30% of its assets in equity securities of issuers domiciled outside the United States, including issuers in developing countries.', 0.0015, 0.0014, 34962, 24550, 21.651, 20.908, 0, 0.9989, NULL, NULL, NULL, NULL, 27.45, 27.15, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 399090208, "Yield_Rate": null, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0014, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 34962, "Vol_Recent": 24550}, "moving_averages": {"MA_50": 21.651, "MA_200": 20.908}}', '{"asset_allocation": {"Bond_Weight": 0.9989, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 27.45, "Duration_Yrs": 27.15}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (838, 'GQRE', 'ETF', 'US', 'The Income Fund of America, Cla', 'American Funds The Income Fund of America Class F-2', 'US_DOLLAR', 'Blend', 'Medium', 'American Funds', 'PCX', 'Global Real Estate', 375258944, 0.0166, '2013-11-05', 0.56, 'The investment seeks to provide investors with current income while secondarily striving for capital growth. Normally the fund invests primarily in income-producing securities. These include equity securities, such as dividend-paying common stocks, and debt securities, such as interest-paying bonds. Generally at least 60% of the fund''s assets will be invested in common stocks and other equity-type securities. The fund may also invest up to 30% of its assets in equity securities of issuers domiciled outside the United States, including issuers in developing countries.', 0.0045, 0.0053, 7820, 7030, 69.83, 66.611, NULL, NULL, 1.56, 16.71, 21.05, 6.01, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 375258944, "Yield_Rate": 0.0166, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.56}', '{"volume_metrics": {"Vol_3M": 7820, "Vol_Recent": 7030}, "moving_averages": {"MA_50": 69.83, "MA_200": 66.611}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.56, "PE_Ratio": 21.05, "PS_Ratio": 6.01, "PCF_Ratio": 16.71}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (846, 'GSEW', 'ETF', 'US', 'Alger Mid Cap Growth Fund Class', 'Alger Mid Cap Growth Fund Class A', 'US_DOLLAR', 'Blend', 'Large', 'Alger', 'BTS', 'Large Blend', 775949056, 0.0119, '2017-09-12', 0.48, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities of companies that, at the time of purchase of the securities, have total market capitalization within the range of companies included in the Russell Midcap Growth Index or the S&P MidCap 400 Index, as reported by the indexes as of the most recent quarter-end. Both indexes are designed to track the performance of medium-capitalization stocks.', 0.0009, 0.0036, 48288, 40190, 70.075, 66.909, 1, 0, 3.82, 16.35, 25.02, 2.36, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 775949056, "Yield_Rate": 0.0119, "Expense_Net": 0.0009, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 48288, "Vol_Recent": 40190}, "moving_averages": {"MA_50": 70.075, "MA_200": 66.909}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.82, "PE_Ratio": 25.02, "PS_Ratio": 2.36, "PCF_Ratio": 16.35}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (839, 'GREK', 'ETF', 'US', 'American Century Equity Growth ', 'American Century Equity Growth Fund I Class', 'US Dollar', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Miscellaneous Region', 161895744, 0.0192, '2011-12-07', 0.2848, 'The investment seeks long-term capital growth by investing in common stocks. The fund invests at least 80% of its net assets in equity securities. In selecting stocks for the fund, the portfolio managers use quantitative and qualitative management techniques in a multi-step process. First, the managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures. Second, the portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0058, 0.0053, 52853, 106490, 27.706, 27.722, 0.9995, 0, 0.77, 5.62, 11.87, 1.06, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 161895744, "Yield_Rate": 0.0192, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.2848}', '{"volume_metrics": {"Vol_3M": 52853, "Vol_Recent": 106490}, "moving_averages": {"MA_50": 27.706, "MA_200": 27.722}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.77, "PE_Ratio": 11.87, "PS_Ratio": 1.06, "PCF_Ratio": 5.62}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (859, 'GTO', 'ETF', 'usa', 'AllianzGl Emerging Markets Cons', 'Virtus AllianzGI Emerging Markets Consumer Fund Class A', 'US_DOLLAR', NULL, NULL, 'Virtus', 'PCX', NULL, 778806464, 0.0177, '2016-02-10', 4.34, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in securities and instruments that are tied economically to emerging market countries and by investing at least 80% of its net assets (plus borrowings made for investment purposes) in securities of companies in the consumer and consumer-related sectors.', 0.005, NULL, 146838, 214000, 56.599, 56.798, NULL, NULL, NULL, NULL, NULL, NULL, 11.48, 5.89, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 778806464, "Yield_Rate": 0.0177, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": 4.34}', '{"volume_metrics": {"Vol_3M": 146838, "Vol_Recent": 214000}, "moving_averages": {"MA_50": 56.599, "MA_200": 56.798}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.48, "Duration_Yrs": 5.89}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (840, 'GRES', 'ETF', 'U.S.', 'AlphaSimplex Managed Futures St', 'AlphaSimplex Managed Futures Strategy Fund Class A', 'USD', 'Value', 'Large', 'Natixis Funds', 'PCX', 'Natural Resources', 21526258, 0.0889, '2009-10-27', NULL, 'The investment seeks to provide capital appreciation. The adviser expected that no more than 25% of the fund''s total assets will be dedicated to initial and variation margin payments relating to the fund''s derivative transactions. The advisor expects that under normal market conditions the fund will invest at least 75% of its total assets in money market and other short-term, high-quality securities. The fund will concentrate its investments in the financial services industry, which means it will normally invest at least 25% of its total assets in securities and other obligations of issuers in such industry.', 0.0078, 0.0048, 7866, 4750, 29.858, 29.051, NULL, NULL, 1.85, 8.77, 16.71, 1.36, NULL, 0.71, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 21526258, "Yield_Rate": 0.0889, "Expense_Net": 0.0078, "Benchmark_Exp": 0.0048, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7866, "Vol_Recent": 4750}, "moving_averages": {"MA_50": 29.858, "MA_200": 29.051}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 0.71}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 16.71, "PS_Ratio": 1.36, "PCF_Ratio": 8.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (841, 'GRID', 'ETF', 'USA', 'American Mutual Fund, Class C S', 'American Funds American Mutual Fund Class C', 'USD', 'Growth', 'Large', 'American Funds', 'NGM', 'Miscellaneous Sector', 425897824, 0.0079, '2009-11-16', 0.53, 'The investment seeks current income, growth of capital and conservation of principal. The fund invests primarily in common stocks of companies that are likely to participate in the growth of the American economy and whose dividends appear to be sustainable. It invests primarily in securities of issuers domiciled in the United States and Canada. The fund may also invest in bonds and other debt securities, including those issued by the U.S. government and by federal agencies and instrumentalities.', 0.007, 0.0067, 71812, 92530, 99.617, 93.486, 0.9994, 0, 3.66, 16.45, 33.74, 2.41, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 425897824, "Yield_Rate": 0.0079, "Expense_Net": 0.007, "Benchmark_Exp": 0.0067, "Turnover_Ratio": 0.53}', '{"volume_metrics": {"Vol_3M": 71812, "Vol_Recent": 92530}, "moving_averages": {"MA_50": 99.617, "MA_200": 93.486}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.66, "PE_Ratio": 33.74, "PS_Ratio": 2.41, "PCF_Ratio": 16.45}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (842, 'GRN', 'ETF', 'U.S.', 'AAMA Equity Fund', 'AAMA Equity Fund', 'AmericanDollar', NULL, NULL, 'AAMA', 'PCX', NULL, 61024408, NULL, '2019-09-10', NULL, 'The investment seeks to generate long term capital appreciation. The fund, under normal market circumstances, will invest at least 80% of its net assets (including the amount of any borrowings for investment purposes) in equity securities of any size capitalization. It invests primarily in common stocks and ETFs, but may also invest in other types of equity securities including, preferred stock, investments in foreign equity securities through U.S. stock exchange listed ADRs, REITs, or mutual funds that invest in the types of securities in which the fund would normally invest, and securities convertible into such securities.', NULL, NULL, 64399, 105591, 25.06, 21.47, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 61024408, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 64399, "Vol_Recent": 105591}, "moving_averages": {"MA_50": 25.06, "MA_200": 21.47}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
