INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (862, 'GUSH', 'ETF', 'UNITED_STATES', 'AB Municipal Income Fund II - M', 'AB Municipal Income Fund II Minnesota Portfolio Class A', 'US$', 'Value', 'Medium', 'AllianceBernstein', 'PCX', 'Trading--Leveraged Equity', 902520832, 0.0007, '2015-05-28', 3.15, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Minnesota personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund normally invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal AMT for certain taxpayers.', 0.0114, 0.009, 2041946, 2.05037e+06, 105.336, 83.169, NULL, NULL, NULL, NULL, NULL, 1.41, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 902520832, "Yield_Rate": 0.0007, "Expense_Net": 0.0114, "Benchmark_Exp": 0.009, "Turnover_Ratio": 3.15}', '{"volume_metrics": {"Vol_3M": 2041946, "Vol_Recent": 2050370}, "moving_averages": {"MA_50": 105.336, "MA_200": 83.169}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 1.41, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (863, 'GVAL', 'ETF', 'US', 'AB Municipal Income Fund II - M', 'AB Municipal Income Fund II Minnesota Portfolio Class C', 'usd', 'Value', 'Medium', 'AllianceBernstein', 'BTS', 'Foreign Small/Mid Value', 122442640, 0.0271, '2014-03-11', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Minnesota personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund normally invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal AMT for certain taxpayers.', 0.0065, 0.0051, 25614, 33110, 23.68, 23.312, NULL, NULL, 1.02, 4.6, 12.31, 0.83, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 122442640, "Yield_Rate": 0.0271, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0051, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 25614, "Vol_Recent": 33110}, "moving_averages": {"MA_50": 23.68, "MA_200": 23.312}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.02, "PE_Ratio": 12.31, "PS_Ratio": 0.83, "PCF_Ratio": 4.6}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (864, 'GVIP', 'ETF', 'UNITED_STATES', 'AQR Large Cap Momentum Style Fu', 'AQR Large Cap Momentum Style Fund Class I', 'Dollar', 'Growth', 'Large', 'AQR Funds', 'PCX', 'Large Growth', 220974224, NULL, '2016-11-01', 1.24, 'The investment seeks long-term capital appreciation. The fund pursues a momentum investment style by investing primarily in equity or equity-related securities (including, but not limited to, exchange-traded funds, equity index futures and real estate investment trusts) of large-cap companies traded on a principal U.S. exchange or over-the-counter market that the Adviser determines to have positive momentum. Under normal market circumstances, it will invest at least 80% of its net assets (including any borrowings for investment purposes) in large-cap U.S. companies.', 0.0045, 0.0039, 5819, 7380, 102.435, 99.949, 1, 0, 4.09, 18.91, 28.38, 3.82, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 220974224, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 1.24}', '{"volume_metrics": {"Vol_3M": 5819, "Vol_Recent": 7380}, "moving_averages": {"MA_50": 102.435, "MA_200": 99.949}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.09, "PE_Ratio": 28.38, "PS_Ratio": 3.82, "PCF_Ratio": 18.91}}');
