INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (867, 'GXG', 'ETF', 'US', 'AMCAP Fund, Class C Shares', 'American Funds AMCAP Fund Class C', 'usd', 'Value', 'Medium', 'American Funds', 'PCX', 'Miscellaneous Region', 37946912, 0.031, '2009-02-05', 0.2085, 'The investment seeks long-term growth of capital. The fund invests primarily in common stocks of U.S. companies that have solid long-term growth records and the potential for good future growth. The basic investment philosophy of the investment adviser is to seek to invest in attractively valued companies that, in its opinion, represent good, long-term investment opportunities.', 0.0062, 0.0053, 7766, 14920, 29.783, 28.624, 0.9987, 0, 1.11, 5.78, 17.47, 1.2, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 37946912, "Yield_Rate": 0.031, "Expense_Net": 0.0062, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.2085}', '{"volume_metrics": {"Vol_3M": 7766, "Vol_Recent": 14920}, "moving_averages": {"MA_50": 29.783, "MA_200": 28.624}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.11, "PE_Ratio": 17.47, "PS_Ratio": 1.2, "PCF_Ratio": 5.78}}');
