INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (871, 'HAP', 'ETF', 'usa', 'American Growth Fund, Inc. - Cl', 'American Growth Fund Series One Class C', 'DOLLAR', 'Value', 'Large', 'American Growth', 'PCX', 'Natural Resources', 76142640, 0.0205, '2008-08-29', 0.26, 'The investment seeks growth of capital. The fund uses a consistent approach to build the fund''s security portfolio which is made up primarily of common stocks and securities convertible into common stock. These securities are issued by large companies, and to a lesser extent, small and mid-sized companies. When a company''s fundamentals are strong, the managers believe earnings growth will follow.', 0.0049, 0.0048, 10111, 3620, 47.425, 46.324, 0.9981, 0, 1.94, 9.33, 18.86, 1.24, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 76142640, "Yield_Rate": 0.0205, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.26}', '{"volume_metrics": {"Vol_3M": 10111, "Vol_Recent": 3620}, "moving_averages": {"MA_50": 47.425, "MA_200": 46.324}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.94, "PE_Ratio": 18.86, "PS_Ratio": 1.24, "PCF_Ratio": 9.33}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (872, 'HART', 'ETF', 'U.S.A.', 'American Growth Fund Series Two', 'American Growth Cannabis Fund Class E', 'US Dollar', 'Blend', 'Large', 'American Growth', 'PCX', 'Health', 6867152, NULL, '2021-01-14', NULL, 'The investment seeks growth of capital; income is a secondary investment objective. The Adviser uses a consistent approach to build the fund''s security portfolio which is made up primarily of common stocks involved in the legal cannabis and hemp businesses. It may also invest in securities convertible into common stock in companies involved in the legal cannabis and hemp business. These securities may be issued by large companies and also small and mid-sized companies, micro-cap companies as well as REITs.', 0.0045, 0.0049, 209, 460, 28.17, 27.313, 0.999, 0, 5.35, 15.59, 27.79, 2.64, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 6867152, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0049, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 209, "Vol_Recent": 460}, "moving_averages": {"MA_50": 28.17, "MA_200": 27.313}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.35, "PE_Ratio": 27.79, "PS_Ratio": 2.64, "PCF_Ratio": 15.59}}');
