INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (889, 'HELX', 'ETF', 'U.S.', 'AB Global Bond Fund, Inc. - Cla', 'AB Global Bond Fund Class C', 'Usd', 'Growth', 'Medium', 'AllianceBernstein', 'BTS', NULL, 15278245, 0.0001, '2020-02-25', 0.4658, 'The investment seeks to generate current income consistent with preservation of capital. The fund invests at least 80% of its net assets in fixed-income securities. It invests significantly in fixed-income securities of non-U.S. companies. The fund normally invests in the fixed-income securities of companies located in at least three countries. It may invest in a broad range of fixed-income securities in both developed and emerging markets. The fund may invest across all fixed-income sectors, including U.S. and non-U.S. government and corporate debt securities.', 0.005, NULL, 7888, 4040, 51.202, 48.902, NULL, NULL, 8.38, 30.33, 42.07, 7.72, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 15278245, "Yield_Rate": 0.0001, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": 0.4658}', '{"volume_metrics": {"Vol_3M": 7888, "Vol_Recent": 4040}, "moving_averages": {"MA_50": 51.202, "MA_200": 48.902}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.38, "PE_Ratio": 42.07, "PS_Ratio": 7.72, "PCF_Ratio": 30.33}}');
