INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (915, 'HTRB', 'ETF', 'usa', 'Angel Oak Financials Income Fun', 'Angel Oak Financials Income Fund Institutional Class', 'US_DOLLAR', NULL, NULL, 'Angel Oak', 'PCX', NULL, 1009747520, 0.0247, '2017-09-27', 0.79, 'The investment seeks current income with a secondary objective of total return. The fund invests primarily in debt issued by financial institutions, including subordinated debt ("sub-debt"), senior debt, preferred securities, high yield securities and trust-preferred securities ("TruPS"). It will under normal circumstances, invest at least 80% of the value of its net assets plus the amount of any borrowings for investment purposes in the securities of financial institutions (measured at the time of purchase).', 0.0029, NULL, 159172, 93570, 40.663, 40.783, NULL, NULL, NULL, NULL, NULL, NULL, 8.6, 5.98, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 1009747520, "Yield_Rate": 0.0247, "Expense_Net": 0.0029, "Benchmark_Exp": null, "Turnover_Ratio": 0.79}', '{"volume_metrics": {"Vol_3M": 159172, "Vol_Recent": 93570}, "moving_averages": {"MA_50": 40.663, "MA_200": 40.783}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.6, "Duration_Yrs": 5.98}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
