INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (917, 'HUSV', 'ETF', 'US', 'AllianzGI Small-Cap Value Fund ', 'Virtus NFJ Small-Cap Value Fund Class R6', 'Dollar', 'Value', 'Large', 'Virtus', 'PCX', 'Large Blend', 115834512, 0.0139, '2016-08-24', 2.11, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 80% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities of companies with smaller market capitalizations. The manager currently considers smaller market capitalization companies to be companies with market capitalizations of between $100 million and the greater of $4 billion or the capitalization of the largest company in the Russell 2000 Index. The fund normally invests significantly in securities of companies that the portfolio managers expect will generate income (for example, by paying dividends).', 0.007, 0.0036, 11651, 7720, 33.269, 32.013, 0.9957, 0, 4.41, 15.25, 23.29, 2.86, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 115834512, "Yield_Rate": 0.0139, "Expense_Net": 0.007, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 2.11}', '{"volume_metrics": {"Vol_3M": 11651, "Vol_Recent": 7720}, "moving_averages": {"MA_50": 33.269, "MA_200": 32.013}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9957}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.41, "PE_Ratio": 23.29, "PS_Ratio": 2.86, "PCF_Ratio": 15.25}}');
