INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (929, 'HYLS', 'ETF', 'USA', 'AllianzGI Convertible Fund Admi', 'Virtus AllianzGI Convertible Fund Administrative Class', 'US Dollar', NULL, NULL, 'Virtus', 'NGM', 'High Yield Bond', 2362410752, 0.054, '2013-02-25', 0.68, 'The investment seeks maximum total return, consisting of capital appreciation and current income. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in convertible securities. Convertible securities include, but are not limited to, corporate bonds, debentures, notes or preferred stocks and their hybrids that can be converted into (exchanged for) equity securities or other securities (such as warrants or options) that provide an opportunity for equity participation.', 0.0101, 0.0047, 242419, 296620, 47.871, 48.374, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2.08, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 2362410752, "Yield_Rate": 0.054, "Expense_Net": 0.0101, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.68}', '{"volume_metrics": {"Vol_3M": 242419, "Vol_Recent": 296620}, "moving_averages": {"MA_50": 47.871, "MA_200": 48.374}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 2.08}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
