INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (960, 'IDHD', 'ETF', 'U.S.A.', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund New York Portfolio Class C', 'USD', 'Value', 'Large', 'AllianceBernstein', 'BTS', 'Foreign Large Value', 18855884, 0.039, '2016-12-01', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and New York State and City income tax that is available without assuming what the Adviser considers to be undue risk to principal or income. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of New York or municipal securities with interest that is otherwise exempt from New York state income tax.', 0.003, 0.0046, 2388, 2100, 26.771, 27.125, 1, 0, 1.18, 6.61, 16.6, 1.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 18855884, "Yield_Rate": 0.039, "Expense_Net": 0.003, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2388, "Vol_Recent": 2100}, "moving_averages": {"MA_50": 26.771, "MA_200": 27.125}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.18, "PE_Ratio": 16.6, "PS_Ratio": 1.04, "PCF_Ratio": 6.61}}');
