INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (971, 'IEUR', 'ETF', 'United States', 'AB Municipal Income Fund II - O', 'AB Municipal Income Fund II Ohio Portfolio Class A', 'US$', 'Blend', 'Large', 'AllianceBernstein', 'PCX', 'Europe Stock', 5184926208, 0.024, '2014-06-10', 0.03, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Ohio personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Ohio or municipal securities with interest that is otherwise exempt from Ohio state income tax.', 0.0009, 0.0044, 748309, 756200, 57.986, 57.347, 0.9925, 0, 2.03, 10.94, 21.28, 1.57, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 5184926208, "Yield_Rate": 0.024, "Expense_Net": 0.0009, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 748309, "Vol_Recent": 756200}, "moving_averages": {"MA_50": 57.986, "MA_200": 57.347}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9925}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.03, "PE_Ratio": 21.28, "PS_Ratio": 1.57, "PCF_Ratio": 10.94}}');
