INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (990, 'IIGV', 'ETF', 'U.S.', 'AB Municipal Income Fund II - P', 'AB Municipal Income Fund II Pennsylvania Portfolio Class A', 'Usd', NULL, NULL, 'AllianceBernstein', 'PCX', 'Corporate Bond', 34479644, 0.0383, '2018-07-25', 1.78, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and Commonwealth of Pennsylvania personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Pennsylvania or municipal securities with interest that is otherwise exempt from Pennsylvania state income tax.', 0.0013, 0.0017, 7850, 3540, 27.271, 27.39, 0, 0.9984, NULL, NULL, NULL, NULL, 7.87, 6.8, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 34479644, "Yield_Rate": 0.0383, "Expense_Net": 0.0013, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 1.78}', '{"volume_metrics": {"Vol_3M": 7850, "Vol_Recent": 3540}, "moving_averages": {"MA_50": 27.271, "MA_200": 27.39}}', '{"asset_allocation": {"Bond_Weight": 0.9984, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.87, "Duration_Yrs": 6.8}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (991, 'IJAN', 'ETF', 'U.S.A.', 'AB Municipal Income Fund II - P', 'AB Municipal Income Fund II Pennsylvania Portfolio Class Class C', 'USD', 'Blend', 'Large', 'AllianceBernstein', 'PCX', 'Foreign Large Blend', 80490032, NULL, '2019-12-31', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and Commonwealth of Pennsylvania personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Pennsylvania or municipal securities with interest that is otherwise exempt from Pennsylvania state income tax.', 0.0085, 0.0037, 7596, 8610, 27, 26.689, NULL, NULL, 1.85, 10.82, 20.34, 1.57, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 80490032, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7596, "Vol_Recent": 8610}, "moving_averages": {"MA_50": 27, "MA_200": 26.689}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 20.34, "PS_Ratio": 1.57, "PCF_Ratio": 10.82}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (992, 'IJT', 'ETF', 'U.S.A.', 'Cavanal Hill Active Core Fund N', 'Cavanal Hill Active Core Fund Investor Class', 'usd', 'Blend', 'Small', 'Cavanal Hill funds', 'NGM', 'Small Growth', 6375302656, 0.0056, '2000-07-24', 0.52, 'The investment seeks capital appreciation and income. The fund normally invests between 40% and 75% of its net assets in equity securities and at least 25% of its net assets in fixed income securities that are "investment grade," rated at the time of purchase within the four highest ratings categories assigned by a nationally recognized statistical ratings organization, or, if not rated, found by the Adviser under guidelines approved by the Trusts Board of Trustees to be of comparable quality. The equity portion of the fund consists of investments in companies of all market capitalization, including large, mid and small.', 0.0018, 0.0033, 125814, 130550, 135.943, 131.88, 0.9978, 0, 3.46, 13.72, 21.25, 1.6, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 6375302656, "Yield_Rate": 0.0056, "Expense_Net": 0.0018, "Benchmark_Exp": 0.0033, "Turnover_Ratio": 0.52}', '{"volume_metrics": {"Vol_3M": 125814, "Vol_Recent": 130550}, "moving_averages": {"MA_50": 135.943, "MA_200": 131.88}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9978}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.46, "PE_Ratio": 21.25, "PS_Ratio": 1.6, "PCF_Ratio": 13.72}}');
