INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (996, 'IMCV', 'ETF', 'usa', 'Artisan Global Discovery Fund -', 'Artisan Global Discovery Fund Advisor Shares', 'US Dollar', 'Value', 'Medium', 'Artisan', 'NGM', 'Mid-Cap Value', 465371904, 0.0179, '2004-06-28', 0.95, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. and non-U.S. growth companies across a broad capitalization range. The team seeks to invest in companies that it believes possess franchise characteristics, are benefiting from an accelerating profit cycle and are trading at a discount to its estimate of private market value. The fund primarily invests in common stocks and other equity securities of U.S. and non-U.S. companies, including depositary receipts.', 0.0006, 0.0043, 15793, 11240, 66.178, 64.23, 0.9967, 0, 2.36, 11.36, 18, 1.34, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 465371904, "Yield_Rate": 0.0179, "Expense_Net": 0.0006, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 0.95}', '{"volume_metrics": {"Vol_3M": 15793, "Vol_Recent": 11240}, "moving_averages": {"MA_50": 66.178, "MA_200": 64.23}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9967}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.36, "PE_Ratio": 18, "PS_Ratio": 1.34, "PCF_Ratio": 11.36}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (997, 'IMFL', 'ETF', 'America', 'Artisan High Income Fund Adviso', 'Artisan High Income Fund Advisor Shares', 'DOLLAR', 'Value', 'Large', 'Artisan', 'BTS', NULL, 131953568, NULL, '2021-02-24', NULL, 'The investment seeks to provide total return through a combination of current income and capital appreciation. Under normal circumstances, the fund will invest primarily in instruments that are rated, at the time of purchase, below investment grade (below BBB- by Standard & Poor''s Rating Services ("S&P") or Fitch, Inc. ("Fitch") or below Baa3 by Moody''s Investors Service, Inc. ("Moody''s")), or comparably rated by another nationally recognized statistical rating organization ("NRSRO"), or unrated but determined by Artisan Partners to be of comparable quality.', 0.0034, NULL, 2677, 4750, 26.322, 26.635, 0.9988, 0, 1.41, 7.55, 17.46, 0.78, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 131953568, "Yield_Rate": null, "Expense_Net": 0.0034, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2677, "Vol_Recent": 4750}, "moving_averages": {"MA_50": 26.322, "MA_200": 26.635}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.41, "PE_Ratio": 17.46, "PS_Ratio": 0.78, "PCF_Ratio": 7.55}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (998, 'IMLP', 'ETF', 'United States', 'Artisan Global Value Fund Advis', 'Artisan Global Value Fund Advisor Class', 'USD', NULL, NULL, 'Artisan', 'BTS', 'Energy Limited Partnership', 14219336, 0.0684, '2013-01-03', NULL, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of securities of undervalued U.S. and non-U.S. companies. The team seeks to invest in what the team considers to be high quality, undervalued companies with strong balance sheets and shareholder-oriented management teams. Under normal market conditions, the fund primarily invests in common stocks and other equity securities, both within and outside the U.S.', 0.008, 0.0074, 1519, 720, 13.129, 12.533, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 14219336, "Yield_Rate": 0.0684, "Expense_Net": 0.008, "Benchmark_Exp": 0.0074, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1519, "Vol_Recent": 720}, "moving_averages": {"MA_50": 13.129, "MA_200": 12.533}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (999, 'IMOM', 'ETF', 'U.S.A.', 'Artisan Global Equity Fund Advi', 'Artisan Global Equity Fund Advisor Shares', 'US Dollar', 'Growth', 'Medium', 'Artisan', 'BTS', 'Foreign Large Growth', 78840320, NULL, '2015-12-22', NULL, 'The investment seeks maximum long-term capital growth. The fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in equity securities or instruments that have similar economic characteristics. It may invest in securities both within and outside the U.S., including emerging and less developed markets. Securities in which the fund may invest may include common stocks, preferred stocks, convertible securities, depositary receipts and rights and warrants to buy common stocks.', 0.0059, 0.0066, 4853, 5560, 34.729, 34.979, 0.9953, 0, 2.41, 10.56, 15.97, 1.27, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 78840320, "Yield_Rate": null, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0066, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4853, "Vol_Recent": 5560}, "moving_averages": {"MA_50": 34.729, "MA_200": 34.979}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.41, "PE_Ratio": 15.97, "PS_Ratio": 1.27, "PCF_Ratio": 10.56}}');
