INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1001, 'INCO', 'ETF', 'us', 'Artisan International Small-Mid', 'Artisan International Small-Mid Fund Advisor Shares', 'Usd', 'Blend', 'Large', 'Artisan', 'PCX', 'India Equity', 94072760, 0.0031, '2011-08-10', 0.16, 'The investment seeks maximum long-term capital growth. Under normal circumstances, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in common stocks and other securities of small- and mid-cap companies. Under normal market conditions, it will invest at least 65% of its total assets at market value at the time of purchase in securities of non-U.S. companies. The fund invests in developed markets and emerging and less developed markets.', 0.0075, 0.0084, 6476, 5940, 58.603, 54.288, 0.9983, 0.0006, 8.59, 26.22, 47.73, 4.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 94072760, "Yield_Rate": 0.0031, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0084, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 6476, "Vol_Recent": 5940}, "moving_averages": {"MA_50": 58.603, "MA_200": 54.288}}', '{"asset_allocation": {"Bond_Weight": 0.0006, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.59, "PE_Ratio": 47.73, "PS_Ratio": 4.72, "PCF_Ratio": 26.22}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1002, 'INDF', 'ETF', 'America', 'Artisan International Value Fun', 'Artisan International Value Fund Advisor Class', 'US$', 'Growth', 'Large', 'Artisan', 'PCX', NULL, 4774402, NULL, '2020-10-20', NULL, 'The investment seeks maximum long-term capital growth. The focus of the investment process is on individual companies, not on selection of countries or regions. Under normal market conditions, the fund invests no less than 80% of its total assets (excluding cash and cash equivalents), measured at market value at the time of purchase, in common stocks and other securities of non-U.S. companies. The fund invests primarily in developed markets but also may invest in emerging and less developed markets.', 0.0075, NULL, 2380, 1040, 37.474, 34.935, 0.9975, 0, 2.72, NULL, 22.12, 2.8, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 4774402, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2380, "Vol_Recent": 1040}, "moving_averages": {"MA_50": 37.474, "MA_200": 34.935}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9975}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.72, "PE_Ratio": 22.12, "PS_Ratio": 2.8, "PCF_Ratio": null}}');
