INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1009, 'INMU', 'ETF', 'usa', 'Artisan Developing World Fund -', 'Artisan Developing World Fund Advisor Shares', 'US Dollar', NULL, NULL, 'Artisan', 'PCX', 'Muni National Interm', 25548124, NULL, '2021-03-16', NULL, 'The investment seeks long-term capital appreciation. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of securities that offers exposure to developing world economies. In pursuit of this goal, the team generally invests substantially in equity securities of issuers domiciled in or economically tied to countries the team considers to have characteristics typical of the developing world. Under normal circumstances, the fund invests substantially in equity securities of issuers domiciled in or economically tied to one or more markets in the developing world.', 0.003, 0.0029, 1500, 850, 25.556, 25.582, 0, 0.9939, NULL, NULL, NULL, NULL, 4.8, 4.44, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 25548124, "Yield_Rate": null, "Expense_Net": 0.003, "Benchmark_Exp": 0.0029, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1500, "Vol_Recent": 850}, "moving_averages": {"MA_50": 25.556, "MA_200": 25.582}}', '{"asset_allocation": {"Bond_Weight": 0.9939, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 4.8, "Duration_Yrs": 4.44}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1010, 'IPAC', 'ETF', 'US', 'Columbia High Yield Bond Fund C', 'Columbia High Yield Bond Fund Class C', 'AmericanDollar', 'Blend', 'Large', 'Columbia Threadneedle', 'PCX', 'Diversified Pacific/Asia', 1161600512, 0.0197, '2014-06-10', 0.05, 'The investment seeks to provide shareholders with high current income as its primary objective and, as its secondary objective, capital growth. Under normal market conditions, the fund invests at least 80% of its net assets (including the amount of any borrowings for investment purposes) in high-yield debt instruments (commonly referred to as "junk" bonds or securities). It may invest up to 25% of its net assets in debt instruments of foreign issuers. The fund may invest in debt instruments of any maturity and does not seek to maintain a particular dollar-weighted average maturity.', 0.0009, 0.0038, 55958, 70810, 66.66, 67.058, 0.994, 0, 1.49, 9.9, 18.36, 1.31, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 1161600512, "Yield_Rate": 0.0197, "Expense_Net": 0.0009, "Benchmark_Exp": 0.0038, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 55958, "Vol_Recent": 70810}, "moving_averages": {"MA_50": 66.66, "MA_200": 67.058}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.49, "PE_Ratio": 18.36, "PS_Ratio": 1.31, "PCF_Ratio": 9.9}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1011, 'IPAY', 'ETF', 'usa', 'AllianzGI Preferred Securities ', 'Virtus AllianzGI Preferred Securities and Income Fund Institutional Class', 'US Dollar', 'Growth', 'Large', 'Virtus', 'PCX', 'Miscellaneous Sector', 1254936704, NULL, '2015-07-15', 0.19, 'The investment seeks total return consisting of high current income and capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in preferred securities or debt securities issued by U.S. and non-U.S. issuers. Under normal market conditions, it will also invest at least 25% of its total assets in the financials sector. The fund may invest without limit in non-U.S. securities, including securities issued in local currencies, and may invest up to 15% of its assets in emerging markets securities.', 0.0075, 0.0067, 134133, 247350, 65.637, 68.879, 0.9725, 0.022, 4.76, 19.79, 36.55, 4.99, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 1254936704, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0067, "Turnover_Ratio": 0.19}', '{"volume_metrics": {"Vol_3M": 134133, "Vol_Recent": 247350}, "moving_averages": {"MA_50": 65.637, "MA_200": 68.879}}', '{"asset_allocation": {"Bond_Weight": 0.022, "Equity_Weight": 0.9725}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.76, "PE_Ratio": 36.55, "PS_Ratio": 4.99, "PCF_Ratio": 19.79}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1012, 'IPKW', 'ETF', 'U.S.A.', 'Strategic Enhanced Yield Fund I', 'Cavanal Hill Strategic Enhanced Yield Fund Investor', 'Dollar', 'Blend', 'Large', 'Cavanal Hill funds', 'NGM', 'Foreign Large Blend', 135441504, 0.0142, '2014-02-24', 0.88, 'The investment seeks current income and, secondarily, the opportunity for capital appreciation to produce total return. The fund seeks total return by allocating assets among various fixed income sectors, with no more than 65% of its net assets in any one sector. The Adviser will employ a strategy to enhance the fund''s yield by shifting assets among higher yielding and lower yielding debt securities across sectors and different maturities based on its view of the relative value of each sector or maturity. Under normal circumstances, the fund invests at least 80% of its net assets in bonds.', 0.0055, 0.0037, 20356, 21960, 43.545, 44.295, NULL, NULL, 1.55, 8.19, 19.45, 0.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 135441504, "Yield_Rate": 0.0142, "Expense_Net": 0.0055, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.88}', '{"volume_metrics": {"Vol_3M": 20356, "Vol_Recent": 21960}, "moving_averages": {"MA_50": 43.545, "MA_200": 44.295}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.55, "PE_Ratio": 19.45, "PS_Ratio": 0.98, "PCF_Ratio": 8.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1013, 'IPO', 'ETF', 'UNITED_STATES', 'Artisan Global Discovery Fund -', 'Artisan Global Discovery Fund Investor Shares', 'US Dollar', 'Growth', 'Medium', 'Artisan', 'PCX', 'Mid-Cap Growth', 632649792, NULL, '2013-10-16', 1.52, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. and non-U.S. growth companies across a broad capitalization range. The team seeks to invest in companies that it believes possess franchise characteristics, are benefiting from an accelerating profit cycle and are trading at a discount to its estimate of private market value. The fund primarily invests in common stocks and other equity securities of U.S. and non-U.S. companies, including depositary receipts.', 0.006, 0.0046, 128672, 132930, 66.229, 64.292, 0.9992, 0, 10.24, 24.25, NULL, 2.12, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 632649792, "Yield_Rate": null, "Expense_Net": 0.006, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 1.52}', '{"volume_metrics": {"Vol_3M": 128672, "Vol_Recent": 132930}, "moving_averages": {"MA_50": 66.229, "MA_200": 64.292}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.24, "PE_Ratio": null, "PS_Ratio": 2.12, "PCF_Ratio": 24.25}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1014, 'IPOS', 'ETF', 'America', 'AB Large Cap Growth Fund, Inc. ', 'AB Large Cap Growth Fund Class A', 'AmericanDollar', 'Growth', 'Large', 'AllianceBernstein', 'PCX', 'Foreign Small/Mid Growth', 34365552, 0.0019, '2014-10-06', 1.27, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of a limited number of large, carefully selected, high-quality U.S. companies. It invests primarily in the domestic equity securities of companies selected by the fund''s Adviser for their growth potential within various market sectors. The fund emphasizes investments in large, seasoned companies. Under normal circumstances, the fund will invest at least 80% of its net assets in common stocks of large-capitalization companies. It may, at times, invest in shares of exchange-traded funds in lieu of making direct investments in securities.', 0.008, 0.008, 4250, 2940, 29.351, 33.541, 0.9962, 0, 6.32, 21.83, 33.62, 3.6, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 34365552, "Yield_Rate": 0.0019, "Expense_Net": 0.008, "Benchmark_Exp": 0.008, "Turnover_Ratio": 1.27}', '{"volume_metrics": {"Vol_3M": 4250, "Vol_Recent": 2940}, "moving_averages": {"MA_50": 29.351, "MA_200": 33.541}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9962}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6.32, "PE_Ratio": 33.62,