INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1024, 'ISEM', 'ETF', 'usa', 'Artisan International Small-Mid', 'Artisan International Small-Mid Fund Institutional Share', 'Usd', 'Value', 'Large', 'Artisan', 'NGM', 'Diversified Emerging Mkts', 28821446, 0.0256, '2018-09-12', 0.19, 'The investment seeks maximum long-term capital growth. Under normal circumstances, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in common stocks and other securities of small- and mid-cap companies. Under normal market conditions, it will invest at least 65% of its total assets at market value at the time of purchase in securities of non-U.S. companies. The fund invests in developed markets and emerging and less developed markets.', 0.0035, 0.0056, 3198, 5430, 28.925, 29.395, 0.9982, 0, 0.88, 3.63, 9.05, 0.46, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 28821446, "Yield_Rate": 0.0256, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.19}', '{"volume_metrics": {"Vol_3M": 3198, "Vol_Recent": 5430}, "moving_averages": {"MA_50": 28.925, "MA_200": 29.395}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9982}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.88, "PE_Ratio": 9.05, "PS_Ratio": 0.46, "PCF_Ratio": 3.63}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1025, 'ISHG', 'ETF', 'U.S.A.', 'Artisan International Value Fd ', 'Artisan International Value Fund Institutional Class', 'usd', NULL, NULL, 'Artisan', 'NGM', 'World Bond', 57468796, NULL, '2009-01-21', 0.71, 'The investment seeks maximum long-term capital growth. The focus of the investment process is on individual companies, not on selection of countries or regions. Under normal market conditions, the fund invests no less than 80% of its total assets (excluding cash and cash equivalents), measured at market value at the time of purchase, in common stocks and other securities of non-U.S. companies. The fund invests primarily in developed markets but also may invest in emerging and less developed markets.', 0.0035, 0.0042, 3964, 1940, 80.202, 82.142, NULL, NULL, NULL, NULL, NULL, NULL, 1.94, 1.92, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 57468796, "Yield_Rate": null, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0042, "Turnover_Ratio": 0.71}', '{"volume_metrics": {"Vol_3M": 3964, "Vol_Recent": 1940}, "moving_averages": {"MA_50": 80.202, "MA_200": 82.142}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.94, "Duration_Yrs": 1.92}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1026, 'ISMD', 'ETF', 'US', 'Artisan Value Fd Insti Shs', 'Artisan Value Fund Institutional Class', 'Usd', 'Value', 'Small', 'Artisan', 'PCX', 'Small Blend', 121133600, 0.0079, '2017-02-27', 0.92, 'The investment seeks maximum long-term capital growth. The fund may invest up to 25% of its total assets at market value at the time of purchase in securities of non-U.S. issuers (including depositary receipts). Its investments in non-U.S. securities may include investments in developed markets, as well as emerging and less developed markets. The fund invests in common stocks and other securities of companies across a broad capitalization range.', 0.006, 0.004, 16629, 19920, 37.102, 36.306, 0.9904, 0, 2.01, 9.54, 16.18, 1.22, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 121133600, "Yield_Rate": 0.0079, "Expense_Net": 0.006, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.92}', '{"volume_metrics": {"Vol_3M": 16629, "Vol_Recent": 19920}, "moving_averages": {"MA_50": 37.102, "MA_200": 36.306}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9904}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.01, "PE_Ratio": 16.18, "PS_Ratio": 1.22, "PCF_Ratio": 9.54}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1027, 'ISTB', 'ETF', 'America', 'Artisan Mid Cap Fd Insti Shs', 'Artisan Mid Cap Fund Institutional Class', 'US Dollar', 'Growth', 'Small', 'Artisan', 'NGM', 'Short-Term Bond', 5498013184, 0.0191, '2012-10-18', 0.77, 'The investment seeks maximum long-term capital growth. The fund normally invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in the common stocks of medium-sized companies. It defines a medium-sized company as one with a market capitalization greater than the market capitalization of the smallest company in the Russell Midcap© Index and less than three times the weighted average market capitalization of companies in the index.', 0.0006, 0.0026, 544933, 628250, 50.776, 51.17, NULL, NULL, 1.64, 4.14, NULL, 2.64, 2.89, 2.78, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 5498013184, "Yield_Rate": 0.0191, "Expense_Net": 0.0006, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.77}', '{"volume_metrics": {"Vol_3M": 544933, "Vol_Recent": 628250}, "moving_averages": {"MA_50": 50.776, "MA_200": 51.17}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.89, "Duration_Yrs": 2.78}}', '{"valuation_metrics": {"PB_Ratio": 1.64, "PE_Ratio": null, "PS_Ratio": 2.64, "PCF_Ratio": 4.14}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1028, 'ISWN', 'ETF', 'U.S.', 'Artisan Select Equity Fund - In', 'Artisan Select Equity Fund Institutional Shares', 'Dollar', 'Blend', 'Large', 'Artisan', 'PCX', NULL, 33717144, NULL, '2021-01-25', NULL, 'The investment seeks maximum long-term capital growth. Under normal market conditions, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in equity securities or instruments that have similar economic characteristics. It will invest primarily in U.S. companies but may invest up to 20% of its total assets at market value at the time of purchase in non-U.S. companies, including those in emerging and less developed markets. The fund is non-diversified.', 0.0049, NULL, 9030, 2650, 25.287, 25.254, 0.2044, 0.7926, 1.84, 10.75, 22.04, 1.55, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 33717144, "Yield_Rate": null, "Expense_Net": 0.0049, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 9030, "Vol_Recent": 2650}, "moving_averages": {"MA_50": 25.287, "MA_200": 25.254}}', '{"asset_allocation": {"Bond_Weight": 0.7926, "Equity_Weight": 0.2044}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.84, "PE_Ratio": 22.04, "PS_Ratio": 1.55, "PCF_Ratio": 10.75}}');
