INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1040, 'IVOG', 'ETF', 'U.S.', 'AMG Managers Pictet Internation', 'AMG Beutel Goodman International Equity Fund - Class N', 'US Dollar', 'Growth', 'Medium', 'AMG Funds', 'PCX', 'Mid-Cap Growth', 1091176448, 0.0066, '2010-09-07', 0.49, 'The investment seeks to provide capital appreciation. The fund invests primarily in equity securities of non-U.S. companies. Under normal circumstances, it invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities. The fund may invest in securities of any market capitalization. Under normal circumstances, it invests at least 40% of its net assets in investments economically tied to countries other than the U.S., and the fund will hold investments economically tied to a minimum of three countries other than the U.S. It is non-diversified.', 0.0015, 0.0046, 6582, 8900, 207.984, 200.91, 1, 0, 4.42, 17.06, 28.22, 2.89, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 1091176448, "Yield_Rate": 0.0066, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 6582, "Vol_Recent": 8900}, "moving_averages": {"MA_50": 207.984, "MA_200": 200.91}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 28.22, "PS_Ratio": 2.89, "PCF_Ratio": 17.06}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1041, 'IVOL', 'ETF', 'U.S.', 'American Century Short Duration', 'American Century Short Duration Inflation Protection Bond Fund R5 Class', 'US$', 'Growth', 'Large', 'American Century Investments', 'PCX', NULL, 3240003584, 0.0351, '2019-05-13', NULL, 'The investment seeks total return using a strategy that seeks to protect against U.S. inflation. The fund normally invests at least 80% of its net assets in inflation-linked debt securities. It invests primarily in investment-grade securities, but may also invest a portion of its assets in high-yield securities, or junk bonds. The fund also may invest a portion of its net assets in fixed-income securities that are not linked to inflation. It may invest up to 20% of its total assets in securities denominated in foreign currencies and may invest beyond this limit in U.S. dollar denominated securities of foreign issuers.', 0.0099, NULL, 1363432, 1.98609e+06, 27.582, 28.1, NULL, NULL, NULL, NULL, NULL, NULL, 8.06, 7.56, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 3240003584, "Yield_Rate": 0.0351, "Expense_Net": 0.0099, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1363432, "Vol_Recent": 1986090}, "moving_averages": {"MA_50": 27.582, "MA_200": 28.1}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.06, "Duration_Yrs": 7.56}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1200, 'LUXE', 'ETF', 'USA', 'American Century One Choice 202', 'American Century Investments One Choice 2025 Portfolio C Class', 'Usd', 'Growth', 'Large', 'American Century Investments', 'BTS', NULL, 2976577, NULL, '2020-11-24', NULL, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The target date in the fund name (2025) refers to the approximate year an investor plans to retire and likely would stop making new investments in the fund.', 0.006, NULL, 6198, 4930, 31.067, 30.398, 1, 0, 3.42, 15.01, 31.07, 2.42, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 2976577, "Yield_Rate": null, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6198, "Vol_Recent": 4930}, "moving_averages": {"MA_50": 31.067, "MA_200": 30.398}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.42, "PE_Ratio": 31.07, "PS_Ratio": 2.42, "PCF_Ratio": 15.01}}');
