INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1055, 'JANZ', 'ETF', 'U.S.', 'Appleseed Fund Institutional Cl', 'Appleseed Fund Institutional Share', 'Dollar', 'Blend', 'Large', 'Appleseed Fund', 'BTS', NULL, 3515894, NULL, '2020-12-31', NULL, 'The investment seeks long-term capital appreciation. The fund invests primarily in a portfolio of equity securities of companies that are undervalued in the opinion of the fund''s adviser, Pekin Hardy Strauss, Inc. (the "Advisor"). When selecting common stocks for investment by the fund, the Advisor focuses on company valuation, looking for significant discrepancies between its own appraisal of the intrinsic value of a prospective investment and the market price of the investment. The fund is non-diversified.', 0.0079, NULL, 279, 70, 29.294, 28.086, 0.1244, 0.8734, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 3515894, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 279, "Vol_Recent": 70}, "moving_averages": {"MA_50": 29.294, "MA_200": 28.086}}', '{"asset_allocation": {"Bond_Weight": 0.8734, "Equity_Weight": 0.1244}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1057, 'JCTR', 'ETF', 'USA', 'The AB Portfolios - AB Conserva', 'AB Conservative Wealth Strategy Class R', 'usd', 'Blend', 'Large', 'AllianceBernstein', 'PCX', NULL, 25283690, NULL, '2020-12-09', NULL, 'The investment seeks to achieve a high total return without, in the opinion of the Adviser, undue risk to principal. The Adviser allocates the fund''s investments among a number of asset classes, including fixed-income securities, equity securities, and alternative asset classes and alternative investment strategies. The fund seeks to have generally greater exposure to fixed-income securities than equity securities or alternative asset classes and alternative investment strategies.', 0.0015, NULL, 1188, 2180, 61.461, 58.031, 0.9983, 0, 4.42, 17.51, 27.53, 3.06, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 25283690, "Yield_Rate": null, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1188, "Vol_Recent": 2180}, "moving_averages": {"MA_50": 61.461, "MA_200": 58.031}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 27.53, "PS_Ratio": 3.06, "PCF_Ratio": 17.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1059, 'JDST', 'ETF', 'U.S.A.', 'AAM/Phocas Real Estate Fund Cla', 'AAM/Phocas Real Estate Fund Class I Shares', 'US Dollar', NULL, NULL, 'AAM', 'PCX', 'Trading--Inverse Equity', 76343264, NULL, '2013-10-03', NULL, 'The investment seeks long-term total investment return through a combination of capital appreciation and current income. Under normal market conditions, the fund invests at least 80% of its net assets, plus borrowings for investment purposes, in securities of equity real estate investment trusts ("REITs") and companies of any size market capitalization which primarily own, manage and invest in underlying real estate assets. Therefore, it invests at least 25% of its net assets (i.e., concentrates) in the real estate industry. The fund is non-diversified.', 0.0105, 0.0092, 2874906, 2.82765e+06, 11.26, 10.859, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 76343264, "Yield_Rate": null, "Expense_Net": 0.0105, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2874906, "Vol_Recent": 2827650}, "moving_averages": {"MA_50": 11.26, "MA_200": 10.859}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1060, 'JEMA', 'ETF', 'America', 'Fiera Capital Small/Mid-Cap Gro', 'Fiera Capital Small/Mid-Cap Growth Fund Institutional Class', 'US Dollar', 'Blend', 'Large', 'Fiera Capital', 'BTS', 'Diversified Emerging Mkts', 102027960, NULL, '2021-03-10', NULL, 'The investment seeks to achieve long-term capital growth. Under normal circumstances, the fund will invest at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in common stocks of small- and mid-cap companies. The fund may invest up to 15% of its assets in common stocks of foreign small- and mid-cap companies through the purchase of American Depository Receipts ("ADRs") and/or foreign domiciled companies listed on U.S. stock exchanges.', 0.0033, 0.0056, 11761, 8710, 47.981, 48.971, NULL, NULL, 2.66, 12.33, 19.02, 1.65, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 102027960, "Yield_Rate": null, "Expense_Net": 0.0033, "Benchmark_Exp": 0.0056, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11761, "Vol_Recent": 8710}, "moving_averages": {"MA_50": 47.981, "MA_200": 48.971}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.66, "PE_Ratio": 19.02, "PS_Ratio": 1.65, "PCF_Ratio": 12.33}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1061, 'JEPI', 'ETF', 'UNITED_STATES', 'Pinnacle Sherman Multi-Strategy', 'Pinnacle Sherman Multi-Strategy Core Fund Class A', 'US$', 'Blend', 'Large', 'Pinnacle', 'PCX', NULL, 1542572544, 0.0757, '2020-05-20', 0.13, 'The investment seeks high total return with reasonable risk. The fund seeks to meet its investment objective by investing, under normal market conditions, in all major asset classes including, but not limited to, foreign and domestic (i) equity securities of all market capitalizations, (ii) fixed income securities of any credit quality, and (iii) cash and cash equivalents. The advisor intends to generally invest in a mix of asset classes. It may invest in individual securities or in exchange traded funds ("ETFs"), and may invest in emerging markets. The fund may also make its cash investments directly.', 0.0035, NULL, 909312, 1.02387e+06, 61.16, 60.068, NULL, NULL, 4.73, 16.47, 27.69, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 1542572544, "Yield_Rate": 0.0757, "Expense_Net": 0.0035, "Benchmark_Exp": null, "Turnover_Ratio": 0.13}', '{"volume_metrics": {"Vol_3M": 909312, "Vol_Recent": 1023870}, "moving_averages": {"MA_50": 61.16, "MA_200": 60.068}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.73, "PE_Ratio": 27.69, "PS_Ratio": 2.89, "PCF_Ratio": 16.47}}');
