INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1089, 'JJP', 'ETF', 'United States', 'Arbitrage Fund Class C', 'The Arbitrage Fund Class C', 'US$', NULL, NULL, 'Arbitrage Fund', 'PCX', NULL, 6358455, NULL, '2018-01-17', NULL, 'The investment seeks to achieve capital growth by engaging in merger arbitrage. The fund will invest at least 80% of its net assets in equity securities of companies (both U.S. and foreign) that are involved in publicly announced mergers, takeovers, tender offers, leveraged buyouts, spin-offs, liquidations and other corporate reorganizations. Equity securities include common and preferred stock. Merger arbitrage is a highly specialized investment approach designed to profit from the successful completion of mergers, takeovers, tender offers, leveraged buyouts, spin-offs, liquidations and other corporate reorganizations.', 0.0045, NULL, 196, 180, 62.795, 63.962, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 6358455, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 196, "Vol_Recent": 180}, "moving_averages": {"MA_50": 62.795, "MA_200": 63.962}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
