INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1094, 'JMIN', 'ETF', 'usa', 'Water Island Credit Opportuniti', 'Water Island Credit Opportunities Fund Class C', 'AmericanDollar', 'Value', 'Large', 'Arbitrage Fund', 'PCX', 'Large Blend', 19340992, 0.0226, '2017-11-08', NULL, 'The investment seeks to provide current income and capital growth. The fund invests primarily in a portfolio of debt securities including corporate bonds and debentures (including high yield bonds commonly known as "junk bonds"), bank loans, convertible and preferred securities, credit default swaps and other debt instruments and derivatives that the fund''s investment adviser believes have debt-like characteristics. It invests in both domestic and foreign debt securities. The principal types of derivatives in which the fund may invest are credit default swaps, interest rate swaps, total return swaps, futures and options.', 0.0012, 0.0036, 2488, 1490, 36.41, 35.322, 0.9986, 0, 3.27, 14.28, 23.39, 1.82, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 19340992, "Yield_Rate": 0.0226, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2488, "Vol_Recent": 1490}, "moving_averages": {"MA_50": 36.41, "MA_200": 35.322}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.27, "PE_Ratio": 23.39, "PS_Ratio": 1.82, "PCF_Ratio": 14.28}}');
