INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1097, 'JNK', 'ETF', 'usa', 'AQR Risk-Balanced Commodities F', 'AQR Risk-Balanced Commodities Strategy Fund Class I', 'US_DOLLAR', 'Value', 'Small', 'AQR Funds', 'PCX', 'High Yield Bond', 9782642688, 0.0466, '2007-11-28', 0.5, 'The investment seeks total return. The fund pursues its investment objective by allocating assets among various commodity sectors (including agricultural, energy, livestock, softs (e.g., non-grain agricultural products such as coffee, sugar, cocoa, etc.) and precious and base metals). It also invests in fixed income securities and money market instruments. The fund will obtain exposure to commodity sectors by investing in commodity-linked derivatives, directly or through its investment in the Subsidiary. It is non-diversified.', 0.004, 0.0047, 8613952, 1.120584e+07, 108.475, 108.934, NULL, NULL, NULL, NULL, NULL, 0.25, 6.27, 3.57, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 9782642688, "Yield_Rate": 0.0466, "Expense_Net": 0.004, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.5}', '{"volume_metrics": {"Vol_3M": 8613952, "Vol_Recent": 11205840}, "moving_averages": {"MA_50": 108.475, "MA_200": 108.934}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.27, "Duration_Yrs": 3.57}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 0.25, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1098, 'JNUG', 'ETF', 'U.S.A.', 'American Century One Choice 203', 'American Century Investments One Choice 2030 Portfolio A Class', 'Usd', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Trading--Leveraged Equity', 603413184, 0.0041, '2013-10-03', 3.12, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The target date in the fund name (2030) refers to the approximate year an investor plans to retire and likely would stop making new investments in the fund.', 0.0108, 0.009, 1163335, 949150, 66.798, 79.8, NULL, NULL, 1.74, 6.91, 15.81, 1.97, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 603413184, "Yield_Rate": 0.0041, "Expense_Net": 0.0108, "Benchmark_Exp": 0.009, "Turnover_Ratio": 3.12}', '{"volume_metrics": {"Vol_3M": 1163335, "Vol_Recent": 949150}, "moving_averages": {"MA_50": 66.798, "MA_200": 79.8}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.74, "PE_Ratio": 15.81, "PS_Ratio": 1.97, "PCF_Ratio": 6.91}}');
