INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1113, 'JSCP', 'ETF', 'us', 'AB Global Real Estate Investmen', 'AB Global Real Estate Investment Fund Class A', 'AmericanDollar', NULL, NULL, 'AllianceBernstein', 'PCX', 'Short-Term Bond', 92367624, NULL, '2021-03-01', NULL, 'The investment seeks total return from long-term growth of capital and income. Under normal circumstances, the fund invests at least 80% of its net assets in the equity securities of real estate investment trusts, or REITs, and other real estate industry companies, such as real estate operating companies, or REOCs. It invests in U.S. and non-U.S. issuers. Under normal circumstances, it invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. In addition, the fund invests, under normal circumstances, in the equity securities of companies located in at least three countries.', 0.0033, 0.0026, 21953, 17780, 49.978, 50.16, NULL, NULL, NULL, NULL, NULL, NULL, 3.48, 2.12, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 92367624, "Yield_Rate": null, "Expense_Net": 0.0033, "Benchmark_Exp": 0.0026, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 21953, "Vol_Recent": 17780}, "moving_averages": {"MA_50": 49.978, "MA_200": 50.16}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.48, "Duration_Yrs": 2.12}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": n