INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1131, 'KBWR', 'ETF', 'U.S.A.', 'Arbitrage Fund, Class A', 'The Arbitrage Fund Class A', 'Usd', 'Value', 'Small', 'Arbitrage Fund', 'NGM', 'Financial', 75919096, 0.0208, '2011-11-01', 0.21, 'The investment seeks to achieve capital growth by engaging in merger arbitrage. The fund will invest at least 80% of its net assets in equity securities of companies (both U.S. and foreign) that are involved in publicly announced mergers, takeovers, tender offers, leveraged buyouts, spin-offs, liquidations and other corporate reorganizations. Equity securities include common and preferred stock. Merger arbitrage is a highly specialized investment approach designed to profit from the successful completion of mergers, takeovers, tender offers, leveraged buyouts, spin-offs, liquidations and other corporate reorganizations.', 0.0035, 0.0038, 6903, 3560, 63.825, 61.541, 1, 0, 1.32, NULL, 13.72, 3.8, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 75919096, "Yield_Rate": 0.0208, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0038, "Turnover_Ratio": 0.21}', '{"volume_metrics": {"Vol_3M": 6903, "Vol_Recent": 3560}, "moving_averages": {"MA_50": 63.825, "MA_200": 61.541}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.32, "PE_Ratio": 13.72, "PS_Ratio": 3.8, "PCF_Ratio": null}}');
