INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1132, 'KBWY', 'ETF', 'us', 'One Choice 2060 Portfolio - R6 ', 'American Century Investments One Choice 2060 Portfolio R6 Class', 'Usd', 'Value', 'Small', 'American Century Investments', 'NGM', 'Real Estate', 354506048, 0.0718, '2010-12-02', 1, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The underlying stock funds draw on growth, value and quantitative investment techniques and diversify investments among small, medium and large U.S. and foreign companies. The underlying bond funds invest in fixed-income securities that vary by issuer type (corporate and government), credit quality and geographic exposure (domestic and international).', 0.0035, 0.0037, 121179, 114520, 23.981, 23.379, 1, 0, 1.14, 9.24, 24.19, 2.49, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 354506048, "Yield_Rate": 0.0718, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 1}', '{"volume_metrics": {"Vol_3M": 121179, "Vol_Recent": 114520}, "moving_averages": {"MA_50": 23.981, "MA_200": 23.379}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.14, "PE_Ratio": 24.19, "PS_Ratio": 2.49, "PCF_Ratio": 9.24}}');
