INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1140, 'KGRN', 'ETF', 'usa', 'American Century One Choice 206', 'American Century Investments One Choice 2065 Portfolio C Class', 'Dollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'China Region', 186036288, 0.0001, '2017-10-12', 1.64, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds that represent a variety of asset classes and investment styles. As the target date approaches, the fund''s neutral mix will become more conservative by decreasing the allocation to stocks and increasing the allocation to bonds and cash. By the time the fund reaches its target date, the neutral mix will become fixed and match that of One Choice In Retirement Portfolio, which is currently 45% stock funds, 45% bond funds and 10% money market funds.', 0.0079, 0.0068, 36461, 34220, 47.357, 44.726, 0.9988, 0, 2.34, 11.69, 16.33, 1.25, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 186036288, "Yield_Rate": 0.0001, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0068, "Turnover_Ratio": 1.64}', '{"volume_metrics": {"Vol_3M": 36461, "Vol_Recent": 34220}, "moving_averages": {"MA_50": 47.357, "MA_200": 44.726}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.34, "PE_Ratio": 16.33, "PS_Ratio": 1.25, "PCF_Ratio": 11.69}}');
