INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1144, 'KLDW', 'ETF', 'USA', 'American Century One Choice 206', 'American Century Investments One Choice 2065 Portfolio I Class', 'US Dollar', 'Growth', 'Large', 'American Century Investments', 'PCX', NULL, 192845168, 0.0055, '2015-07-07', 0.31, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds that represent a variety of asset classes and investment styles. As the target date approaches, the fund''s neutral mix will become more conservative by decreasing the allocation to stocks and increasing the allocation to bonds and cash. By the time the fund reaches its target date, the neutral mix will become fixed and match that of One Choice In Retirement Portfolio, which is currently 45% stock funds, 45% bond funds and 10% money market funds.', 0.0075, NULL, 3551, 4030, 47.839, 46.509, 0.9967, 0, 2.98, 14.31, 29.48, 2.07, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 192845168, "Yield_Rate": 0.0055, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 3551, "Vol_Recent": 4030}, "moving_averages": {"MA_50": 47.839, "MA_200": 46.509}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9967}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.98, "PE_Ratio": 29.48, "PS_Ratio": 2.07, "PCF_Ratio": 14.31}}');
