INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1167, 'LBJ', 'ETF', 'America', 'AMG River Road Focused Absolute', 'AMG River Road Focused Absolute Value Fund Class N', 'Usd', 'Blend', 'Large', 'AMG Funds', 'PCX', 'Trading--Leveraged Equity', 30744126, 0.0037, '2009-12-03', 0.71, 'The investment seeks to provide long-term capital appreciation. The fund principally invests in a portfolio of equity securities of U.S. and non-U.S. companies and may invest in securities of all market capitalizations. Under normal conditions, the advisor intends to invest the fund''s assets in the equity securities of a limited number of issuers. It will primarily invest in common stocks, real estate investment trusts ("REITs") and publicly traded partnerships ("PTPs"), including, but not limited to, master limited partnerships ("MLPs"). The fund is non-diversified.', 0.0123, 0.009, 4095, 3690, 58.275, 72.56, NULL, NULL, 2.24, 6.17, 14.24, 1.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 30744126, "Yield_Rate": 0.0037, "Expense_Net": 0.0123, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.71}', '{"volume_metrics": {"Vol_3M": 4095, "Vol_Recent": 3690}, "moving_averages": {"MA_50": 58.275, "MA_200": 72.56}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.24, "PE_Ratio": 14.24, "PS_Ratio": 1.96, "PCF_Ratio": 6.17}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1168, 'LCG', 'ETF', 'U.S.A.', 'AB Global Real Estate Investmen', 'AB Global Real Estate Investment Fund Class K', 'DOLLAR', 'Growth', 'Large', 'AllianceBernstein', 'PCX', 'Large Growth', 23228484, NULL, '2020-08-26', NULL, 'The investment seeks total return from long-term growth of capital and income. Under normal circumstances, the fund invests at least 80% of its net assets in the equity securities of real estate investment trusts, or REITs, and other real estate industry companies, such as real estate operating companies, or REOCs. It invests in U.S. and non-U.S. issuers. Under normal circumstances, it invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. In addition, the fund invests, under normal circumstances, in the equity securities of companies located in at least three countries.', 0.0059, 0.0039, 20109, 6510, 31.038, 29.096, 0.9975, 0, 13.95, 33.18, 46.64, 11.05, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 23228484, "Yield_Rate": null, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0039, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 20109, "Vol_Recent": 6510}, "moving_averages": {"MA_50": 31.038, "MA_200": 29.096}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9975}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 13.95, "PE_Ratio": 46.64, "PS_Ratio": 11.05, "PCF_Ratio": 33.18}}');
