INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1190, 'LOWC', 'ETF', 'us', 'Artisan International Value Fun', 'Artisan International Value Fund Investor Class', 'AmericanDollar', 'Blend', 'Large', 'Artisan', 'PCX', NULL, 114250656, 0.0155, '2014-11-25', 0.1, 'The investment seeks maximum long-term capital growth. The focus of the investment process is on individual companies, not on selection of countries or regions. Under normal market conditions, the fund invests no less than 80% of its total assets (excluding cash and cash equivalents), measured at market value at the time of purchase, in common stocks and other securities of non-U.S. companies. The fund invests primarily in developed markets but also may invest in emerging and less developed markets.', 0.002, NULL, 1750, 1760, 130.734, 126.664, 0.9965, 0, 2.93, 15.09, 22.49, 2.28, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 114250656, "Yield_Rate": 0.0155, "Expense_Net": 0.002, "Benchmark_Exp": null, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 1750, "Vol_Recent": 1760}, "moving_averages": {"MA_50": 130.734, "MA_200": 126.664}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9965}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.93, "PE_Ratio": 22.49, "PS_Ratio": 2.28, "PCF_Ratio": 15.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1191, 'LQDB', 'ETF', 'US', 'Artisan Value Fund Inv Shs', 'Artisan Value Fund Investor Class', 'USD', NULL, NULL, 'Artisan', 'PCX', NULL, NULL, NULL, '2021-05-18', NULL, 'The investment seeks maximum long-term capital growth. The fund may invest up to 25% of its total assets at market value at the time of purchase in securities of non-U.S. issuers (including depositary receipts). Its investments in non-U.S. securities may include investments in developed markets, as well as emerging and less developed markets. The fund invests in common stocks and other securities of companies across a broad capitalization range.', 0.0015, NULL, 601, 250, 101.851, 102.423, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 601, "Vol_Recent": 250}, "moving_averages": {"MA_50": 101.851, "MA_200": 102.423}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1192, 'LRGE', 'ETF', 'U.S.A.', 'Artisan Select Equity Fund - In', 'Artisan Select Equity Fund Investor Shares', 'US$', 'Growth', 'Large', 'Artisan', 'NGM', 'Large Growth', 158945712, 0.0033, '2017-05-22', 0.21, 'The investment seeks maximum long-term capital growth. Under normal market conditions, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in equity securities or instruments that have similar economic characteristics. It will invest primarily in U.S. companies but may invest up to 20% of its total assets at market value at the time of purchase in non-U.S. companies, including those in emerging and less developed markets. The fund is non-diversified.', 0.006, 0.0039, 8170, 13330, 59.782, 55.662, NULL, NULL, 7.92, 22.75, 34.9, 3.9, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 158945712, "Yield_Rate": 0.0033, "Expense_Net": 0.006, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 0.21}', '{"volume_metrics": {"Vol_3M": 8170, "Vol_Recent": 13330}, "moving_averages": {"MA_50": 59.782, "MA_200": 55.662}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.92, "PE_Ratio": 34.9, "PS_Ratio": 3.9, "PCF_Ratio": 22.75}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1193, 'LRNZ', 'ETF', 'us', 'American Century One Choice in ', 'American Century Investments One Choice In Retirement Portfolio Investor Class', 'usd', 'Growth', 'Large', 'American Century Investments', 'PCX', 'Technology', 29695528, NULL, '2020-02-28', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The fund''s investments generally will be allocated among the major asset classes as follow: 45% of its assets in equity securities (stock funds); 45% of its assets in fixed-income securities (bond funds); and 10% of its assets in cash equivalents (money market funds). The neutral mix of One Choice In Retirement Portfolio is expected to remain fixed over time.', 0.0069, 0.0053, 5132, 6170, 49.893, 45.608, 0.9974, 0, 13.77, 38.71, NULL, 15.38, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 29695528, "Yield_Rate": null, "Expense_Net": 0.0069, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5132, "Vol_Recent": 6170}, "moving_averages": {"MA_50": 49.893, "MA_200": 45.608}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 13.77, "PE_Ratio": null, "PS_Ratio": 15.38, "PCF_Ratio": 38.71}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1195, 'LSAT', 'ETF', 'United States', 'Artisan Mid Cap Value Fd Invest', 'Artisan Mid Cap Value Fund Investor Class', 'USD', 'Value', 'Medium', 'Artisan', 'PCX', NULL, 95819952, NULL, '2020-10-26', NULL, 'The investment seeks maximum long-term capital growth. The fund normally invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in the common stocks of medium-sized companies. It defines a medium-sized company as one with a market capitalization greater than the market capitalization of the smallest company in the Russell Midcap© Index and less than three times the weighted average market capitalization of companies in that index.', 0.0099, NULL, 14343, 13220, 35.553, 34.577, 0.9906, 0, 2.05, 8.84, 14.14, 0.99, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 95819952, "Yield_Rate": null, "Expense_Net": 0.0099, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14343, "Vol_Recent": 13220}, "moving_averages": {"MA_50": 35.553, "MA_200": 34.577}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9906}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.05, "PE_Ratio": 14.14, "PS_Ratio": 0.99, "PCF_Ratio": 8.84}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1196, 'LSLT', 'ETF', 'US', 'Artisan Small Cap Fund Inv Shs', 'Artisan Small Cap Fund Investor Shares', 'US$', 'Value', 'Large', 'Artisan', 'BTS', NULL, 6247481, 0.023, '2019-03-12', NULL, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. small-cap growth companies. It invests primarily in US companies and, under normal circumstances, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in the common stocks of small companies.', 0.006, NULL, 317, 820, 31.708, 31.091, 0.999, 0, 2.93, 13.25, 22.89, 2.24, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 6247481, "Yield_Rate": 0.023, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 317, "Vol_Recent": 820}, "moving_averages": {"MA_50": 31.708, "MA_200": 31.091}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.93, "PE_Ratio": 22.89, "PS_Ratio": 2.24, "PCF_Ratio": 13.25}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1197, 'LSST', 'ETF', 'UNITED_STATES', 'Artisan Developing World Fund -', 'Artisan Developing World Fund Investor Shares', 'Usd', NULL, NULL, 'Artisan', 'PCX', 'Short-Term Bond', 35283752, 0.0141, '2017-12-27', 1.81, 'The investment seeks long-term capital appreciation. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of securities that offers exposure to developing world economies. In pursuit of this goal, the team generally invests substantially in equity securities of issuers domiciled in or economically tied to countries the team considers to have characteristics typical of the developing world. Under normal circumstances, the fund invests substantially in equity securities of issuers domiciled in or economically tied to one or more markets in the developing world.', 0.0038, 0.0026, 12879, 4930, 25.123, 25.26, NULL, NULL, NULL, NULL, NULL, NULL, 2.03, 1.89, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 35283752, "Yield_Rate": 0.0141, "Expense_Net": 0.0038, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 1.81}', '{"volume_metrics": {"Vol_3M": 12879, "Vol_Recent": 4930}, "moving_averages": {"MA_50": 25.123, "MA_200": 25.26}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.03, "Duration_Yrs": 1.89}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
