INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1206, 'MAGA', 'ETF', 'U.S.A.', 'American Century Real Estate Fu', 'American Century Real Estate Fund C Class', 'usd', 'Value', 'Medium', 'American Century Investments', 'BTS', 'Large Value', 12678522, 0.0212, '2017-09-06', 0.27, 'The investment seeks high total investment return through a combination of capital appreciation and current income. Under normal market conditions, the fund invests at least 80% of its net assets in equity securities issued by real estate investment trusts (REITs) and other companies engaged in the real estate industry. The portfolio managers look for real estate securities they believe will provide superior returns, focusing on companies with the potential for stock price appreciation, plus sustainable growth of cash flow to investors. The fund is non-diversified.', 0.0072, 0.0034, 2014, 1780, 38.141, 36.341, 0.9974, 0, 2.8, 13.15, 21.68, 1.94, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 12678522, "Yield_Rate": 0.0212, "Expense_Net": 0.0072, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.27}', '{"volume_metrics": {"Vol_3M": 2014, "Vol_Recent": 1780}, "moving_averages": {"MA_50": 38.141, "MA_200": 36.341}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.8, "PE_Ratio": 21.68, "PS_Ratio": 1.94, "PCF_Ratio": 13.15}}');
