INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1216, 'MBSD', 'ETF', 'usa', 'American Fds, Short-Term Bond F', 'American Funds Short-Term Bond Fund of America Class A', 'USD', NULL, NULL, 'American Funds', 'PCX', 'Intermediate Government', 109767800, 0.0278, '2014-09-03', 1.75, 'The investment seeks current income, consistent with the maturity and quality standards described in the prospectus, and preservation of capital. The fund will invest at least 80% of its assets in bonds (bonds include any debt instrument and cash equivalents). It maintains a portfolio of bonds, other debt securities and money market instruments having a dollar-weighted average effective maturity no greater than three years and consisting primarily of debt securities rated AA- or Aa3 or better. The fund primarily invests in debt securities denominated in U.S. dollars. It may invest up to 10% of its assets in debt securities in the A rating category.', 0.002, 0.0011, 20346, 47330, 23.42, 23.627, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.57, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 109767800, "Yield_Rate": 0.0278, "Expense_Net": 0.002, "Benchmark_Exp": 0.0011, "Turnover_Ratio": 1.75}', '{"volume_metrics": {"Vol_3M": 20346, "Vol_Recent": 47330}, "moving_averages": {"MA_50": 23.42, "MA_200": 23.627}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 4.57}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS