INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1225, 'MFDX', 'ETF', 'U.S.A.', 'Alger Small Cap Growth Fund Cla', 'Alger Small Cap Growth Fund Class Z', 'US_DOLLAR', 'Value', 'Large', 'Alger', 'PCX', 'Foreign Large Blend', 88977552, 0.0142, '2017-08-31', 0.35, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index.', 0.004, 0.0037, 4341, 6480, 29.706, 29.554, NULL, NULL, 1.37, 7.09, 17.77, 0.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 88977552, "Yield_Rate": 0.0142, "Expense_Net": 0.004, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 4341, "Vol_Recent": 6480}, "moving_averages": {"MA_50": 29.706, "MA_200": 29.554}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.37, "PE_Ratio": 17.77, "PS_Ratio": 0.89, "PCF_Ratio": 7.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1226, 'MFEM', 'ETF', 'USA', 'AAM/HIMCO Short Duration Fund C', 'AAM/HIMCO Short Duration Fund Class A', 'AmericanDollar', 'Value', 'Large', 'AAM', 'PCX', 'Diversified Emerging Mkts', 494443328, 0.0135, '2017-08-31', 0.59, 'The investment seeks current income and long-term total return. The fund has an investment policy whereby at least 80% of the fund''s net assets (plus any borrowings for investment purposes) will be invested, under normal circumstances, in fixed income instruments. It normally invests at least 65% of its total assets in "investment grade" securities. The fund may invest up to 35% of its total assets in non-investment grade securities (often called "junk bonds"), as well as bank loans and loan participation interests.', 0.0049, 0.0056, 51230, 53060, 29.204, 29.723, NULL, NULL, 1.21, 5.53, 12.96, 0.67, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 494443328, "Yield_Rate": 0.0135, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.59}', '{"volume_metrics": {"Vol_3M": 51230, "Vol_Recent": 53060}, "moving_averages": {"MA_50": 29.204, "MA_200": 29.723}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.21, "PE_Ratio": 12.96, "PS_Ratio": 0.67, "PCF_Ratio": 5.53}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1228, 'MFUS', 'ETF', 'US', 'Short Duration Fund - R6 Class', 'American Century Short Duration Fund R6 CLASS', 'AmericanDollar', 'Value', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 82677192, 0.0138, '2017-08-31', 0.36, 'The investment seeks to maximize total return; as a secondary objective, the fund seeks a high level of income. The fund invests at least 65% of its assets in investment-grade, non-money market debt securities. No more than 10% of the fund''s assets may be invested in non-dollar denominated debt securities. The weighted average duration of the fund''s portfolio must be three years or shorter.', 0.003, 0.0036, 2783, 2120, 40.321, 38.625, 0.991, 0, 2.8, 10.81, 19.98, 1.26, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 82677192, "Yield_Rate": 0.0138, "Expense_Net": 0.003, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 2783, "Vol_Recent": 2120}, "moving_averages": {"MA_50": 40.321, "MA_200": 38.625}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.8, "PE_Ratio": 19.98, "PS_Ratio": 1.26, "PCF_Ratio": 10.81}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1229, 'MGC', 'ETF', 'USA', 'American Century Select Fund R6', 'American Century Select Fund R6 Class', 'Dollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 4133430016, 0.0125, '2007-12-17', 0.04, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.0007, 0.0036, 83606, 104910, 161.082, 152.577, 1, 0, 4.87, 18.19, 26.91, 3.25, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 4133430016, "Yield_Rate": 0.0125, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.04}', '{"volume_metrics": {"Vol_3M": 83606, "Vol_Recent": 104910}, "moving_averages": {"MA_50": 161.082, "MA_200": 152.577}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.87, "PE_Ratio": 26.91, "PS_Ratio": 3.25, "PCF_Ratio": 18.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1308, 'NUMG', 'ETF', 'USA', 'American Century Small Cap Valu', 'American Century Small Cap Value Fund R5 Class', 'US$', 'Growth', 'Medium', 'American Century Investments', 'BTS', NULL, 305542848, 0.0003, '2016-12-13', 0.94, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s net assets in small cap companies. The portfolio managers consider small cap companies to include those with market capitalizations no larger than that of the largest company in the S&P Small Cap 600© Index or the Russell 2000© Index.', 0.004, NULL, 30937, 36430, 56.839, 54.033, 0.9987, 0, 8.85, 29.51, 41.7, 6.15, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 305542848, "Yield_Rate": 0.0003, "Expense_Net": 0.004, "Benchmark_Exp": null, "Turnover_Ratio": 0.94}', '{"volume_metrics": {"Vol_3M": 30937, "Vol_Recent": 36430}, "moving_averages": {"MA_50": 56.839, "MA_200": 54.033}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.85, "PE_Ratio": 41.7, "PS_Ratio": 6.15, "PCF_Ratio": 29.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1230, 'MGK', 'ETF', 'U.S.A.', 'American Century Short Duration', 'American Century Short Duration Strategic Income Fund I Class', 'US Dollar', 'Growth', 'Large', 'American Century Investments', 'PCX', 'Large Growth', 11397450752, 0.0054, '2007-12-17', 0.06, 'The investment seeks income; long-term capital appreciation is the secondary consideration. The fund invests in both investment-grade and high-yield, non-money market debt securities. These securities may include corporate bonds and notes, government securities and securities backed by mortgages or other assets. The fund may also invest in certain equity securities such as preferred stock, convertible securities or equity equivalents provided that such investments are consistent with the fund''s investment objectives.', 0.0007, 0.0039, 244266, 424390, 249.851, 231.737, 1, 0, 11, 25.44, 38.26, 5.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 11397450752, "Yield_Rate": 0.0054, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 244266, "Vol_Recent": 424390}, "moving_averages": {"MA_50": 249.851, "MA_200": 231.737}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 11, "PE_Ratio": 38.26, "PS_Ratio": 5.63, "PCF_Ratio": 25.44}}');
