INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1245, 'MLPO', 'ETF', 'America', 'AllianzGI Global Dynamic Alloca', 'Virtus AllianzGI Global Dynamic Allocation Fund Class A', 'DOLLAR', NULL, NULL, 'Virtus', 'PCX', 'Energy Limited Partnership', 24882130, 0.0341, '2014-12-02', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective through a combination of active allocation between asset classes and actively managed strategies within those asset classes. It allocates the fund''s investments among asset classes in response to changing market, economic, and political factors and events that the portfolio managers responsible for allocation believe may affect the value of the fund''s investments.', 0.0095, 0.0074, 1470, 140, 10.106, 10.081, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 24882130, "Yield_Rate": 0.0341, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0074, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1470, "Vol_Recent": 140}, "moving_averages": {"MA_50": 10.106, "MA_200": 10.081}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1246, 'MLPX', 'ETF', 'USA', 'American Century Short-Term Go', 'American Century Short-Term Government Fund I Class', 'US Dollar', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Energy Limited Partnership', 745640128, 0.0611, '2013-08-06', NULL, 'The investment seeks high current income while maintaining safety of principal. Under normal market conditions, the fund buys short-term debt securities and will invest at least 80% of its net assets in U.S. government securities. In addition, the fund may invest a portion of its assets in investment-grade debt securities, including debt securities of U.S. companies, and non-U.S. government mortgage-backed, asset-backed and other fixed-income securities.', 0.0045, 0.0074, 131304, 176980, 37.546, 34.834, 0.9991, 0, 2.02, 6.16, 17.05, 1.42, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 745640128, "Yield_Rate": 0.0611, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0074, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 131304, "Vol_Recent": 176980}, "moving_averages": {"MA_50": 37.546, "MA_200": 34.834}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.02, "PE_Ratio": 17.05, "PS_Ratio": 1.42, "PCF_Ratio": 6.16}}');
