INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1248, 'MMIT', 'ETF', 'U.S.', 'AllianzGI Short Duration High I', 'Virtus AllianzGI Short Duration High Income Fund Class A', 'DOLLAR', NULL, NULL, 'Virtus', 'PCX', 'Muni National Interm', 179963936, 0.0208, '2017-10-17', NULL, 'The investment seeks a high level of current income with lower volatility than the broader high yield market. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in debt securities ("junk bonds") issued by public and private companies, which are rated below investment grade, while maintaining an average duration of less than three years, and in derivatives and other synthetic instruments that have economic characteristics similar to such debt securities.', 0.003, 0.0029, 69922, 66200, 26.681, 26.796, NULL, NULL, NULL, NULL, NULL, NULL, 4.83, 4.06, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 179963936, "Yield_Rate": 0.0208, "Expense_Net": 0.003, "Benchmark_Exp": 0.0029, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 69922, "Vol_Recent": 66200}, "moving_averages": {"MA_50": 26.681, "MA_200": 26.796}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.83, "Duration_Yrs": 4.06}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
