INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1273, 'MVV', 'ETF', 'us', 'Invesco Summit Fund Class A', 'Invesco Summit Fund Class A', 'US Dollar', 'Blend', 'Medium', 'Invesco', 'PCX', 'Trading--Leveraged Equity', 175027920, 0.0013, '2006-06-19', 0.31, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of issuers of all market capitalizations that are considered by the fund''s portfolio managers to have potential for earnings or revenue growth. The principal type of equity securities in which it invests is common stock. The fund does not invest in companies whose primary business involves alcohol, tobacco or gambling. It may invest up to 25% of its net assets in foreign securities, including up to 10% of its net assets in emerging markets countries, i.e., those that are generally in the early stages of their industrial cycles. The fund is non-diversified.', 0.0095, 0.009, 50222, 86470, 68.212, 64.591, NULL, NULL, NULL, NULL, NULL, 1.77, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 175027920, "Yield_Rate": 0.0013, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 50222, "Vol_Recent": 86470}, "moving_averages": {"MA_50": 68.212, "MA_200": 64.591}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio