INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1295, 'NORW', 'ETF', 'United States', 'American Century Strategic Allo', 'American Century Strategic Allocation: Aggressive Fund C Class', 'US Dollar', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Miscellaneous Region', 46266192, 0.0236, '2010-11-09', 0.0838, 'The investment seeks the highest level of total return consistent with its asset mix. The fund''s asset allocation strategy diversifies investments among equity securities, bonds and money market instruments. It usually invests 79% of its assets in stocks, 20% of its assets in bonds, and 1% of its assets in cash equivalents. The fund also invests in a variety of debt securities payable in U.S. and foreign currencies. It may invest in any type of U.S. or foreign equity security that meets certain fundamental and technical standards. The fund may invest up to 10% of its assets in below investment-grade securities.', 0.005, 0.0053, 33333, 112360, 31.553, 30.922, 0.9975, 0, 2.07, 9.41, 17.91, 1.55, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 46266192, "Yield_Rate": 0.0236, "Expense_Net": 0.005, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.0838}', '{"volume_metrics": {"Vol_3M": 33333, "Vol_Recent": 112360}, "moving_averages": {"MA_50": 31.553, "MA_200": 30.922}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9975}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.07, "PE_Ratio": 17.91, "PS_Ratio": 1.55, "PCF_Ratio": 9.41}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1296, 'NTSE', 'ETF', 'us', 'American Century Strategic Allo', 'American Century Strategic Allocation: Moderate Fund C Class', 'USD', NULL, NULL, 'American Century Investments', 'PCX', NULL, NULL, NULL, '2021-05-18', NULL, 'The investment seeks the highest level of total return consistent with its asset mix. The fund''s asset allocation strategy diversifies investments among equity securities, bonds and money market instruments. It usually invests 64% of its assets in stocks, 32% of its assets in bonds, and 4% of its assets in cash equivalents. The fund also invests in a variety of debt securities payable in U.S. and foreign currencies. It may invest in any type of U.S. or foreign equity security that meets certain fundamental and technical standards. The fund may invest up to 10% of its assets in below investment-grade securities.', 0.0032, NULL, 1379, 1370, 38.472, 39.687, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0032, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1379, "Vol_Recent": 1370}, "moving_averages": {"MA_50": 38.472, "MA_200": 39.687}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1297, 'NTSI', 'ETF', 'UNITED_STATES', 'American Funds Short-Term Tax-E', 'American Funds Short-Term Tax-Exempt Bond Fund Class A', 'usd', NULL, NULL, 'American Funds', 'PCX', NULL, NULL, NULL, '2021-05-18', NULL, 'The investment seeks current income exempt from regular federal income tax, consistent with the maturity and quality standards, and to preserve capital. The fund will invest at least 80% of its assets in, or derive at least 80% of its income from, securities that are exempt from regular federal income tax and that do not subject the investors to federal alternative minimum tax. The fund invests primarily in debt securities rated AA- or better or Aa3 or better, or unrated but determined by the fund''s investment adviser to be of equivalent quality. Its aggregate portfolio will have a dollar-weighted average effective maturity no greater than three years.', 0.0026, NULL, 4101, 5890, 40.269, 40.658, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0026, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4101, "Vol_Recent": 5890}, "moving_averages": {"MA_50": 40.269, "MA_200": 40.658}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
