INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1299, 'NUAG', 'ETF', 'us', 'Astor Dynamic Allocation Fund C', 'Astor Dynamic Allocation Fund Class I', 'AmericanDollar', NULL, NULL, 'Astor', 'PCX', 'Intermediate-Term Bond', 62402600, 0.0296, '2016-09-14', 2.08, 'The investment seeks total return through a combination of capital appreciation and income. The fund invests predominantly in exchange-traded funds ("ETFs") that each invest primarily in domestic or foreign (1) equity securities, (2) fixed-income securities, (3) alternative/specialty securities or (4) cash equivalents. The adviser defines equity securities to include ETFs that invest primarily in equity securities, such as common and preferred stocks. It invests at least 80% of its assets (defined as net assets plus any borrowing for investment purposes) measured at the time of purchase in ETFs.', 0.002, 0.0023, 47020, 42540, 24.748, 24.872, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 62402600, "Yield_Rate": 0.0296, "Expense_Net": 0.002, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 2.08}', '{"volume_metrics": {"Vol_3M": 47020, "Vol_Recent": 42540}, "moving_averages": {"MA_50": 24.748, "MA_200": 24.872}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
