INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1301, 'NUDM', 'ETF', 'USA', 'Astor Macro Alternative Fund Cl', 'Astor Macro Alternative Fund Class A', 'USD', 'Blend', 'Large', 'Astor', 'BTS', NULL, 99215304, 0.0143, '2017-06-06', 0.66, 'The investment seeks to provide positive returns over a market cycle regardless of market conditions or general market direction. The fund utilizes multiple quantitative strategies implemented over a broad variety of asset classes and countries in seeking to achieve its investment objective and generate high risk-adjusted returns (capital appreciation) with lower volatility than the global equity markets. It invests in ETFs that each invest primarily in either equity securities (common and preferred stocks) or fixed-income securities (such as bonds, notes and debentures).', 0.004, NULL, 36279, 77550, 32.129, 31.719, NULL, NULL, 1.85, 10.86, 21.98, 1.44, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 99215304, "Yield_Rate": 0.0143, "Expense_Net": 0.004, "Benchmark_Exp": null, "Turnover_Ratio": 0.66}', '{"volume_metrics": {"Vol_3M": 36279, "Vol_Recent": 77550}, "moving_averages": {"MA_50": 32.129, "MA_200": 31.719}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 21.98, "PS_Ratio": 1.44, "PCF_Ratio": 10.86}}');
