INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1318, 'OCTZ', 'ETF', 'America', 'AB Cap Fund, Inc. - AB Select U', 'AB Select US Long/Short Portfolio Advisor Class', 'US_DOLLAR', 'Blend', 'Large', 'AllianceBernstein', 'BTS', NULL, 4548273, NULL, '2020-09-30', NULL, 'The investment seeks long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities of U.S. companies, short positions in such securities, and cash and U.S. cash equivalents. Its investments will be focused on securities of companies with large and medium market capitalizations, but it may also take long and short positions in securities of small-capitalization companies. The fund may invest in non-U.S. companies, but currently intends to limit its investments in such companies to no more than 10% of its net assets.', 0.0079, NULL, 3595, 1840, 31.535, 30.239, NULL, NULL, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 4548273, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3595, "Vol_Recent": 1840}, "moving_averages": {"MA_50": 31.535, "MA_200": 30.239}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1319, 'OEUR', 'ETF', 'America', 'Alger Weatherbie Specialized Gr', 'Alger Weatherbie Specialized Growth Fund Class Y', 'US$', 'Blend', 'Large', 'Alger', 'BTS', 'Europe Stock', 26596904, 0.0287, '2015-08-18', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of smallcap and midcap companies. Equity securities include common or preferred stocks that are listed on U.S. or foreign exchanges. Smallcap or midcap companies are companies that, at the time of purchase, have total market capitalization within the range of companies included in the Russell 2500 Growth Index or the Russell Midcap Growth Index, respectively, as reported by the indexes as of the most recent quarter-end.', 0.0048, 0.0044, 9198, 7250, 28.295, 27.837, 0.9978, 0, 4.19, 14.85, 21.54, 2.7, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 26596904, "Yield_Rate": 0.0287, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0044, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 9198, "Vol_Recent": 7250}, "moving_averages": {"MA_50": 28.295, "MA_200": 27.837}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9978}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.19, "PE_Ratio": 21.54, "PS_Ratio": 2.7, "PCF_Ratio": 14.85}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1320, 'OGIG', 'ETF', 'U.S.', 'ATAC Rotation Fund - Investor C', 'ATAC Rotation Fund Investor Class', 'US$', 'Growth', 'Large', 'ATAC Fund', 'BTS', NULL, 753612224, NULL, '2018-06-05', NULL, 'The investment seeks to achieve absolute positive returns over time. The adviser invests the fund''s assets primarily in shares of a diversified portfolio of exchange-traded funds ("ETFs") that track various indices or multiples thereof, sometimes referred to "underlying ETFs." These indices may track the performance of the equity and/or fixed income markets, in general, or the performance of specific sectors (e.g., a large grouping of companies operating within the market that share similar characteristics) or market segments (e.g., large, medium, or small capitalization domestic and/or foreign companies).', 0.0048, NULL, 62748, 66600, 55.209, 54.756, 0.999, 0, 9.28, 29.95, 38.39, 4.08, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 753612224, "Yield_Rate": null, "Expense_Net": 0.0048, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 62748, "Vol_Recent": 66600}, "moving_averages": {"MA_50": 55.209, "MA_200": 54.756}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 9.28, "PE_Ratio": 38.39, "PS_Ratio": 4.08, "PCF_Ratio": 29.95}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1321, 'OILK', 'ETF', 'U.S.', 'American Trust Allegiance Fund', 'American Trust Allegiance Fund', 'Usd', NULL, NULL, 'American Trust Company', 'BTS', NULL, 90070112, 0.0486, '2016-09-26', NULL, 'The investment seeks capital appreciation. The fund invests at least 85% of its net assets in domestic and foreign equity securities including both long and short positions. Normally, the companies in which the fund invests represent ten major economic or market sectors: consumer discretionary, consumer staples, energy, financial services, technology, industrials, utilities, communication services, materials and real estate. It avoids investments in companies that have significant involvement in the tobacco, pharmaceuticals, biotechnology, medical diagnostic services and products, gambling and liquor industries.', 0.0068, NULL, 37680, 98130, 58.362, 58.515, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 90070112, "Yield_Rate": 0.0486, "Expense_Net": 0.0068, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 37680, "Vol_Recent": 98130}, "moving_averages": {"MA_50": 58.362, "MA_200": 58.515}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1322, 'OLD', 'ETF', 'us', 'Anchor Risk Managed Global Stra', 'Anchor Risk Managed Global Strategies Fund Advisor Class Shares', 'usd', 'Blend', 'Medium', 'Anchor', 'NGM', 'Real Estate', 26093368, 0.0179, '2016-06-08', 0.18, 'The investment seeks to achieve above average total returns over a full market cycle with lower correlation and reduced risk when compared to traditional world indices. The fund seeks to achieve its investment objective by allocating assets among various strategies based on the adviser''s research and analysis regarding market trends. It will invest at least 40% of its assets (plus the amount of borrowings, if any) in long and short positions in exchange-traded funds, mutual funds and derivative instruments registered and offered in the U.S. with underlying holdings in non-U.S. companies.', 0.003, 0.0037, 6659, NULL, 31.172, 32.232, 0.9992, 0, 2.24, 14.53, 29.93, 3.28, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 26093368, "Yield_Rate": 0.0179, "Expense_Net": 0.003, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 6659, "Vol_Recent": null}, "moving_averages": {"MA_50": 31.172, "MA_200": 32.232}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.24, "PE_Ratio": 29.93, "PS_Ratio": 3.28, "PCF_Ratio": 14.53}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1341, 'OVLH', 'ETF', 'UNITED_STATES', 'American Century International ', 'American Century International Growth Fund R5 Class', 'Usd', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 9659576, NULL, '2021-01-14', NULL, 'The investment seeks capital growth. The fund invests primarily in securities of companies located in at least three developed countries world-wide (excluding the United States). Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.0078, 0.0036, 6730, 18580, 28.96, 27.699, NULL, NULL, 4.27, 17.32, 26, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 9659576, "Yield_Rate": null, "Expense_Net": 0.0078, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6730, "Vol_Recent": 18580}, "moving_averages": {"MA_50": 28.96, "MA_200": 27.699}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.27, "PE_Ratio": 26, "PS_Ratio": 2.89, "PCF_Ratio": 17.32}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1323, 'OMFL', 'ETF', 'U.S.A.', 'Anchor Risk Managed Municipal S', 'Anchor Risk Managed Municipal Strategies Fund Advisor Class Shares', 'US_DOLLAR', 'Value', 'Medium', 'Anchor', 'BTS', 'Large Blend', 1568427904, 0.0128, '2017-11-08', 3.21, 'The investment seeks to provide total return from income and capital appreciation with a secondary objective of limiting risk during unfavorable market conditions. Under normal market conditions, the fund invests, directly or indirectly through unaffiliated exchange traded funds ("ETFs") and mutual funds, at least 80% of its net assets (plus the amount of borrowings, if any) in long and short positions in municipal debt instruments. It may invest in inverse funds linked to U.S. Treasury securities when the adviser believes this strategy will provide an effective hedge to manage interest rate risk.', 0.0029, 0.0036, 122316, 131270, 48.84, 46.71, 1, 0, 2.59, 10.48, 17.57, 1.29, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 1568427904, "Yield_Rate": 0.0128, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 3.21}', '{"volume_metrics": {"Vol_3M": 122316, "Vol_Recent": 131270}, "moving_averages": {"MA_50": 48.84, "MA_200": 46.71}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.59, "PE_Ratio": 17.57, "PS_Ratio": 1.29, "PCF_Ratio": 10.48}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1324, 'OMFS', 'ETF', 'US', 'American Century Intermediate-T', 'American Century Intermediate-Term Tax-Free Bond Fund Y Class', 'US Dollar', 'Value', 'Small', 'American Century Investments', 'BTS', 'Small Blend', 104704488, 0.0074, '2017-11-08', 2.82, 'The investment seeks safety of principal and high current income that is exempt from federal income tax. The fund primarily invests in investment-grade debt securities and, under normal market conditions, will invest at least 80% of its net assets in debt securities with interest payments exempt from federal income tax. The fund''s weighted average maturity will be not less than three years nor more than ten years. However, there is no maturity limit on individual securities. The portfolio managers also may buy investment-grade debt securities with interest payments exempt from regular federal income tax, but not exempt from the federal alternative minimum tax.', 0.0039, 0.004, 31529, 30210, 42.18, 40.496, 0.9919, 0, 2.12, 6.37, 12.2, 0.75, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 104704488, "Yield_Rate": 0.0074, "Expense_Net": 0.0039, "Benchmark_Exp": 0.004, "Turnover_Ratio": 2.82}', '{"volume_metrics": {"Vol_3M": 31529, "Vol_Recent": 30210}, "moving_averages": {"MA_50": 42.18, "MA_200": 40.496}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9919}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.12, "PE_Ratio": 12.2, "PS_Ratio": 0.75, "PCF_Ratio": 6.37}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1325, 'ONEO', 'ETF', 'U.S.', 'Anchor Risk Managed Credit Stra', 'Anchor Risk Managed Credit Strategies Fund Advisor Class Shares', 'US_DOLLAR', 'Blend', 'Medium', 'Anchor', 'PCX', 'Mid-Cap Blend', 312234496, 0.0114, '2015-12-01', 0.42, 'The investment seeks to provide total return from income and capital appreciation with a secondary objective of limiting risk during unfavorable market conditions. The fund seeks to achieve its investment objective, utilizing a fund of funds structure, by allocating assets among various strategies based on the adviser''s research and analysis regarding market trends. It invests, directly or indirectly through unaffiliated fixed income exchange traded funds ("ETFs") and fixed income mutual funds (together with ETFs, "underlying funds"), at least 80% of its net assets (plus the amount of borrowings, if any) in long and short positions in fixed income securities.', 0.002, 0.0047, 1143, 760, 103.17, 98.945, 0.9989, 0, 3.02, 11.41, 18.79, 1.44, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 312234496, "Yield_Rate": 0.0114, "Expense_Net": 0.002, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.42}', '{"volume_metrics": {"Vol_3M": 1143, "Vol_Recent": 760}, "moving_averages": {"MA_50": 103.17, "MA_200": 98.945}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.02, "PE_Ratio": 18.79, "PS_Ratio": 1.44, "PCF_Ratio": 11.41}}');
