INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1329, 'ONLN', 'ETF', 'usa', 'Anchor Risk Managed Equity Stra', 'Anchor Risk Managed Equity Strategies Fund Advisor Class', 'Usd', 'Growth', 'Large', 'Anchor', 'PCX', 'Consumer Cyclical', 1101521152, 0.0116, '2018-07-13', NULL, 'The investment seeks to provide total return from income and capital appreciation with a secondary objective of limiting risk during unfavorable market conditions. Under normal market conditions, the fund invests, directly or indirectly through unaffiliated exchange traded funds ("ETFs") and mutual funds, at least 80% of its net assets (plus the amount of borrowings, if any) in long and short positions in equity securities. It may invest in inverse funds linked to equity securities or indices when the adviser believes this strategy will provide an effective hedge to manage risk for the fund''s equity investments.', 0.0058, 0.0045, 70153, 74840, 67.551, 74.674, 1, 0, 7.25, 17.3, 28.43, 1.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 1101521152, "Yield_Rate": 0.0116, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0045, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 70153, "Vol_Recent": 74840}, "moving_averages": {"MA_50": 67.551, "MA_200": 74.674}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.25, "PE_Ratio": 28.43, "PS_Ratio": 1.63, "PCF_Ratio": 17.3}}');
