INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1353, 'PBD', 'ETF', 'United States', 'PIMCO Strategic Bond Fund Class', 'PIMCO Strategic Bond Fund Class A', 'AmericanDollar', 'Growth', 'Medium', 'PIMCO', 'PCX', 'Miscellaneous Sector', 422858336, 0.0051, '2007-06-13', 0.56, 'The investment seeks maximum long-term return, consistent with preservation of capital and prudent investment management. The fund normally invests at least 80% of its assets in a diversified portfolio of Fixed Income Instruments of varying maturities, which may be represented by forwards or derivatives such as options, futures contracts, or swap agreements. It may invest in both investment-grade securities and high yield securities ("junk bonds") subject to a maximum of 20% of its total assets in securities rated below Baa by Moody''s, or equivalently rated by S&P or Fitch, or, if unrated, determined by PIMCO to be of comparable quality.', 0.0075, 0.0067, 122244, 81910, 29.697, 30.068, NULL, NULL, 3.89, 20.38, 35.74, 2.95, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 422858336, "Yield_Rate": 0.0051, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0067, "Turnover_Ratio": 0.56}', '{"volume_metrics": {"Vol_3M": 122244, "Vol_Recent": 81910}, "moving_averages": {"MA_50": 29.697, "MA_200": 30.068}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.89, "PE_Ratio": 35.74, "PS_Ratio": 2.95, "PCF_Ratio": 20.38}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1354, 'PBDM', 'ETF', 'usa', 'PIMCO Strategic Bond Fund Class', 'PIMCO Strategic Bond Fund Class C', 'Usd', 'Blend', 'Large', 'PIMCO', 'BTS', 'Foreign Large Blend', 8802117, 0.0169, '2017-09-22', 0.03, 'The investment seeks maximum long-term return, consistent with preservation of capital and prudent investment management. The fund normally invests at least 80% of its assets in a diversified portfolio of Fixed Income Instruments of varying maturities, which may be represented by forwards or derivatives such as options, futures contracts, or swap agreements. It may invest in both investment-grade securities and high yield securities ("junk bonds") subject to a maximum of 20% of its total assets in securities rated below Baa by Moody''s, or equivalently rated by S&P or Fitch, or, if unrated, determined by PIMCO to be of comparable quality.', 0.0007, 0.0037, 55888, 910, 29.275, 29.322, 0.9983, 0, 1.76, 10.37, 19.7, 1.46, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 8802117, "Yield_Rate": 0.0169, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 55888, "Vol_Recent": 910}, "moving_averages": {"MA_50": 29.275, "MA_200": 29.322}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.76, "PE_Ratio": 19.7, "PS_Ratio": 1.46, "PCF_Ratio": 10.37}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1375, 'PFFD', 'ETF', 'America', 'Alger 35 Fund Class P', 'Alger 35 Fund Class Z', 'US_DOLLAR', NULL, NULL, 'Alger', 'PCX', 'Preferred Stock', 1968497408, 0.0503, '2017-09-11', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests in a 35-stock portfolio of equity securities of companies of any market capitalization that the manager believes are undergoing Positive Dynamic Change. Equity securities include common or preferred stocks, or securities convertible into or exchangeable for equity securities, including warrants and rights. The fund may invest in companies whose securities are traded on domestic or foreign exchanges. It is non-diversified.', 0.0023, 0.0055, 765514, 1.25213e+06, 25.689, 25.736, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 1968497408, "Yield_Rate": 0.0503, "Expense_Net": 0.0023, "Benchmark_Exp": 0.0055, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 765514, "Vol_Recent": 1252130}, "moving_averages": {"MA_50": 25.689, "MA_200": 25.736}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1355, 'PBEE', 'ETF', 'U.S.A.', 'Anchor Risk Managed Municipal S', 'Anchor Risk Managed Municipal Strategies Fund Institutional Class', 'AmericanDollar', 'Blend', 'Large', 'Anchor', 'BTS', 'Diversified Emerging Mkts', 9104960, 0.0165, '2017-09-22', 0.18, 'The investment seeks to provide total return from income and capital appreciation with a secondary objective of limiting risk during unfavorable market conditions. Under normal market conditions, the fund invests, directly or indirectly through unaffiliated exchange traded funds ("ETFs") and mutual funds, at least 80% of its net assets (plus the amount of borrowings, if any) in long and short positions in municipal debt instruments. It may invest in inverse funds linked to U.S. Treasury securities when the adviser believes this strategy will provide an effective hedge to manage interest rate risk.', 0.0016, 0.0056, 1040, 900, 28.463, 29.289, 0.9964, 0, 2.1, 10.92, 16.41, 1.39, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 9104960, "Yield_Rate": 0.0165, "Expense_Net": 0.0016, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 1040, "Vol_Recent": 900}, "moving_averages": {"MA_50": 28.463, "MA_200": 29.289}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9964}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.1, "PE_Ratio": 16.41, "PS_Ratio": 1.39, "PCF_Ratio": 10.92}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1356, 'PBND', 'ETF', 'U.S.', 'Aberdeen Ultra Short Municipal ', 'Aberdeen Ultra Short Municipal Income Fund Class A', 'US_DOLLAR', NULL, NULL, 'Aberdeen', 'BTS', 'Intermediate-Term Bond', 20756916, 0.0223, '2017-09-27', 0.3, 'The investment seeks high after-tax current income consistent with preservation of capital. The fund invests its assets in a combination of tax-exempt obligations and taxable debt obligations. Under normal circumstances, it invests at least 80% of its net assets in tax-exempt obligations. The fund''s average portfolio maturity, at the time of investment, will be two years or less. The obligations in which the fund invests must, at the time of investment, be rated investment grade, as determined by the various rating agencies, or if unrated, of comparable quality as determined by the Adviser.', 0.0005, 0.0023, 5454, 6440, 25.767, 25.88, 0, 0.991, NULL, NULL, NULL, NULL, 8.44, 6.33, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 20756916, "Yield_Rate": 0.0223, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.3}', '{"volume_metrics": {"Vol_3M": 5454, "Vol_Recent": 6440}, "moving_averages": {"MA_50": 25.767, "MA_200": 25.88}}', '{"asset_allocation": {"Bond_Weight": 0.991, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.44, "Duration_Yrs": 6.33}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
