INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1364, 'PDEC', 'ETF', 'USA', 'Water Island Long/Short Fund In', 'The Water Island Long/Short Fund Class I', 'USD', 'Blend', 'Large', 'Arbitrage Fund', 'BTS', NULL, 145918544, NULL, '2019-11-29', 1.41, 'The investment seeks to achieve capital appreciation over a full market cycle with lower volatility than the broad equity market. To pursue its investment objective, the adviser employs a "long/short" event-driven strategy, which seeks to profit by investing, long and/or short, in the equity and debt securities of companies whose prices the Adviser believes are or will be impacted by a publicly announced or anticipated corporate event. It is non-diversified.', 0.0079, NULL, 65443, 331410, 30.937, 30.424, 0.9998, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 145918544, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": 1.41}', '{"volume_metrics": {"Vol_3M": 65443, "Vol_Recent": 331410}, "moving_averages": {"MA_50": 30.937, "MA_200": 30.424}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1365, 'PDEV', 'ETF', 'U.S.A.', 'Catalyst Systematic Alpha Class', 'Catalyst Systematic Alpha Fund Class A', 'AmericanDollar', 'Blend', 'Large', 'Catalyst Mutual Funds', 'NGM', 'Foreign Large Blend', 91694280, 0.0173, '2019-07-23', 0.561, 'The investment seeks long-term capital appreciation. The fund seeks to provide a total return that exceeds the BNP Paribas Catalyst Systematic Alpha Index (the "Benchmark"). It will seek excess return, after the impact of fees and expenses, above the Benchmark through investing in securities that provide exposure to the Benchmark ("Benchmark Component") and actively managing an equity portfolio ("Equity Component").', 0.0025, 0.0037, 37184, 541, 30.945, 31.302, 0.9922, 0, 1.81, 9.8, 17.31, 1.4, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 91694280, "Yield_Rate": 0.0173, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.561}', '{"volume_metrics": {"Vol_3M": 37184, "Vol_Recent": 541}, "moving_averages": {"MA_50": 30.945, "MA_200": 31.302}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9922}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.81, "PE_Ratio": 17.31, "PS_Ratio": 1.4, "PCF_Ratio": 9.8}}');
