INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1369, 'PEXL', 'ETF', 'U.S.A.', 'AB Bond Fund, Inc. - AB Tax-Awa', 'AB Tax-Aware Fixed Income Opportunities Portfolio Class A', 'Usd', 'Blend', 'Medium', 'AllianceBernstein', 'PCX', NULL, 1866429, 0.0046, '2018-07-23', 0.79, 'The investment seeks to maximize after-tax return and income. The fund invests, under normal circumstances, at least 80% of its net assets in fixed-income securities. It also invests, under normal circumstances, at least 65% of its total assets in municipal securities that pay interest that is exempt from federal income tax. The fund may also invest in forward commitments, zero-coupon municipal securities and variable, floating and inverse floating-rate municipal securities.', 0.006, NULL, 180, 200, 43.956, 41.626, 0.9994, 0, 4.34, 15.29, 28.56, 1.89, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1866429, "Yield_Rate": 0.0046, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": 0.79}', '{"volume_metrics": {"Vol_3M": 180, "Vol_Recent": 200}, "moving_averages": {"MA_50": 43.956, "MA_200": 41.626}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.34, "PE_Ratio": 28.56, "PS_Ratio": 1.89, "PCF_Ratio": 15.29}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1376, 'PFFL', 'ETF', 'us', 'Alger 35 Fund Class P-2', 'Alger 35 Fund Class P-2', 'US_DOLLAR', NULL, NULL, 'Alger', 'PCX', 'Trading--Miscellaneous', 19582500, 0.0865, '2018-09-26', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests in a 35-stock portfolio of equity securities of companies of any market capitalization that the manager believes are undergoing Positive Dynamic Change. Equity securities include common or preferred stocks, or securities convertible into or exchangeable for equity securities, including warrants and rights. The fund may invest in companies whose securities are traded on domestic or foreign exchanges. It is non-diversified.', 0.0085, 0.0087, 4393, 3550, 18.826, 19.005, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 19582500, "Yield_Rate": 0.0865, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4393, "Vol_Recent": 3550}, "moving_averages": {"MA_50": 18.826, "MA_200": 19.005}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1370, 'PEY', 'ETF', 'UNITED_STATES', 'American Century One Choice in ', 'American Century Investments One Choice In Retirement Portfolio C Class', 'USD', 'Value', 'Medium', 'American Century Investments', 'NGM', 'Mid-Cap Value', 979187264, 0.0367, '2004-12-09', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The fund''s investments generally will be allocated among the major asset classes as follow: 45% of its assets in equity securities (stock funds); 45% of its assets in fixed-income securities (bond funds); and 10% of its assets in cash equivalents (money market funds). The neutral mix of One Choice In Retirement Portfolio is expected to remain fixed over time.', 0.0052, 0.0043, 152912, 195310, 20.423, 20.445, 1, 0, 1.79, 8.63, 16.16, 1.16, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 979187264, "Yield_Rate": 0.0367, "Expense_Net": 0.0052, "Benchmark_Exp": 0.0043, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 152912, "Vol_Recent": 195310}, "moving_averages": {"MA_50": 20.423, "MA_200": 20.445}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.79, "PE_Ratio": 16.16, "PS_Ratio": 1.16, "PCF_Ratio": 8.63}}');
