INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1373, 'PFF', 'ETF', 'United States', 'Athena Behavioral Tactical Fund', 'Athena Behavioral Tactical Fund Class A', 'AmericanDollar', 'Value', 'Small', 'Athena Fund', 'NGM', 'Preferred Stock', 19595597824, 0.0451, '2007-03-26', 0.28, 'The investment seeks capital appreciation. To achieve its investment objective, the fund seeks investment exposure to domestic, foreign and emerging market equity markets. It is designed to invest in global markets which the portfolio managers believe have the most attractive expected returns on an unconstrained basis. The strategy relies on what the portfolio managers believe to be unique market behavioral indicators that measure macro-level investor preferences for specific investment strategies and return factors.', 0.0046, 0.0055, 4896566, 4.43517e+06, 38.86, 38.791, NULL, NULL, NULL, NULL, NULL, 7.18, 7.76, 3.57, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 19595597824, "Yield_Rate": 0.0451, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 4896566, "Vol_Recent": 4435170}, "moving_averages": {"MA_50": 38.86, "MA_200": 38.791}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.76, "Duration_Yrs": 3.57}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 7.18, "PCF_Ratio": null}}');
