INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1380, 'PFIG', 'ETF', 'U.S.', 'American Century International ', 'American Century International Growth Fund Y Class', 'US_DOLLAR', 'Blend', 'Medium', 'American Century Investments', 'PCX', NULL, 51919220, 0.0241, '2011-09-15', 0.36, 'The investment seeks capital growth. The fund invests primarily in securities of companies located in at least three developed countries world-wide (excluding the United States). Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.0022, NULL, 4523, 3310, 26.633, 26.841, NULL, NULL, NULL, NULL, NULL, NULL, 5.49, 4.85, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 51919220, "Yield_Rate": 0.0241, "Expense_Net": 0.0022, "Benchmark_Exp": null, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 4523, "Vol_Recent": 3310}, "moving_averages": {"MA_50": 26.633, "MA_200": 26.841}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.49, "Duration_Yrs": 4.85}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1733, 'SPIB', 'ETF', 'usa', 'Chartwell Mid Cap Value Fund', 'Chartwell Mid Cap Value Fund', 'usd', NULL, NULL, 'Chartwell Investment Partners', 'PCX', 'Corporate Bond', NULL, NULL, '2009-02-10', 0.35, 'The investment seeks long-term capital appreciation. The fund will invest at least 80% of its net assets (including amounts borrowed for investment purposes) in common stocks of mid-capitalization U.S. companies. It generally invests in companies that its advisor believes to be undervalued. The advisor''s investment approach seeks to identify companies with favorable valuations, margin improvement, product innovations and visionary management teams.', 0.0007, 0.0017, 3845261, 5.19247e+06, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5.13, 4.58, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 3845261, "Vol_Recent": 5192470}, "moving_averages": {"MA_50": null, "MA_200": null}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.13, "Duration_Yrs": 4.58}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
