INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1386, 'PGAL', 'ETF', 'United States', 'AQR Large Cap Defensive Style F', 'AQR Large Cap Defensive Style Fund Class I', 'Dollar', 'Value', 'Medium', 'AQR Funds', 'PCX', 'Miscellaneous Region', 14938874, 0.0332, '2013-11-12', 0.2519, 'The investment seeks total return. The fund pursues a "defensive" investment style, seeking to provide downside protection with upside potential through active stock selection, risk management and diversification. It pursues its objective by investing, under normal market conditions, at least 80% of its net assets (including any borrowings for investment purposes) in Equity Instruments of large-cap issuers. The fund can invest in companies of any size and may invest in small- and mid-cap companies from time to time in the discretion of the Adviser.', 0.0058, 0.0053, 7846, 1530, 11.266, 11.314, 1, 0, 1.39, 4.8, 17.26, 0.81, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 14938874, "Yield_Rate": 0.0332, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.2519}', '{"volume_metrics": {"Vol_3M": 7846, "Vol_Recent": 1530}, "moving_averages": {"MA_50": 11.266, "MA_200": 11.314}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.39, "PE_Ratio": 17.26, "PS_Ratio": 0.81, "PCF_Ratio": 4.8}}');
