INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1388, 'PGHY', 'ETF', 'UNITED_STATES', 'Auer Growth Fund', 'Auer Growth Fund', 'USD', 'Value', 'Small', 'Auer', 'PCX', NULL, 234623824, 0.0542, '2013-06-20', 0.54, 'The investment seeks long-term capital appreciation. The fund invests primarily in a diversified portfolio of common stocks traded on major U.S. exchanges, markets and bulletin boards that the fund''s adviser believes present the most favorable potential for capital appreciation. In selecting stocks for the fund''s portfolio, the Adviser reviews public companies'' financial statements to determine those companies that report substantial sales and earnings growth over the prior twelve months, plus a relatively low price to earnings ratio.', 0.0035, NULL, 51691, 43680, 21.611, 21.942, NULL, NULL, 0.88, 4.47, 7.22, 3.96, 1.32, 1.1, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 234623824, "Yield_Rate": 0.0542, "Expense_Net": 0.0035, "Benchmark_Exp": null, "Turnover_Ratio": 0.54}', '{"volume_metrics": {"Vol_3M": 51691, "Vol_Recent": 43680}, "moving_averages": {"MA_50": 21.611, "MA_200": 21.942}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.32, "Duration_Yrs": 1.1}}', '{"valuation_metrics": {"PB_Ratio": 0.88, "PE_Ratio": 7.22, "PS_Ratio": 3.96, "PCF_Ratio": 4.47}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1389, 'PGM', 'ETF', 'U.S.', 'Columbia Quality Income Fund Cl', 'Columbia Quality Income Fund Class A', 'AmericanDollar', NULL, NULL, 'Columbia Threadneedle', 'PCX', NULL, 5324425, NULL, '2018-01-17', NULL, 'The investment seeks to provide shareholders with current income as its primary objective and, as its secondary objective, preservation of capital. Under normal circumstances, at least 80% of the fund''s net assets (including the amount of any borrowings for investment purposes) are invested in mortgage-related securities. Its investments in mortgage-related securities include investments in stripped mortgage-backed securities such as interest-only (IO) and principal-only (PO) securities. The fund may invest in debt instruments of any maturity and does not seek to maintain a particular dollar-weighted average maturity.', 0.0045, NULL, 645, 1150, 47.726, 51.838, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 5324425, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 645, "Vol_Recent": 1150}, "moving_averages": {"MA_50": 47.726, "MA_200": 51.838}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
