INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1398, 'PIFI', 'ETF', 'United States', 'American Century Ultra Fund R6 ', 'American Century Ultra Fund R6 Class', 'USD', NULL, NULL, 'American Century Investments', 'PCX', 'Intermediate-Term Bond', 32238336, NULL, '2020-10-01', NULL, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.0045, 0.0023, 6964, 35860, 98.749, 99.091, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 32238336, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0023, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6964, "Vol_Recent": 35860}, "moving_averages": {"MA_50": 98.749, "MA_200": 99.091}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "P