INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1421, 'PPTY', 'ETF', 'America', 'AB Municipal Income Fund II - V', 'AB Municipal Income Fund II Virginia Portfolio Advisor Class', 'DOLLAR', 'Blend', 'Medium', 'AllianceBernstein', 'PCX', 'Real Estate', 141609472, 0.0281, '2018-03-26', 0.42, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and Commonwealth of Virginia personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal AMT for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Virginia or municipal securities with interest that is otherwise exempt from Virginia state income tax.', 0.0049, 0.0037, 5788, 5930, 37.069, 34.87, 0.9987, 0, 2.35, 19.71, 38.37, 9.44, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 141609472, "Yield_Rate": 0.0281, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.42}', '{"volume_metrics": {"Vol_3M": 5788, "Vol_Recent": 5930}, "moving_averages": {"MA_50": 37.069, "MA_200": 34.87}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.35, "PE_Ratio": 38.37, "PS_Ratio":