INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1583, 'RTM', 'ETF', 'U.S.', 'BMO Short Tax-Free Fund Class A', 'BMO Short Tax-Free Fund Class A', 'AmericanDollar', 'Value', 'Medium', 'BMO Funds', 'PCX', 'Natural Resources', 595220800, 0.0139, '2006-11-01', NULL, 'The investment seeks to provide current income exempt from federal income tax consistent with preservation of capital. The fund invests at least 80% of its assets in municipal securities, the income from which is exempt from federal income tax (including the federal alternative minimum tax (AMT)). It normally maintains an average dollar-weighted effective maturity of one to three years.', 0.004, 0.0048, 13534, 9100, 170.44, 165.802, 1, 0, 3.16, 12.93, 24.93, 2.18, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 595220800, "Yield_Rate": 0.0139, "Expense_Net": 0.004, "Benchmark_Exp": 0.0048, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 13534, "Vol_Recent": 9100}, "moving_averages": {"MA_50": 170.44, "MA_200": 165.802}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.16, "PE_Ratio": 24.93, "PS_Ratio": 2.18, "PCF_Ratio": 12.93}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1422, 'PQDI', 'ETF', 'UNITED_STATES', NULL, 'Avantis Core Fixed Income Fund G Class', 'US Dollar', 'Value', 'Small', 'Avantis Investors', 'PCX', NULL, 22513844, NULL, '2020-06-16', 0.063, 'The investment seeks to maximize total return. The fund invests primarily in investment grade quality debt obligations from a diverse group of U.S. and non-U.S. issuers. Under normal market conditions, it will invest at least 80% of its net assets, plus any borrowings for investment purposes, in fixed income securities. Fixed income securities in which the fund may invest include corporate bonds and notes issued by U.S. and foreign corporations, securities issued by governments and their agencies, instrumentalities, or sponsored corporations-including supranational organizations.', 0.006, NULL, 1445, 2050, 21.329, 21.433, NULL, NULL, NULL, NULL, NULL, NULL, 4.4, 4.3, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 22513844, "Yield_Rate": null, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": 0.063}', '{"volume_metrics": {"Vol_3M": 1445, "Vol_Recent": 2050}, "moving_averages": {"MA_50": 21.329, "MA_200": 21.433}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.4, "Duration_Yrs": 4.3}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1423, 'PREF', 'ETF', 'U.S.A.', 'Avantis International Equity Fu', 'Avantis International Equity Fund Institutional Class', 'Dollar', 'Blend', 'Small', 'Avantis Investors', 'PCX', NULL, 344879008, 0.0422, '2017-07-10', 0.419, 'The investment seeks long-term capital appreciation. The fund invests primarily in a diverse group of non-U.S. companies across countries, market sectors and industry groups. It may invest in companies of all market capitalizations. Under normal market conditions, the fund will invest at least 80% of its assets in equity securities. It may invest in securities that are denominated in foreign currencies and may also invest in foreign securities that are represented in the U.S. and other securities markets by American Depositary Receipts (ADRs), Global Depositary Receipts (GDRs), and other similar depositary arrangements.', 0.0055, NULL, 101361, 107380, 20.514, 20.586, NULL, NULL, NULL, NULL, NULL, NULL, 6.1, 4.8, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 344879008, "Yield_Rate": 0.0422, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": 0.419}', '{"volume_metrics": {"Vol_3M": 101361, "Vol_Recent": 107380}, "moving_averages": {"MA_50": 20.514, "MA_200": 20.586}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.1, "Duration_Yrs": 4.8}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1424, 'PRFZ', 'ETF', 'America', 'Avantis International Small Cap', 'Avantis International Small Cap Value Fund Institutional Class', 'usd', 'Value', 'Small', 'Avantis Investors', 'NGM', 'Small Blend', 2006491136, 0.0077, '2006-09-20', 0.25, 'The investment seeks long-term capital appreciation. The fund invests primarily in a diverse group of non-U.S. small cap value companies across market sectors, industry groups, and countries. It seeks securities of companies that the manager expects to have higher returns by placing an enhanced emphasis on securities of companies with smaller market capitalizations and securities of companies it defines as high profitability or value companies. Under normal market conditions, the fund will invest at least 80% of its assets in securities of small capitalization companies.', 0.0039, 0.004, 29757, 30100, 190.953, 184.166, 0.9992, 0, 2.11, 9.8, 16.61, 1.22, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 2006491136, "Yield_Rate": 0.0077, "Expense_Net": 0.0039, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 29757, "Vol_Recent": 30100}, "moving_averages": {"MA_50": 190.953, "MA_200": 184.166}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.11, "PE_Ratio": 16.61, "PS_Ratio": 1.22, "PCF_Ratio": 9.8}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1425, 'PRN', 'ETF', 'UNITED_STATES', 'Ave Maria Focused Fund', 'Ave Maria Focused Fund', 'US_DOLLAR', 'Blend', 'Medium', 'Ave Maria Mutual Funds', 'NGM', 'Industrials', 372103648, 0.0009, '2006-10-12', NULL, 'The investment seeks long-term capital appreciation. Under normal market conditions, the fund will invest primarily in equity securities that the Adviser believes have high earnings growth potential. Under normal circumstances, all of the fund''s equity investments and at least 80% of the fund''s net assets (plus the amount of borrowings for investment purposes) will be invested in companies believed to offer products or services or engage in practices that are not contrary to core values and teachings of the Roman Catholic Church. The fund is non-diversified.', 0.006, 0.0046, 11573, 13730, 110.707, 103.346, 0.9996, 0, 4.36, 14.89, 30.64, 1.93, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 372103648, "Yield_Rate": 0.0009, "Expense_Net": 0.006, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11573, "Vol_Recent": 13730}, "moving_averages": {"MA_50": 110.707, "MA_200": 103.346}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.36, "PE_Ratio": 30.64, "PS_Ratio": 1.93, "PCF_Ratio": 14.89}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1426, 'PRNT', 'ETF', 'UNITED_STATES', 'Ave Maria Rising Dividend Fund', 'Ave Maria Rising Dividend Fund', 'DOLLAR', 'Growth', 'Medium', 'Ave Maria Mutual Funds', 'BTS', 'Technology', 556428032, NULL, '2016-07-18', NULL, 'The investment seeks increasing dividend income over time, long-term growth of capital, and a reasonable level of current income. The fund will invest at least 80% of its net assets, including the amount of any borrowings for investment purposes, in the common stocks of dividend-paying companies that are expected to increase their dividends over time and to provide long-term growth of capital. Under normal circumstances, all of its equity investments (which include common stocks, preferred stocks and securities convertible into common stock) and at least 80% of the fund''s net assets will be invested in companies meeting its religious criteria.', 0.0066, 0.0053, 85285, 100890, 36.65, 37.997, 0.9996, 0, 5.12, 22.07, 39.11, 3.55, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 556428032, "Yield_Rate": null, "Expense_Net": 0.0066, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 85285, "Vol_Recent": 100890}, "moving_averages": {"MA_50": 36.65, "MA_200": 37.997}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.12, "PE_Ratio": 39.11, "PS_Ratio": 3.55, "PCF_Ratio": 22.07}}');
