INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1428, 'PSCC', 'ETF', 'UNITED_STATES', 'Ave Maria Bond Fund Class R', 'Ave Maria Bond Fund', 'Usd', 'Blend', 'Small', 'Ave Maria Mutual Funds', 'NGM', 'Consumer Defensive', 55459980, 0.0152, '2010-04-07', 0.4, 'The investment seeks preservation of principal with a reasonable level of current income. The fund invests primarily (80% or more of its net assets, including the amount of any borrowings for investment purposes) in investment-grade debt securities of domestic issuers, including the U.S. government and its agencies and instrumentalities, corporations and municipalities and money market instruments. It may invest up to 20% of its net assets in equity securities (which include preferred stocks, common stocks paying dividends and securities convertible into common stock) of domestic or foreign issuers of any market capitalization.', 0.0029, 0.0042, 1752, 1080, 104.025, 102.922, 1, 0, 2.85, 12.65, 24.14, 0.54, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 55459980, "Yield_Rate": 0.0152, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0042, "Turnover_Ratio": 0.4}', '{"volume_metrics": {"Vol_3M": 1752, "Vol_Recent": 1080}, "moving_averages": {"MA_50": 104.025, "MA_200": 102.922}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.85, "PE_Ratio": 24.14, "PS_Ratio": 0.54, "PCF_Ratio": 12.65}