INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1442, 'PSFD', 'ETF', 'US', 'Arin Large Cap Theta Fund Advis', 'Arin Large Cap Theta Fund Advisor Class', 'US_DOLLAR', 'Blend', 'Large', 'Nottingham', 'BTS', 'Large Blend', 2877681, NULL, '2020-12-22', NULL, 'The investment seeks maximum relative total return versus the S&P 500 Stock Index through a combination of capital appreciation and current income. The fund normally will invest at least 80% of net assets, plus borrowings for investment purposes, in a portfolio of securities whose value is based on companies with market capitalizations that qualify them as "large-cap" companies. The advisor considers a company to be a "large cap" company if its market capitalization is at least $10 billion.', 0.0075, 0.0036, 3345, 3840, 23.763, 22.949, 0.9932, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 2877681, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3345, "Vol_Recent": 3840}, "moving_averages": {"MA_50": 23.763, "MA_200": 22.949}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9932}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1444, 'PSFJ', 'ETF', 'U.S.A.', 'American Beacon Small Cap Value', 'American Beacon Small Cap Value Fund Investor Class', 'USD', NULL, NULL, 'American Beacon', 'BTS', 'Large Blend', 20, NULL, '2021-06-30', NULL, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of small market capitalization U.S. companies. These companies have market capitalizations of $5 billion or less at the time of investment. The fund''s investments may include common stocks, preferred stocks, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs"), master limited partnerships ("MLPs"), and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively, "stocks").', 0.0075, 0.0036, 2820, 2100, 21.171, 20.975, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 20, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2820, "Vol_Recent": 2100}, "moving_averages": {"MA_50": 21.171, "MA_200": 20.975}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1445, 'PSFM', 'ETF', 'US', 'ALPS/Red Rocks Global Opportuni', 'ALPS/Red Rocks Global Opportunity Portfolio Class III', 'US$', 'Blend', 'Large', 'ALPS', 'BTS', 'Large Blend', 6005498, NULL, '2021-03-31', NULL, 'The investment seeks to maximize total return, which consists of appreciation on its investments and a variable income stream. The portfolio will invest at least 80% of its net assets in securities of U.S. and non-U.S. companies, including those in emerging markets, listed on a national securities exchange, or foreign equivalent, that have a majority of their assets invested in or exposed to private companies or have as their stated intention to have a majority of their assets invested in or exposed to private companies ("Listed Private Equity Companies").', 0.0075, 0.0036, 1161, 1440, 22.598, 22.021, 0.9909, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 6005498, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1161, "Vol_Recent": 1440}, "moving_averages": {"MA_50": 22.598, "MA_200": 22.021}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9909}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1446, 'PSK', 'ETF', 'us', NULL, 'Avantis Short-Term Fixed Income Fund Institutional Class', 'US$', NULL, NULL, 'Avantis Investors', 'PCX', 'Preferred Stock', 1484914560, 0.0506, '2009-09-16', 0.36, 'The investment seeks to maximize total return. The fund invests primarily in investment grade quality debt obligations from a diverse group of U.S. and non-U.S. issuers. Under normal market conditions, it will invest at least 80% of its net assets, plus any borrowings for investment purposes, in fixed income securities. Fixed income securities in which the fund may invest include corporate bonds and notes issued by U.S. and foreign corporations, securities issued by governments and their agencies, instrumentalities, or sponsored corporations-including supranational organizations.', 0.0045, 0.0055, 152922, 134510, 42.975, 43.397, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 1484914560, "Yield_Rate": 0.0506, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 152922, "Vol_Recent": 134510}, "moving_averages": {"MA_50": 42.975, "MA_200": 43.397}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
