INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1448, 'PSMB', 'ETF', 'US', 'American Century Value Fund R6 ', 'American Century Value Fund R6 Class', 'usd', 'Blend', 'Medium', 'American Century Investments', 'BTS', 'Allocation--50% to 70% Equity', 16874140, 0.0185, '2017-02-23', 0.5, 'The investment seeks long-term capital growth; income is a secondary objective. In selecting stocks for the fund, the portfolio managers look for companies of all sizes whose stock price may not reflect the company''s value. The managers attempt to purchase the stocks of these undervalued companies and hold each stock until the price has increased to, or is higher than, a level the managers believe more accurately reflects the fair value of the company. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0032, 0.0072, 7782, 6910, 16.929, 16.533, NULL, NULL, 2.4, 10.47, 19.7, 1.38, 10.03, 7.19, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 16874140, "Yield_Rate": 0.0185, "Expense_Net": 0.0032, "Benchmark_Exp": 0.0072, "Turnover_Ratio": 0.5}', '{"volume_metrics": {"Vol_3M": 7782, "Vol_Recent": 6910}, "moving_averages": {"MA_50": 16.929, "MA_200": 16.533}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 10.03, "Duration_Yrs": 7.19}}', '{"valuation_metrics": {"PB_Ratio": 2.4, "PE_Ratio": 19.7, "PS_Ratio": 1.38, "PCF_Ratio": 10.47}}');
