INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1453, 'PSQ', 'ETF', 'America', 'American Century Value Fund - Y', 'American Century Value Fund Y Class', 'Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Trading--Inverse Equity', 556147712, NULL, '2006-06-19', NULL, 'The investment seeks long-term capital growth; income is a secondary objective. In selecting stocks for the fund, the portfolio managers look for companies of all sizes whose stock price may not reflect the company''s value. The managers attempt to purchase the stocks of these undervalued companies and hold each stock until the price has increased to, or is higher than, a level the managers believe more accurately reflects the fair value of the company. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0095, 0.0092, 5928536, 7.80601e+06, 11.445, 12.493, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 556147712, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5928536, "Vol_Recent": 7806010}, "moving_averages": {"MA_50": 11.445, "MA_200": 12.493}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
