INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1506, 'QSY', 'ETF', 'us', 'Alger Emerging Markets Fund Cla', 'Alger Emerging Markets Fund Class Z', 'AmericanDollar', 'Value', 'Medium', 'Alger', 'PCX', 'Large Value', 66886528, 0.0156, '2007-02-23', 0.59, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities, including common stocks, American Depositary Receipts and Global Depositary Receipts, of emerging country issuers. It generally invests in at least three emerging countries, and, at times, may invest a substantial portion of its assets in a single emerging country. The fund may invest in companies of any market capitalization, from larger, well-established companies to small, emerging growth companies.', 0.0038, 0.0034, 4612, 2510, 61.718, 59.726, 1, 0, 2.81, 10.51, 16.57, 1.54, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 66886528, "Yield_Rate": 0.0156, "Expense_Net": 0.0038, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.59}', '{"volume_metrics": {"Vol_3M": 4612, "Vol_Recent": 2510}, "moving_averages": {"MA_50": 61.718, "MA_200": 59.726}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.81, "PE_Ratio": 16.57, "PS_Ratio": 1.54, "PCF_Ratio": 10.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1507, 'QTAP', 'ETF', 'United States', 'AllianzGI Emerging Markets Valu', 'Virtus NFJ Emerging Markets Value Fund Class A', 'Dollar', 'Growth', 'Large', 'Virtus', 'BTS', NULL, 11200720, NULL, '2021-03-31', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in equity securities of companies that are domiciled in or tied economically to countries with emerging securities markets-that is, countries with securities markets which are, in the opinion of the portfolio managers, less sophisticated than more developed markets in terms of participation by investors, analyst coverage, liquidity and regulation.', 0.0079, NULL, 17261, 4910, 29.289, 28.18, 0.9923, 0, 8.57, 22.2, 35.06, 3.46, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 11200720, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 17261, "Vol_Recent": 4910}, "moving_averages": {"MA_50": 29.289, "MA_200": 28.18}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9923}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.57, "PE_Ratio": 35.06, "PS_Ratio": 3.46, "PCF_Ratio": 22.2}}');
