INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1521, 'RAYC', 'ETF', 'us', 'Aquila Tax-Free Trust of Arizon', 'Aquila Tax-Free Trust of Arizona Class Y', 'US Dollar', 'Blend', 'Large', 'Aquila', 'PCX', NULL, 18073972, NULL, '2020-12-30', NULL, 'The investment seeks to provide the investors as high a level of current income exempt from Arizona state and regular Federal income taxes as is consistent with preservation of capital. Under normal circumstances, at least 80% of the fund''s net assets will be invested in municipal obligations that pay interest exempt, in the opinion of bond counsel, from Arizona state and regular Federal income taxes, the income paid upon which will not be subject to the Federal alternative minimum tax on individuals. These obligations can be of any maturity, but the fund''s weighted average maturity has traditionally been between 5 and 15 years. The fund is non-diversified.', 0.008, NULL, 5690, 6050, 25.154, 26.054, 0.9946, 0, 2.52, 11.21, 17.66, 1.1, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 18073972, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5690, "Vol_Recent": 6050}, "moving_averages": {"MA_50": 25.154, "MA_200": 26.054}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9946}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.52, "PE_Ratio": 17.66, "PS_Ratio": 1.1, "PCF_Ratio": 11.21}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1522, 'RBIN', 'ETF', 'America', 'BlackRock 80/20 Target Allocati', 'BlackRock 80/20 Target Allocation Fund Class A', 'Dollar', 'Blend', 'Large', 'BlackRock', 'PCX', 'Foreign Large Blend', 130984360, 0.0172, '2017-09-15', 0.78, 'The investment seeks long term capital appreciation. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 80% of its assets and exposure to fixed-income securities in an amount equal to 20% of its assets. Under normal circumstances, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0042, 0.0037, 2085, 9890, 28.239, 28.175, 0.997, 0, 2.19, 10.13, 19.6, 1.53, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 130984360, "Yield_Rate": 0.0172, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.78}', '{"volume_metrics": {"Vol_3M": 2085, "Vol_Recent": 9890}, "moving_averages": {"MA_50": 28.239, "MA_200": 28.175}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.19, "PE_Ratio": 19.6, "PS_Ratio": 1.53, "PCF_Ratio": 10.13}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1523, 'RBND', 'ETF', 'United States', 'BlackRock Global Dividend Ptf I', 'BlackRock Global Dividend Portfolio Investor A Shares', 'DOLLAR', NULL, NULL, 'BlackRock', 'PCX', 'Corporate Bond', 29911608, NULL, '2020-11-05', NULL, 'The investment seeks to provide a level of current income that exceeds the average yield on global stocks generally. Under normal circumstances, the fund will invest at least 80% of its net assets in dividend-paying equity securities and at least 40% of its assets outside of the U.S. (unless market conditions are not deemed favorable by fund management, in which case the fund would invest at least 30% of its assets outside of the U.S.). It will primarily invest in common stock, preferred stock, securities convertible into common and preferred stock and non-convertible preferred stock.', 0.0012, 0.0017, 674, 530, 24.762, 24.737, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 29911608, "Yield_Rate": null, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0017, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 674, "Vol_Recent": 530}, "moving_averages": {"MA_50": 24.762, "MA_200": 24.737}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1524, 'RBUS', 'ETF', 'UNITED_STATES', 'BMO Growth Allocation - I', 'BMO Growth Allocation Fund Class I', 'US Dollar', 'Blend', 'Large', 'BMO Funds', 'PCX', 'Large Blend', 124866248, 0.0121, '2017-09-15', 0.73, 'The investment seeks to provide total investment return from income and appreciation. The fund normally targets an allocation of approximately 20% of its total assets in funds that invest principally in fixed income securities and 80% of its total assets in funds that invest principally in equity securities. Under normal market conditions it allocates its assets among the underlying funds based on asset allocation target ranges of 10-30% of its total assets in funds that invest principally in fixed income securities and 70-90% of its total assets in funds that invest principally in equity securities.', 0.003, 0.0036, 1787, 6570, 39.667, 38.307, 0.9991, 0, 4.47, 15.26, 24.81, 1.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 124866248, "Yield_Rate": 0.0121, "Expense_Net": 0.003, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.73}', '{"volume_metrics": {"Vol_3M": 1787, "Vol_Recent": 6570}, "moving_averages": {"MA_50": 39.667, "MA_200": 38.307}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.47, "PE_Ratio": 24.81, "PS_Ratio": 1.84, "PCF_Ratio": 15.26}}');
