INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1537, 'RESE', 'ETF', 'US', NULL, 'BlackRock Defensive Advantage U.S. Fund Investor A', 'US Dollar', 'Blend', 'Large', 'BlackRock', 'BTS', 'Diversified Emerging Mkts', 35403776, 0.0173, '2016-04-07', 1.3, 'The investment seeks to provide long-term capital appreciation. Under normal circumstances, the fund seeks to invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities of U.S. issuers and derivatives that have similar economic characteristics to such securities. It primarily intends to invest in equity securities or other financial instruments that are components of, or have characteristics similar to, the securities included in the Russell 1000© Index.', 0.0032, 0.0056, 3437, 1200, 35.649, 37.541, 1, 0, 2.15, 10.61, 16.09, 1.1, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 35403776, "Yield_Rate": 0.0173, "Expense_Net": 0.0032, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 1.3}', '{"volume_metrics": {"Vol_3M": 3437, "Vol_Recent": 1200}, "moving_averages": {"MA_50": 35.649, "MA_200": 37.541}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.15, "PE_Ratio": 16.09, "PS_Ratio": 1.1, "PCF_Ratio": 10.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1528, 'RDOG', 'ETF', 'America', 'BlackRock Fds, All-Cap Energy &', 'BlackRock Energy Opportunities Fund Investor A Class', 'US_DOLLAR', 'Value', 'Small', 'BlackRock', 'PCX', 'Real Estate', 31184718, 0.0411, '2008-05-07', NULL, 'The investment seeks to provide long-term growth of capital. The fund invests at least 80% of its total assets in equity securities of global energy and natural resources companies and companies in associated businesses, as well as utilities (such as gas, water, cable, electrical and telecommunications utilities). It will concentrate its investments (i.e., invest more than 25% of its assets) in energy or natural resources companies. The fund may invest without limit in companies located anywhere in the world and will generally invest in at least three countries and in companies tied economically to a number of countries. It is non-diversified.', 0.0035, 0.0037, 898, 500, 50.484, 48.204, 0.9937, 0, 1.62, 13.7, 27.65, 3.9, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 31184718, "Yield_Rate": 0.0411, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 898, "Vol_Recent": 500}, "moving_averages": {"MA_50": 50.484, "MA_200": 48.204}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9937}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.62, "PE_Ratio": 27.65, "PS_Ratio": 3.9, "PCF_Ratio": 13.7}}');
