INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1531, 'RECS', 'ETF', 'UNITED_STATES', 'BlackRock 20/80 Target Allocati', 'BlackRock 20/80 Target Allocation Fund Investor A Shares', 'AmericanDollar', 'Blend', 'Large', 'BlackRock', 'PCX', NULL, 22027856, 0.0088, '2019-09-25', 0.41, 'The investment seeks a balance between long term capital appreciation and high current income, with an emphasis on income. The fund, which is a fund of funds, normally obtains exposure to equity securities (and certain other instruments) in an amount equal to 20% of its assets and exposure to fixed-income securities in an amount equal to 80% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0015, NULL, 1853, 2130, 30.885, 29.135, 0.9974, 0, 4.07, 15.14, 23.65, 2.51, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 22027856, "Yield_Rate": 0.0088, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": 0.41}', '{"volume_metrics": {"Vol_3M": 1853, "Vol_Recent": 2130}, "moving_averages": {"MA_50": 30.885, "MA_200": 29.135}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.07, "PE_Ratio": 23.65, "PS_Ratio": 2.51, "PCF_Ratio": 15.14}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1542, 'RFCI', 'ETF', 'USA', 'Sterling Capital Equity Income', 'Sterling Capital Equity Income Fund Class R', 'usd', NULL, NULL, 'Sterling Capital Funds', 'PCX', NULL, 103826536, 0.0178, '2016-06-10', NULL, 'The investment seeks capital growth and current income. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in equity securities. It invests, under normal market conditions, primarily in dividend-paying equity securities, in particular common stocks of companies with a history of increasing dividend rates. The fund may also invest in U.S. traded common stocks of foreign companies, including American Depositary Receipts.', 0.0054, NULL, 6287, 2130, 25.343, 25.458, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 103826536, "Yield_Rate": 0.0178, "Expense_Net": 0.0054, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6287, "Vol_Recent": 2130}, "moving_averages": {"MA_50": 25.343, "MA_200": 25.458}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1532, 'REGL', 'ETF', 'usa', 'BlackRock Fds, All-Cap Energy &', 'BlackRock Energy Opportunities Fund Service Class', 'Dollar', 'Value', 'Small', 'BlackRock', 'BTS', 'Mid-Cap Blend', 1026099456, 0.0229, '2015-02-03', NULL, 'The investment seeks to provide long-term growth of capital. The fund invests at least 80% of its total assets in equity securities of global energy and natural resources companies and companies in associated businesses, as well as utilities (such as gas, water, cable, electrical and telecommunications utilities). It will concentrate its investments (i.e., invest more than 25% of its assets) in energy or natural resources companies. The fund may invest without limit in companies located anywhere in the world and will generally invest in at least three countries and in companies tied economically to a number of countries. It is non-diversified.', 0.0041, 0.0047, 34891, 27090, 71.01, 71.159, 0.997, 0, 2.35, 9.59, 18.49, 1.76, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 1026099456, "Yield_Rate": 0.0229, "Expense_Net": 0.0041, "Benchmark_Exp": 0.0047, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 34891, "Vol_Recent": 27090}, "moving_averages": {"MA_50": 71.01, "MA_200": 71.159}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.35, "PE_Ratio": 18.49, "PS_Ratio": 1.76, "PCF_Ratio": 9.59}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1533, 'REIT', 'ETF', 'UNITED_STATES', 'BMO Small Cap Value Fund Class ', 'BMO Small-Cap Value Fund Class A', 'US$', 'Blend', 'Medium', 'BMO Funds', 'NGM', 'Real Estate', 21327108, NULL, '2021-02-24', NULL, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in value-oriented common stocks of small-sized U.S. companies similar in size, at the time of purchase, to those within the Russell 2000© Value Index. The Adviser selects stocks using a unique, value-oriented approach focusing on high quality companies with long-term capital appreciation potential that are available at reasonable prices, which combines the use of proprietary analytical tools and the qualitative judgments of the investment team.', 0.0068, 0.0037, 3887, 3680, 29.689, 28.264, NULL, NULL, 2.29, 17.63, 41.84, 8.67, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 21327108, "Yield_Rate": null, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3887, "Vol_Recent": 3680}, "moving_averages": {"MA_50": 29.689, "MA_200": 28.264}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.29, "PE_Ratio": 41.84, "PS_Ratio": 8.67, "PCF_Ratio": 17.63}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1534, 'REK', 'ETF', 'U.S.', 'Brown Advisory Equity Income Fd', 'Brown Advisory Equity Income Fund Advisor Shares', 'US$', NULL, NULL, 'Brown Advisory Funds', 'PCX', 'Trading--Inverse Equity', 7460586, NULL, '2010-03-16', NULL, 'The investment seeks to provide current dividend yield and dividend growth. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in a diversified portfolio of dividend paying equity securities. Equity securities include domestic and foreign common and preferred stock, convertible debt securities, American Depositary Receipts ("ADRs"), Master Limited Partnerships ("MLPs"), real estate investment trusts ("REITs") and exchange traded funds ("ETFs"), and the Adviser may also invest in private placements in these types of securities.', 0.0095, 0.0092, 14604, 18590, 8.708, 9.355, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7460586, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14604, "Vol_Recent": 18590}, "moving_averages": {"MA_50": 8.708, "MA_200": 9.355}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1535, 'REMX', 'ETF', 'us', NULL, 'BlackRock Defensive Advantage Emerging Markets Fund Investor A', 'US Dollar', 'Growth', 'Medium', 'BlackRock', 'PCX', 'Equity Precious Metals', 758353856, 0.0063, '2010-10-27', 0.7, 'The investment seeks to provide long-term capital appreciation. Under normal circumstances, the fund seeks to invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities issued by, or tied economically to, companies in emerging markets and derivatives that have similar economic characteristics to such securities. It primarily intends to invest in equity securities, which include common stock, preferred stock and convertible securities, or other financial instruments that are components of, or have characteristics similar to, the securities included in the MSCI EM Index.', 0.0059, 0.0057, 205306, 206300, 113.838, 96.382, NULL, NULL, 3.8, 22.4, 24.11, 2.33, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 758353856, "Yield_Rate": 0.0063, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0057, "Turnover_Ratio": 0.7}', '{"volume_metrics": {"Vol_3M": 205306, "Vol_Recent": 206300}, "moving_averages": {"MA_50": 113.838, "MA_200": 96.382}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.8, "PE_Ratio": 24.11, "PS_Ratio": 2.33, "PCF_Ratio": 22.4}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1536, 'RESD', 'ETF', 'United States', 'BMO Dividend Income Fund Class ', 'BMO Dividend Income Fund Class A', 'USD', 'Blend', 'Large', 'BMO Funds', 'BTS', NULL, 7367322, 0.0201, '2016-11-03', 1.12, 'The investment seeks to provide capital appreciation and current income. The fund invests at least 80% of its net assets primarily in dividend paying common stocks of large-sized U.S. companies similar in size, at the time of purchase, to those within the Russell 1000© Value Index. To provide both capital appreciation and current income, the Adviser selects stocks using a unique, value-oriented approach, focusing on companies with dividend yields in excess of 1%, which combines the use of proprietary analytical tools and the qualitative judgments of the investment team.', 0.003, NULL, 1193, 560, 30.997, 30.893, 1, 0, 1.96, 10.36, 20.85, 1.5, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 7367322, "Yield_Rate": 0.0201, "Expense_Net": 0.003, "Benchmark_Exp": null, "Turnover_Ratio": 1.12}', '{"volume_metrics": {"Vol_3M": 1193, "Vol_Recent": 560}, "moving_averages": {"MA_50": 30.997, "MA_200": 30.893}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.96, "PE_Ratio": 20.85, "PS_Ratio": 1.5, "PCF_Ratio": 10.36}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1538, 'RESP', 'ETF', 'UNITED_STATES', 'BlackRock Emerging Markets Flex', 'BlackRock Emerging Markets Flexible Dynamic Bond Portfolio Investor A Shares', 'DOLLAR', 'Blend', 'Large', 'BlackRock', 'PCX', 'Large Blend', 95839136, 0.0105, '2007-02-23', 0.78, 'The investment seeks maximum long term total return. The fund invests primarily in a global portfolio of fixed income securities and derivatives of any maturity of issuers located in emerging markets that may be denominated in any currency (on a hedged or un-hedged basis). It will invest at least 80% of its assets in fixed income securities issued by governments, their political subdivisions (states, provinces and municipalities), agencies and companies tied economically to an emerging market. The fund is non-diversified.', 0.0028, 0.0036, 2753, 2060, 48.882, 46.943, 1, 0, 3.97, 14.32, 23.23, 2.02, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 95839136, "Yield_Rate": 0.0105, "Expense_Net": 0.0028, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.78}', '{"volume_metrics": {"Vol_3M": 2753, "Vol_Recent": 2060}, "moving_averages": {"MA_50": 48.882, "MA_200": 46.943}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.97, "PE_Ratio": 23.23, "PS_Ratio": 2.02, "PCF_Ratio": 14.32}}');
