INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1548, 'RFUN', 'ETF', 'U.S.A.', 'Brown Advisory Global Leaders F', 'Brown Advisory Global Leaders Fund Institutional Shares', 'Usd', NULL, NULL, 'Brown Advisory Funds', 'PCX', NULL, 14091091, 0.0407, '2016-06-10', NULL, 'The investment seeks to achieve long-term capital appreciation by investing primarily in global equities. The fund aims to achieve its investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities. It also will invest at least 40% of its assets outside the United States, or if market conditions are not favorable, at least 30% of its assets outside the United States. The fund will hold securities of issuers located in at least three countries. Its non-U.S. investments may include equity securities issued by companies that are established or operating in emerging market countries.', 0.0055, NULL, 2162, NULL, 25.736, 25.75, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 14091091, "Yield_Rate": 0.0407, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2162, "Vol_Recent": null}, "moving_averages": {"MA_50": 25.736, "MA_200": 25.75}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
