INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1609, 'SCDL', 'ETF', 'U.S.', NULL, 'BBH Partner Fund - Small Cap Equity', 'US$', NULL, NULL, 'BBH', 'PCX', 'Trading--Leveraged Equity', 33313900, NULL, '2021-02-04', NULL, 'The investment seeks to provide investors with long-term growth of capital. The fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in small cap equity securities. Such securities will be publicly traded and issued by domestic issuers directly. The fund primarily seeks to purchase common stock. Brown Brothers Harriman & Co. ("BBH&Co."), through a separately identifiable department ("Investment Adviser"), employs a "manager of managers" investment approach, whereby it allocates the fund''s assets to the fund''s sub-adviser, Bares Capital Management, Inc. ("Sub-adviser"). The fund is non-diversified.', 0.0095, 0.009, 140, 190, 35.04, 33.206, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 33313900, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 140, "Vol_Recent": 190}, "moving_averages": {"MA_50": 35.04, "MA_200": 33.206}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
