INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1616, 'SCHG', 'ETF', 'America', NULL, 'BBH Select Series - Mid Cap Fund Class I', 'US$', 'Growth', 'Large', 'BBH', 'PCX', 'Large Growth', 15159136256, 0.0043, '2009-12-11', 0.07, 'The investment seeks to provide investors with long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in publicly traded mid cap equity securities. Such securities may be issued by domestic or foreign issuers. It primarily seeks to buy common stock and may also invest in preferred stock. The fund may also invest in large cap and small cap publicly traded equity securities. It is non-diversified.', 0.0004, 0.0039, 358477, 385990, 158.027, 146.084, 0.9993, 0, 9.81, 24.61, 36.82, 4.82, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 15159136256, "Yield_Rate": 0.0043, "Expense_Net": 0.0004, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 0.07}', '{"volume_metrics": {"Vol_3M": 358477, "Vol_Recent": 385990}, "moving_averages": {"MA_50": 158.027, "MA_200": 146.084}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 9.81, "PE_Ratio": 36.82, "PS_Ratio": 4.82, "PCF_Ratio": 24.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1617, 'SCHH', 'ETF', 'U.S.', NULL, 'BBH Select Series - Mid Cap Fund Retail Class', 'AmericanDollar', 'Blend', 'Medium', 'BBH', 'PCX', 'Real Estate', 5925398528, 0.0211, '2011-01-13', 0.59, 'The investment seeks to provide investors with long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in publicly traded mid cap equity securities. Such securities will be issued by domestic and foreign issuers both directly and in the form of depository receipts, including ADRs and GDRs, representing an interest in these securities. It primarily seeks to buy common stock and may also invest in preferred stock. The fund may also invest in large cap and small cap publicly traded equity securities. It is non-diversified.', 0.0007, 0.0037, 806963, 773750, 48.397, 45.815, 1, 0, 2.98, 21.65, 41.72, 9.5, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 5925398528, "Yield_Rate": 0.0211, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.59}', '{"volume_metrics": {"Vol_3M": 806963, "Vol_Recent": 773750}, "moving_averages": {"MA_50": 48.397, "MA_200": 45.815}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.98, "PE_Ratio": 41.72, "PS_Ratio": 9.5, "PCF_Ratio": 21.65}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1618, 'SCHI', 'ETF', 'USA', 'Bridge Builder Municipal Bond F', 'Bridge Builder Municipal Bond Fund', 'US$', NULL, NULL, 'Bridge Builder', 'PCX', 'Corporate Bond', 354823968, 0.0213, '2019-10-09', 0.36, 'The investment seeks to provide current income exempt from federal tax, with a secondary goal of preservation of investment principal. The fund invests, under normal market conditions, at least 80% of its net assets (plus the amount of borrowings for investment purposes) in municipal securities of any maturity or duration whose interest is exempt from federal income tax. It invests in municipal securities rated below investment grade, also known as "junk bonds," or in unrated municipal securities that a Sub-adviser believes are of comparable quality.', 0.0005, 0.0017, 35012, 48970, 51.89, 52.156, NULL, NULL, NULL, NULL, NULL, NULL, 7.29, 6.44, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 354823968, "Yield_Rate": 0.0213, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 35012, "Vol_Recent": 48970}, "moving_averages": {"MA_50": 51.89, "MA_200": 52.156}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.29, "Duration_Yrs": 6.44}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1619, 'SCHJ', 'ETF', 'United States', 'Sterling Capital North Carolina', 'Sterling Capital North Carolina Intermediate Tax-Free Fund C Shares', 'USD', NULL, NULL, 'Sterling Capital Funds', 'PCX', 'Short-Term Bond', 629433024, 0.0134, '2019-10-09', 0.8, 'The investment seeks current income exempt from federal and North Carolina income taxes consistent with preservation of capital. The fund normally invests at least 80% of its net assets in investments the income from which is exempt from federal income tax, alternative minimum tax, and North Carolina personal income tax. It invests primarily in municipal securities of the State of North Carolina and its political subdivisions, that provide income exempt from both federal personal income tax and North Carolina personal income tax. The fund''s dollar-weighted average maturity is expected to be more than 3 years but less than 10 years. It is non-diversified.', 0.0005, 0.0026, 86096, 68210, 50.79, 51.051, NULL, NULL, NULL, NULL, NULL, NULL, 2.93, 2.77, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 629433024, "Yield_Rate": 0.0134, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.8}', '{"volume_metrics": {"Vol_3M": 86096, "Vol_Recent": 68210}, "moving_averages": {"MA_50": 50.79, "MA_200": 51.051}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.93, "Duration_Yrs": 2.77}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
