INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1624, 'SCHQ', 'ETF', 'America', 'BlackRock Short Obligations Fun', 'BlackRock Short Obligations Fund Class K', 'US Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Long Government', 80260496, 0.016, '2019-10-09', 0.45, 'The investment seeks current income consistent with preservation of capital. The fund will invest in U.S. dollar-denominated investment grade and short-term fixed and floating rate debt securities maturing in three years or less (with certain exceptions) and will maintain a dollar-weighted average maturity of 180 days or less and a dollar-weighted average life of 365 days or less. It invests a significant portion of its assets in securities issued by financial services companies, including banks, broker-dealers and insurance companies, and repurchase agreements secured by such obligations.', 0.0005, 0.0014, 93514, 169830, 50.689, 49.954, 0, 1, NULL, NULL, NULL, NULL, 24.52, 18.35, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 80260496, "Yield_Rate": 0.016, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0014, "Turnover_Ratio": 0.45}', '{"volume_metrics": {"Vol_3M": 93514, "Vol_Recent": 169830}, "moving_averages": {"MA_50": 50.689, "MA_200": 49.954}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 24.52, "Duration_Yrs": 18.35}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1625, 'SCHR', 'ETF', 'US', NULL, 'BBH Partner Fund - Select Short Term Assets', 'US Dollar', NULL, NULL, 'BBH', 'PCX', 'Intermediate Government', 3434468864, 0.0126, '2010-08-05', 0.51, 'The investment seeks to provide income balanced with low price volatility. The fund seeks to achieve its investment objective by investing in a well-diversified portfolio of durable performing fixed income instruments. It invests primarily in securities rated A/A and equivalent or better by a nationally recognized statistical rating organization. These investments will be primarily focused in ABS, notes and bonds issued by domestic and foreign corporations, including those located in emerging markets, and financial institutions and the U.S. government, government agencies and government guaranteed issuers.', 0.0005, 0.0011, 690263, 778680, 56.344, 56.807, 0, 0.9995, NULL, NULL, NULL, NULL, 5.61, 5.34, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 3434468864, "Yield_Rate": 0.0126, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0011, "Turnover_Ratio": 0.51}', '{"volume_metrics": {"Vol_3M": 690263, "Vol_Recent": 778680}, "moving_averages": {"MA_50": 56.344, "MA_200": 56.807}}', '{"asset_allocation": {"Bond_Weight": 0.9995, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 5.61, "Duration_Yrs": 5.34}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1626, 'SCHV', 'ETF', 'UNITED_STATES', 'Bridge Builder Core Bond Fund', 'Bridge Builder Core Bond Fund', 'DOLLAR', 'Value', 'Large', 'Bridge Builder', 'PCX', 'Large Value', 9565440000, 0.0244, '2009-12-11', 0.19, 'The investment seeks to provide total return (capital appreciation plus income). The fund invests, under normal market conditions, at least 80% of its net assets (plus the amount of borrowings for investment purposes) in fixed income securities and other instruments, such as derivatives and certain investment companies, with economic characteristics similar to fixed income securities. It may invest in futures, primarily interest rate and U.S. Treasury futures, and swaps, primarily interest rate swaps.', 0.0004, 0.0034, 357873, 395320, 70.517, 68.54, 0.9989, 0, 2.98, 13.9, 20.7, 2.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 9565440000, "Yield_Rate": 0.0244, "Expense_Net": 0.0004, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.19}', '{"volume_metrics": {"Vol_3M": 357873, "Vol_Recent": 395320}, "moving_averages": {"MA_50": 70.517, "MA_200": 68.54}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.98, "PE_Ratio": 20.7, "PS_Ratio": 2.21, "PCF_Ratio": 13.9}}');
