INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1642, 'SDS', 'ETF', 'UNITED_STATES', 'Blue Current Global Dividend Fu', 'Blue Current Global Dividend Fund Institutional Class', 'AmericanDollar', NULL, NULL, 'Blue Current Funds', 'PCX', 'Trading--Inverse Equity', 609340928, NULL, '2006-07-11', NULL, 'The investment seeks current income and capital appreciation. Under normal circumstances, the fund will invest at least 80% of its net assets in equity securities that either have paid a dividend in the 12 months prior to purchase, or are expected by the Adviser to pay a dividend within 12 months following the fund''s purchase of the security. It will invest, under normal market conditions, in at least three different countries, one of which will be the United States. The fund will also invest at least 40% of its assets in foreign securities.', 0.0091, 0.0092, 21289990, 2.454258e+07, 7.925, 9.086, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 609340928, "Yield_Rate": null, "Expense_Net": 0.0091, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 21289990, "Vol_Recent": 24542580}, "moving_averages": {"MA_50": 7.925, "MA_200": 9.086}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
