INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1639, 'SDOG', 'ETF', 'us', 'BlackRock 20/80 Target Allocati', 'BlackRock 20/80 Target Allocation Fund Investor C Shares', 'US Dollar', 'Value', 'Medium', 'BlackRock', 'PCX', 'Large Value', 1213589632, 0.0322, '2012-06-29', NULL, 'The investment seeks a balance between long term capital appreciation and high current income, with an emphasis on income. The fund, which is a fund of funds, normally obtains exposure to equity securities (and certain other instruments) in an amount equal to 20% of its assets and exposure to fixed-income securities in an amount equal to 80% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.004, 0.0034, 32890, 33650, 52.503, 52.54, 0.997, 0, 2.44, 9.06, 20.17, 1.14, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 1213589632, "Yield_Rate": 0.0322, "Expense_Net": 0.004, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 32890, "Vol_Recent": 33650}, "moving_averages": {"MA_50": 52.503, "MA_200": 52.54}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.44, "PE_