INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1640, 'SDOW', 'ETF', 'United States', 'BlackRock Emerging Markets Flex', 'BlackRock Emerging Markets Flexible Dynamic Bond Portfolio Investor C Shares', 'DOLLAR', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Inverse Equity', 356676672, NULL, '2010-02-09', NULL, 'The investment seeks maximum long term total return. The fund invests primarily in a global portfolio of fixed income securities and derivatives of any maturity of issuers located in emerging markets that may be denominated in any currency (on a hedged or un-hedged basis). It will invest at least 80% of its assets in fixed income securities issued by governments, their political subdivisions (states, provinces and municipalities), agencies and companies tied economically to an emerging market. The fund is non-diversified.', 0.0095, 0.0092, 5885915, 8.80388e+06, 29.421, 33.882, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 356676672, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5885915, "Vol_Recent": 8803880}, "moving_averages": {"MA_50": 29.421, "MA_200": 33.882}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1641, 'SDP', 'ETF', 'US', 'Sterling Capital Equity Income', 'Sterling Capital Equity Income Fund Class C', 'AmericanDollar', NULL, NULL, 'Sterling Capital Funds', 'PCX', 'Trading--Inverse Equity', 2424885, NULL, '2007-01-30', 0.45, 'The investment seeks capital growth and current income. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in equity securities. It invests, under normal market conditions, primarily in dividend-paying equity securities, in particular common stocks of companies with a history of increasing dividend rates. The fund may also invest in U.S. traded common stocks of foreign companies, including American Depositary Receipts.', 0.0095, 0.0092, 4988, 3170, 14.964, 15.898, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 2424885, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": 0.45}', '{"volume_metrics": {"Vol_3M": 4988, "Vol_Recent": 3170}, "moving_averages": {"MA_50": 14.964, "MA_200": 15.898}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1643, 'SDVY', 'ETF', 'usa', 'BlackRock 60/40 Target Allocati', 'BlackRock 60/40 Target Allocation Fund Investor C Shares', 'US Dollar', 'Value', 'Small', 'BlackRock', 'NGM', NULL, 93201432, 0.0106, '2017-11-02', 0.76, 'The investment seeks long term capital appreciation, and current income is also a consideration. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 60% of its assets and exposure to fixed-income securities in an amount equal to 40% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.006, NULL, 133806, 142330, 29.678, 29.141, 0.9989, 0, 2.33, 10.84, 15.27, 1.44, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 93201432, "Yield_Rate": 0.0106, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": 0.76}', '{"volume_metrics": {"Vol_3M": 133806, "Vol_Recent": 142330}, "moving_averages": {"MA_50": 29.678, "MA_200": 29.141}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.33, "PE_Ratio": 15.27, "PS_Ratio": 1.44, "PCF_Ratio": 10.84}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1644, 'SECT', 'ETF', 'usa', 'American Century California Hig', 'American Century California High Yield Municipal Fund I Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', 'Large Blend', 906380032, 0.0052, '2017-09-05', 0.76, 'The investment seeks high current income that is exempt from federal and California income taxes. The fund invests at least 80% of its net assets in municipal securities with income payments exempt from federal and California income taxes. It invests in California municipal and other debt securities with an emphasis on high-yield securities. A high-yield security is one that has been rated below investment-grade, or determined by the investment advisor to be of similar quality. The portfolio managers also may buy unrated securities if they determine such securities meet the investment objectives of the fund.', 0.008, 0.0036, 63085, 66420, 42.944, 40.877, NULL, NULL, 3.24, 14.3, 21.66, 2.08, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 906380032, "Yield_Rate": 0.0052, "Expense_Net": 0.008, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.76}', '{"volume_metrics": {"Vol_3M": 63085, "Vol_Recent": 66420}, "moving_averages": {"MA_50": 42.944, "MA_200": 40.877}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.24, "PE_Ratio": 21.66, "PS_Ratio": 2.08, "PCF_Ratio": 14.3}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1645, 'SEF', 'ETF', 'U.S.A.', 'American Century California Hig', 'American Century California High Yield Municipal Fund Investor Class', 'AmericanDollar', NULL, NULL, 'American Century Investments', 'PCX', 'Trading--Inverse Equity', 16386888, NULL, '2008-06-10', NULL, 'The investment seeks high current income that is exempt from federal and California income taxes. The fund invests at least 80% of its net assets in municipal securities with income payments exempt from federal and California income taxes. It invests in California municipal and other debt securities with an emphasis on high-yield securities. A high-yield security is one that has been rated below investment-grade, or determined by the investment advisor to be of similar quality. The portfolio managers also may buy unrated securities if they determine such securities meet the investment objectives of the fund.', 0.0095, 0.0092, 12463, 30150, 11.954, 12.786, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 16386888, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12463, "Vol_Recent": 30150}, "moving_averages": {"MA_50": 11.954, "MA_200": 12.786}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1646, 'SEIX', 'ETF', 'USA', 'American Century California Int', 'American Century California Intermediate-Term Tax-Free Bond Fund A Class', 'US Dollar', 'Value', 'Small', 'American Century Investments', 'PCX', NULL, 20493360, 0.0383, '2019-04-23', 5.46, 'The investment seeks safety of principal and high current income that is exempt from federal and California income taxes. The fund primarily invests in investment-grade debt securities and, under normal market conditions, will invest at least 80% of its net assets in debt securities that have interest payments exempt from federal and California income taxes. Cities, counties and other municipalities in California and U.S. territories, such as Puerto Rico, issue these securities. The fund''s weighted average maturity will be not less than three years nor more than ten years. However, there is no maturity limit on individual securities.', 0.0057, NULL, 6316, 6830, 25.204, 25.012, NULL, NULL, NULL, NULL, NULL, NULL, 6.28, 0.98, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 20493360, "Yield_Rate": 0.0383, "Expense_Net": 0.0057, "Benchmark_Exp": null, "Turnover_Ratio": 5.46}', '{"volume_metrics": {"Vol_3M": 6316, "Vol_Recent": 6830}, "moving_averages": {"MA_50": 25.204, "MA_200": 25.012}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.28, "Duration_Yrs": 0.98}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1647, 'SENT', 'ETF', 'UNITED_STATES', 'BlackRock Funds II, BlackRock M', 'BlackRock Multi-Asset Income Portfolio Investor C Shares', 'USD', 'Growth', 'Medium', 'BlackRock', 'PCX', 'Large Growth', 69906736, NULL, '2021-02-02', NULL, 'The investment seeks to maximize current income with consideration for capital appreciation. The fund may invest up to 60% of its assets in equity securities and up to 100% of its assets in fixed income securities. In addition, it may invest in structured notes that provide exposure to covered call options or other types of financial instruments. The fund may also invest up to 15% of its assets in collateralized debt obligations ("CDOs"), including collateralized loan obligations ("CLOs").', 0.0112, 0.0039, 6737, 8420, 27.642, 27.044, 0.9938, 0, 5.3, 14.79, 26.99, 2.15, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 69906736, "Yield_Rate": null, "Expense_Net": 0.0112, "Benchmark_Exp": 0.0039, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6737, "Vol_Recent": 8420}, "moving_averages": {"MA_50": 27.642, "MA_200": 27.044}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9938}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.3, "PE_Ratio": 26.99, "PS_Ratio": 2.15, "PCF_Ratio": 14.79}}');
