INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1656, 'SGOL', 'ETF', 'United States', 'Brown Capital Management Mid Co', 'Brown Capital Management Mid Company Fund Investor Shares', 'Dollar', NULL, NULL, 'Brown Capital Management', 'PCX', NULL, 2351933440, NULL, '2009-09-09', 0.1142, 'The investment seeks long-term capital appreciation; current income is a secondary consideration in selecting portfolio investments. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in a portfolio of equity securities of companies with total operating revenues of $500 million to $5 billion at the time of initial investment ("mid sized companies"). It typically invests in common stocks. The fund typically holds a portfolio of between 40 to 60 securities which the Advisor believes have the potential for growth.', 0.0017, NULL, 1035960, 1.4609e+06, 17.192, 17.197, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 2351933440, "Yield_Rate": null, "Expense_Net": 0.0017, "Benchmark_Exp": null, "Turnover_Ratio": 0.1142}', '{"volume_metrics": {"Vol_3M": 1035960, "Vol_Recent": 1460900}, "moving_averages": {"MA_50": 17.192, "MA_200": 17.197}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1657, 'SGOV', 'ETF', 'US', 'Baird Core Plus Bond Fund Insti', 'Baird Core Plus Bond Fund Class Institutional', 'Dollar', 'Value', 'Large', 'Baird', 'PCX', NULL, 750064064, 0.0005, '2020-05-26', 3.26, 'The investment seeks an annual rate of total return, before fund expenses, greater than the annual rate of total return of the Bloomberg Barclays U.S. Universal Bond Index. The fund normally invests at least 80% of its net assets in the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector entities; asset-backed and mortgage-backed obligations of U.S. and foreign issuers; corporate debt of U.S. and foreign issuers. It invests primarily in investment-grade debt obligations, but may invest up to 20% of its net assets in non-investment grade debt obligations (sometimes referred to as "high yield" or "junk" bonds).', 0.0003, NULL, 47729, 32840, 100.021, 100.023, NULL, NULL, NULL, NULL, NULL, NULL, 0.22, 0.16, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 750064064, "Yield_Rate": 0.0005, "Expense_Net": 0.0003, "Benchmark_Exp": null, "Turnover_Ratio": 3.26}', '{"volume_metrics": {"Vol_3M": 47729, "Vol_Recent": 32840}, "moving_averages": {"MA_50": 100.021, "MA_200": 100.023}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.22, "Duration_Yrs": 0.16}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
