INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1674, 'SINV', 'ETF', 'us', 'American Century California Int', 'American Century California Intermediate-Term Tax-Free Bond Fund I Class', 'US$', NULL, NULL, 'American Century Investments', 'PCX', NULL, NULL, NULL, '2021-06-15', NULL, 'The investment seeks safety of principal and high current income that is exempt from federal and California income taxes. The fund primarily invests in investment-grade debt securities and, under normal market conditions, will invest at least 80% of its net assets in debt securities that have interest payments exempt from federal and California income taxes. Cities, counties and other municipalities in California and U.S. territories, such as Puerto Rico, issue these securities. The fund''s weighted average maturity will be not less than three years nor more than ten years. However, there is no maturity limit on individual securities.', 0.0095, NULL, 612, 490, 13.907, 13.966, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 612, "Vol_Recent": 490}, "moving_averages": {"MA_50": 13.907, "MA_200": 13.966}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1675, 'SIVR', 'ETF', 'US', 'Sterling Capital Behavioral Lar', 'Sterling Capital Behavioral Large Cap Value Equity Fund C', 'usd', NULL, NULL, 'Sterling Capital Funds', 'PCX', NULL, 1036550144, NULL, '2009-07-24', 0.0353, 'The investment seeks maximum long-term total return, by investing primarily in equity securities of large companies. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in the equity securities of large companies. Large companies are defined as companies with market capitalizations within the range of those companies in the Standard & Poor''s 500© Index at the time of purchase.', 0.003, NULL, 604466, 644270, 22.691, 24.254, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 1036550144, "Yield_Rate": null, "Expense_Net": 0.003, "Benchmark_Exp": null, "Turnover_Ratio": 0.0353}', '{"volume_metrics": {"Vol_3M": 604466, "Vol_Recent": 644270}, "moving_averages": {"MA_50": 22.691, "MA_200": 24.254}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
