INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1726, 'SPFF', 'ETF', 'USA', 'Boston Partners Emerging Market', 'Boston Partners Emerging Markets Dynamic Equity Fund Institutional Class', 'DOLLAR', NULL, NULL, 'Boston Partners', 'PCX', 'Preferred Stock', 218496880, 0.0562, '2012-07-16', 0.6765, 'The investment seeks long-term growth of capital. The fund will pursue its objective through investing in a non-diversified, multi-strategy long-short portfolio of equity securities and financial investments with equity like characteristics designed to provide exposure to emerging markets. The Advisor intends, under normal circumstances, to invest at least 80% of the fund''s net assets (including borrowings for investment purposes) in the securities of emerging market issuers, related derivative instruments and other investments that are tied economically to emerging market countries. The fund is non-diversified.', 0.0058, 0.0055, 69995, 74110, 11.855, 11.924, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 218496880, "Yield_Rate": 0.0562, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.6765}', '{"volume_metrics": {"Vol_3M": 69995, "Vol_Recent": 74110}, "moving_averages": {"MA_50": 11.855, "MA_200": 11.924}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": nu