INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1731, 'SPHQ', 'ETF', 'America', 'American Century Equity Growth ', 'American Century Equity Growth Fund A Class', 'US$', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 2947303936, 0.0124, '2005-12-06', 0.57, 'The investment seeks long-term capital growth by investing in common stocks. The fund invests at least 80% of its net assets in equity securities. In selecting stocks for the fund, the portfolio managers use quantitative and qualitative management techniques in a multi-step process. First, the managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures. Second, the portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0015, 0.0036, 619687, 1.12817e+06, 51.016, 48.233, 0.9997, 0, 4.56, 17.68, 24.34, 3.01, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 2947303936, "Yield_Rate": 0.0124, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.57}', '{"volume_metrics": {"Vol_3M": 619687, "Vol_Recent": 1128170}, "moving_averages": {"MA_50": 51.016, "MA_200": 48.233}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.56, "P