;
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1747, 'SPTL', 'ETF', 'us', 'Baron Focused Growth Fund Retai', 'Baron Focused Growth Fund Retail Shares', 'US$', NULL, NULL, 'Baron Capital Group, Inc.', 'PCX', 'Long Government', 3583414784, 0.017, '2007-05-23', 0.12, 'The investment seeks capital appreciation. The fund invests for the long term primarily in equity securities in the form of common stock of U.S. small- and mid-sized growth companies. The Adviser defines small- and mid-sized companies as those, at the time of purchase, with market capitalizations up to the largest market cap stock in the Russell Midcap Growth Index at reconstitution. Because of its long-term approach, the fund could have a significant percentage of its assets invested in securities that have appreciated beyond their original market cap ranges. It is non-diversified.', 0.0006, 0.0014, 3428649, 3.28205e+06, 41.758, 41.144, 0, 0.9999, NULL, NULL, NULL, NULL, 24.28, 18.8, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 3583414784, "Yield_Rate": 0.017, "Expense_Net": 0.0006, "Benchmark_Exp": 0.0014, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 3428649, "Vol_Recent": 3282050}, "moving_averages": {"MA_50": 41.758, "MA_200": 41.144}}', '{"asset_allocation": {"Bond_Weight": 0.9999, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 24.28, "Duration_Yrs": 18.8}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
