INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1759, 'SPXT', 'ETF', 'us', 'BlackRock Low Duration Bond Por', 'BlackRock Low Duration Bond Portfolio Institutional Shares', 'DOLLAR', 'Blend', 'Large', 'BlackRock', 'PCX', 'Large Blend', 7396839, 0.0132, '2015-09-22', NULL, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. The fund invests primarily in investment grade bonds and maintains an average portfolio duration that is between 0 and 3 years. It normally invests at least 80% of its assets in debt securities. The fund may invest up to 20% of its assets in non-investment grade bonds (commonly called "high yield" or "junk bonds"). It may also invest up to 35% of its assets in assets of foreign issuers, of which 10% (as a percentage of the fund''s assets) may be invested in emerging markets issuers.', 0.0027, 0.0036, 946, 490, 77.47, 74.154, NULL, NULL, 3.59, 16.23, 24.14, 2.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 7396839, "Yield_Rate": 0.0132, "Expense_Net": 0.0027, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 946, "Vol_Recent": 490}, "moving_averages": {"MA_50": 77.47, "MA_200": 74.154}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.59, "PE_Ratio": 24.14, "PS_Ratio": 2.45, "PCF_Ratio": 16.23}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1760, 'SPXU', 'ETF', 'UNITED_STATES', 'Berkshire Focus Fund', 'Berkshire Focus Fund', 'DOLLAR', NULL, NULL, 'Berkshire', 'PCX', 'Trading--Inverse Equity', 511489792, NULL, '2009-06-23', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in common stocks that are selected for their long-term growth potential. It may invest in companies of any size. The fund concentrates its investments in the electronic technology industry, which means more than 25%, and as much as 100%, of the fund''s total assets can be invested in that particular industry. It may invest without limitation in foreign securities and certain types of exchange traded funds. The fund is non-diversified.', 0.0093, 0.0092, 12397552, 2.205831e+07, 14.866, 18.431, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 511489792, "Yield_Rate": null, "Expense_Net": 0.0093, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12397552, "Vol_Recent": 22058310}, "moving_averages": {"MA_50": 14.866, "MA_200": 18.431}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2296, 'UNL', 'ETF', 'UNITED_STATES', 'BTS Managed Income Fund Class A', 'BTS Managed Income Fund Class A Shares', 'usd', NULL, NULL, 'BTS', 'PCX', NULL, 9979157, NULL, '2009-11-18', NULL, 'The investment seeks to provide total return. The fund invests primarily in a portfolio of income-producing securities, including bonds issued by the U.S. government, its agencies and instrumentalities; foreign and domestic debt securities; foreign and domestic equity securities of any market capitalization that pay dividends; underlying funds. The Adviser expects that up to 100% of the fund''s assets may be invested in underlying funds.', 0.009, NULL, 34415, 19760, 14.028, 10.726, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 9979157, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 34415, "Vol_Recent": 19760}, "moving_averages": {"MA_50": 14.028, "MA_200": 10.726}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
