INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1771, 'SRS', 'ETF', 'us', 'Baillie Gifford Global Alpha Eq', 'Baillie Gifford Global Alpha Equities Fund Class 3', 'USD', NULL, NULL, 'Baillie Gifford Funds', 'PCX', 'Trading--Inverse Equity', 15590135, NULL, '2007-01-30', NULL, 'The investment seeks capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in equity securities. It invests predominantly in a diversified portfolio of securities issued by companies located in countries represented in the MSCI ACWI Index, cash and cash equivalents. The fund invests in companies whose principal activities are in the U.S., Canada, Latin America, Europe, Australasia, Africa, the Middle East and/or the Far East.', 0.0095, 0.0092, 29141, 31950, 14.308, 16.674, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 15590135, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 29141, "Vol_Recent": 31950}, "moving_averages": {"MA_50": 14.308, "MA_200": 16.674}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1772, 'SRTY', 'ETF', 'America', 'Baron Global Advantage Fd Retai', 'Baron Global Advantage Fund Retail Shares', 'Dollar', NULL, NULL, 'Baron Capital Group, Inc.', 'PCX', 'Trading--Inverse Equity', 111350688, NULL, '2010-02-09', NULL, 'The investment seeks capital appreciation. The fund is a diversified fund that, under normal circumstances, invests primarily in equity securities in the form of common stock of established and emerging markets companies located throughout the world, with capitalizations within the range of companies included in the MSCI ACWI Index Net USD. At all times, it will have investments in equity securities of companies in at least three countries outside of the U.S. Under normal conditions, at least 40% of the fund''s net assets will be invested in stocks of companies outside the U.S. (at least 30% if foreign market conditions are not favorable).', 0.0095, 0.0092, 5821057, 9.6911e+06, 8.433, 9.599, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 111350688, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5821057, "Vol_Recent": 9691100}, "moving_averages": {"MA_50": 8.433, "MA_200": 9.599}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio":