INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1856, 'TRTY', 'ETF', 'U.S.A.', 'BlackRock Impact Bond Fund - Cl', 'BlackRock Systematic ESG Bond Fund Investor A', 'usd', 'Value', 'Medium', 'BlackRock', 'BTS', 'Tactical Allocation', 45831192, 0.0181, '2018-09-10', NULL, 'The investment seeks to provide a combination of income and capital growth. The fund seeks to provide a combination of income and capital growth by investing in a portfolio of debt securities, using model-based asset allocation and security selection models. To determine the fund''s investable universe, BlackRock will, utilizing BlackRock''s environmental, social, and governance ("ESG") research, first seek to screen out certain companies or industries based on ESG criteria determined by BlackRock. The fund invests, under normal circumstances, at least 80% of its assets in bonds.', 0.0048, 0.0112, 5370, 7800, 27.845, 27.545, NULL, NULL, 1.61, 6.73, 12.14, 0.83, 7.58, 6.47, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 45831192, "Yield_Rate": 0.0181, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0112, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5370, "Vol_Recent": 7800}, "moving_averages": {"MA_50": 27.845, "MA_200": 27.545}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.58, "Duration_Yrs": 6.47}}', '{"valuation_metrics": {"PB_Ratio": 1.61, "PE_Ratio": 12.14, "PS_Ratio": 0.83, "PCF_Ratio": 6.73}}');
