INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1858, 'TSJA', 'ETF', 'usa', 'Brown Advisory Equity Income Fd', 'Brown Advisory Equity Income Fund Investor Shares', 'US_DOLLAR', 'Blend', 'Large', 'Brown Advisory Funds', 'BTS', 'Large Blend', 31934502, NULL, '2020-12-31', NULL, 'The investment seeks to provide current dividend yield and dividend growth. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in a diversified portfolio of dividend paying equity securities. Equity securities include domestic and foreign common and preferred stock, convertible debt securities, American Depositary Receipts ("ADRs"), Master Limited Partnerships ("MLPs"), real estate investment trusts ("REITs") and exchange traded funds ("ETFs"), and the Adviser may also invest in private placements in these types of securities.', 0.0079, 0.0036, 4064, 2510, 29.305, 28.209, 0.9927, 0, 4.25, 16.9, 26.1, 2.69, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 31934502, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4064, "Vol_Recent": 2510}, "moving_averages": {"MA_50": 29.305, "MA_200": 28.209}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9927}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.25, "PE_Ratio": 26.1, "PS_Ratio": 2.69, "PCF_Ratio": 16.9}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1859, 'TSOC', 'ETF', 'usa', 'Brown Advisory Tax-Exempt Bond ', 'Brown Advisory Tax Exempt Bond Fund Investor Shares', 'Usd', 'Blend', 'Large', 'Brown Advisory Funds', 'BTS', 'Large Blend', 25855800, NULL, '2020-09-30', 37.42, 'The investment seeks to provide a high level of current income exempt from Federal income tax by investing primarily in intermediate-term investment grade municipal bonds. The fund normally will invest at least 80% of the fund''s net assets (plus borrowings for investment purposes) in securities the interest of which is exempt from Federal income taxes and that do not subject shareholders to the federal alternative minimum tax ("AMT"). It may invest up to 20% of its assets in securities that may fully subject shareholders to Federal income tax, including the AMT. The fund is non-diversified.', 0.0079, 0.0036, 7400, 7180, 31.508, 30.309, 0.9949, 0, 3.96, 15.98, 25.2, 2.44, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 25855800, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 37.42}', '{"volume_metrics": {"Vol_3M": 7400, "Vol_Recent": 7180}, "moving_averages": {"MA_50": 31.508, "MA_200": 30.309}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9949}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.96, "PE_Ratio": 25.2, "PS_Ratio": 2.44, "PCF_Ratio": 15.98}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1860, 'TSPA', 'ETF', 'us', 'Brown Advisory Flexible Equity ', 'Brown Advisory Flexible Equity Fund Investor Shares', 'usd', 'Blend', 'Large', 'Brown Advisory Funds', 'PCX', 'Large Blend', 16138502, NULL, '2021-06-08', NULL, 'The investment seeks to achieve long-term growth of capital. The fund normally invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in a diversified portfolio of equity securities. It invests primarily in securities of medium and large market capitalization companies that the Adviser believes have strong, or improving, long-term business characteristics and share prices that do not reflect these favorable fundamental attributes. The fund may invest up to 15% of its net assets in foreign securities, including emerging markets.', 0.0034, 0.0036, 2830, 3450, 27.027, 26.429, 0.993, 0, 4.2, 18.89, 27.37, 3.17, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 16138502, "Yield_Rate": null, "Expense_Net": 0.0034, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2830, "Vol_Recent": 3450}, "moving_averages": {"MA_50": 27.027, "MA_200": 26.429}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.2, "PE_Ratio": 27.37, "PS_Ratio": 3.17, "PCF_Ratio": 18.89}}');
