INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1872, 'UAPR', 'ETF', 'UNITED_STATES', 'Brown Advisory Value Equity Inv', 'Brown Advisory - Beutel Goodman Large-Cap Value Fund Investor Shares', 'AmericanDollar', 'Blend', 'Large', 'Brown Advisory Funds', 'BTS', NULL, 61513908, NULL, '2019-03-29', NULL, 'The investment seeks to achieve capital appreciation. Under normal conditions, the fund seeks to achieve its investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of large-cap companies. It seeks to invest in companies at discounts to their business value, which the advisor considers to be the present value of sustainable free cash flow. The fund may invest up to 20% of its net assets in foreign securities. It is non-diversified.', 0.0079, NULL, 10006, 17660, 26.011, 25.639, 0.9905, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 61513908, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10006, "Vol_Recent": 17660}, "moving_averages": {"MA_50": 26.011, "MA_200": 25.639}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9905}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1873, 'UAUG', 'ETF', 'America', 'Brown Advisory Sustainable Grow', 'Brown Advisory Sustainable Growth Fund Investor Shares', 'Dollar', 'Blend', 'Large', 'Brown Advisory Funds', 'BTS', NULL, 21450422, NULL, '2019-07-31', NULL, 'The investment seeks to achieve capital appreciation. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in equity securities of sustainable domestic companies. It invests primarily in the securities of medium and large capitalization companies that Brown Advisory LLC (the "Adviser") believes (1) have the fundamental strengths (strong financials and business models) to outperform their peers and deliver above-average earnings growth over a market cycle, (2) effectively implement Sustainable Business Advantages, and (3) have attractive valuations.', 0.0079, NULL, 12379, 1670, 28.893, 28.576, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 21450422, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12379, "Vol_Recent": 1670}, "moving_averages": {"MA_50": 28.893, "MA_200": 28.576}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1874, 'UBOT', 'ETF', 'America', 'Brown Advisory Mortgage Securit', 'Brown Advisory Mortgage Securities Fund Investor Shares', 'US$', 'Growth', 'Large', 'Brown Advisory Funds', 'PCX', 'Trading--Leveraged Equity', 46999344, 0.1467, '2018-04-19', 0.93, 'The investment seeks to maximize total return consistent with preservation of capital. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in investment grade mortgage-related securities. It invests in securities of various maturities and durations. The fund may invest in derivatives instruments, such as options, futures contracts, including interest rate futures, and options on futures.', 0.0132, 0.009, 13185, 11740, 48.912, 44.623, NULL, NULL, 4.14, 23.35, 47.48, 3.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 46999344, "Yield_Rate": 0.1467, "Expense_Net": 0.0132, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.93}', '{"volume_metrics": {"Vol_3M": 13185, "Vol_Recent": 11740}, "moving_averages": {"MA_50": 48.912, "MA_200": 44.623}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.14, "PE_Ratio": 47.48, "PS_Ratio": 3.63, "PCF_Ratio": 23.35}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1875, 'UBR', 'ETF', 'UNITED_STATES', 'BlackRock Global Dividend Ptf I', 'BlackRock Global Dividend Portfolio Insitutional Shares', 'US Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 8984093, NULL, '2010-04-27', NULL, 'The investment seeks to provide a level of current income that exceeds the average yield on global stocks generally. Under normal circumstances, the fund will invest at least 80% of its net assets in dividend-paying equity securities and at least 40% of its assets outside of the U.S. (unless market conditions are not deemed favorable by fund management, in which case the fund would invest at least 30% of its assets outside of the U.S.). It will primarily invest in common stock, preferred stock, securities convertible into common and preferred stock and non-convertible preferred stock.', 0.0095, 0.009, 15460, 14110, 23.091, 30.838, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 8984093, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 15460, "Vol_Recent": 14110}, "moving_averages": {"MA_50": 23.091, "MA_200": 30.838}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1876, 'UBT', 'ETF', 'United States', 'BlackRock U.S. Impact Fund Inst', 'BlackRock U.S. Impact Fund Institutional', 'Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Leveraged Debt', 36324868, NULL, '2010-01-19', 0.48, 'The investment seeks total return. Under normal circumstances, the fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in U.S. securities. It will invest primarily in equity securities and other financial instruments that have similar economic characteristics to such securities. The fund may invest in issuers of any market capitalization, including small- to mid-capitalization companies. It is non-diversified.', 0.0095, 0.0095, 46369, 69830, 53.539, 51.597, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 36324868, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0095, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 46369, "Vol_Recent": 69830}, "moving_averages": {"MA_50": 53.539, "MA_200": 51.597}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1877, 'UCC', 'ETF', 'UNITED_STATES', 'BlackRock International Impact ', 'BlackRock International Impact Fund Investor A', 'US_DOLLAR', 'Growth', 'Large', 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 32970542, NULL, '2007-01-30', 0.37, 'The investment seeks total return. Under normal circumstances, the fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities of foreign issuers and other financial instruments that have similar economic characteristics to such securities. It may invest in emerging market issuers, and may invest in issuers of any market capitalization, including small- to mid-capitalization companies. The fund may enter into forward foreign exchange transactions in order to hedge (or protect) the value of its assets against adverse movements in currency exchange rates. It is non-diversified.', 0.0095, 0.009, 2590, 2610, 105.716, 100.82, NULL, NULL, NULL, NULL, NULL, 1.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 32970542, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.37}', '{"volume_metrics": {"Vol_3M": 2590, "Vol_Recent": 2610}, "moving_averages": {"MA_50": 105.716, "MA_200": 100.82}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null