INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1886, 'UFO', 'ETF', 'U.S.', 'BlackRock Commodity Strategies ', 'BlackRock Commodity Strategies Portfolio Institutional Shares', 'DOLLAR', 'Value', 'Medium', 'BlackRock', 'NGM', NULL, 128057720, 0.0098, '2019-04-10', NULL, 'The investment seeks total return. The adviser utilizes two strategies and under normal circumstances expects to invest approximately 50% of its total assets in each strategy. One strategy focuses on investments in commodity-linked derivatives. To meet coverage and collateral requirements associated with these derivative investments, and to invest excess cash, the fund holds a portion of its portfolio in investment-grade short-term fixed-income securities. The other strategy focuses on equity investments in commodity-related companies, including, but not limited to, companies operating in the mining, energy and agricultural sectors.', 0.0075, NULL, 40427, 47170, 30.066, 29.933, 0.995, 0, 1.77, 7.64, 18.36, 2.16, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 128057720, "Yield_Rate": 0.0098, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 40427, "Vol_Recent": 47170}, "moving_averages": {"MA_50": 30.066, "MA_200": 29.933}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.77, "PE_Ratio": 18.36, "PS_Ratio": 2.16, "PCF_Ratio": 7.64}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1887, 'UGCE', 'ETF', 'U.S.A.', 'iShares Municipal Bond Index Fu', 'iShares Municipal Bond Index Fund Investor A Shares', 'US$', 'Blend', 'Large', 'BlackRock', 'PCX', NULL, 1006598, NULL, '2021-04-15', NULL, 'The investment seeks to provide investment results that correspond to the total return performance of fixed-income securities in the aggregate, as represented by the ICE BofA US Municipal Securities Index. The fund generally invests at least 80% of its assets, plus the amount of any borrowings for investment purposes, in securities or other financial instruments that are components of or have economic characteristics similar to the securities in the index. The index tracks the performance of U.S. dollar denominated investment grade tax-exempt debt publicly issued by U.S. states and territories, and their political subdivisions, in the U.S. domestic market.', 0.0065, NULL, 5896, 5350, 26.405, 25.947, NULL, NULL, 3.19, 13.76, 26.71, 1.37, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1006598, "Yield_Rate": null, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5896, "Vol_Recent": 5350}, "moving_averages": {"MA_50": 26.405, "MA_200": 25.947}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.19, "PE_Ratio": 26.71, "PS_Ratio": 1.37, "PCF_Ratio": 13.76}}');
