INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1907, 'UPW', 'ETF', 'USA', 'BlackRock 60/40 Target Allocati', 'BlackRock 60/40 Target Allocation Fund Institutional Shares', 'AmericanDollar', 'Value', 'Medium', 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 13122245, 0.0097, '2007-01-30', 0.13, 'The investment seeks long term capital appreciation, and current income is also a consideration. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 60% of its assets and exposure to fixed-income securities in an amount equal to 40% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0095, 0.009, 7680, 2800, 63.534, 62.2, NULL, NULL, NULL, NULL, NULL, 2.61, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 13122245, "Yield_Rate": 0.0097, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.13}', '{"volume_metrics": {"Vol_3M": 7680, "Vol_Recent": 2800}, "moving_averages": {"MA_50": 63.534, "MA_200": 62.2}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 2.61, "PCF_