INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1908, 'URA', 'ETF', 'United States', 'Disciplined Core Value Fund - I', 'American Century Disciplined Core Value Fund Investor Class', 'usd', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Natural Resources', 736381824, 0.006, '2010-11-04', 0.5912, 'The investment seeks long-term capital growth; income is a secondary consideration. In selecting stocks for the fund, the managers use quantitative and qualitative management techniques in a multi-step process. The managers evaluate stocks, primarily large capitalization, publicly traded U.S. companies based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use quantitative models to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0069, 0.0048, 2404060, 2.10075e+06, 26.995, 22.222, 0.9998, 0, 2.11, NULL, NULL, 1.67, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 736381824, "Yield_Rate": 0.006, "Expense_Net": 0.0069, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.5912}', '{"volume_metrics": {"Vol_3M": 2404060, "Vol_Recent": 2100750}, "moving_averages": {"MA_50": 26.995, "MA_200": 22.222}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.11, "PE_Ratio": null, "PS_Ratio": 1.67, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1909, 'URE', 'ETF', 'us', 'The Texas Fund Class I', 'The Texas Fund Class I', 'usd', 'Blend', 'Medium', 'Monteagle Funds', 'PCX', 'Trading--Leveraged Equity', 122136368, 0.0051, '2007-01-30', 0.41, 'The investment seeks long-term capital appreciation. The fund will be invested across a broad market capitalization spectrum, including small, mid and large capitalization companies. The Sub-Adviser typically selects companies in which to invest by performing an initial market capitalization screening of $500 million or more. The Sub-Adviser analyzes factors such as financial conditions, industry position, and market and economic conditions and trends to select investments and make buy and sell decisions.', 0.0095, 0.009, 8130, 7490, 99.258, 89.019, NULL, NULL, NULL, NULL, NULL, 6.78, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 122136368, "Yield_Rate": 0.0051, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.41}', '{"volume_metrics": {"Vol_3M": 8130, "Vol_Recent": 7490}, "moving_averages": {"MA_50": 99.258, "MA_200": 89.019}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 6.78, "PCF_Ratio": null}}');
