INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1935, 'UTSL', 'ETF', 'UNITED_STATES', 'iShares Developed Real Estate I', 'iShares Developed Real Estate Index Fund Institutional Shares', 'AmericanDollar', 'Value', 'Large', 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 20672216, 0.0128, '2017-05-03', 0.8, 'The investment seeks to track the investment results of an index composed of real estate equities in developed markets. The fund seeks to track the investment results of the FTSE EPRA/NAREIT Developed Index, which measures the stock performance of companies engaged in the ownership, disposal and development of income-producing real estate in developed countries as defined by FTSE EPRA/NAREIT. It generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index and in depositary receipts representing securities of the underlying index.', 0.01, 0.009, 94424, 98740, 31.446, 30.63, NULL, NULL, 2.2, 12.04, 23.2, 2.79, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 20672216, "Yield_Rate": 0.0128, "Expense_Net": 0.01, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.8}', '{"volume_metrics": {"Vol_3M": 94424, "Vol_Recent": 98740}, "moving_averages": {"MA_50": 31.446, "MA_200": 30.63}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.2, "PE_Ratio": 23.2, "PS_Ratio": 2.79, "PCF_Ratio": 12.04}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1936, 'UUP', 'ETF', 'us', 'BlackRock Real Estate Securitie', 'BlackRock Real Estate Securities Fund Institutional Shares', 'US Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Miscellaneous', 430025568, NULL, '2007-02-20', NULL, 'The investment seeks total return comprised of long-term growth of capital and dividend income. The fund normally invests at least 80% of its net assets plus any borrowings for investment purposes (measured at the time of purchase) in a portfolio of equity investments in issuers that are primarily engaged in or related to the real estate industry inside the United States. It may invest up to 20% of its net assets plus any borrowings for investment purposes in a portfolio of equity investments in issuers that are primarily engaged in or related to the real estate industry outside the United States and fixed-income investments. The fund is non-diversified.', 0.0075, 0.0087, 868280, 1.1403e+06, 25.387, 24.864, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 430025568, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 868280, "Vol_Recent": 1140300}, "moving_averages": {"MA_50": 25.387, "MA_200": 24.864}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
