INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1985, 'VOT', 'ETF', 'America', 'BlackRock Low Duration Bond Por', 'BlackRock Low Duration Bond Portfolio Class R', 'US$', 'Growth', 'Medium', 'BlackRock', 'PCX', 'Mid-Cap Growth', 23272884224, 0.004, '2006-08-17', 0.22, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. The fund invests primarily in investment grade bonds and maintains an average portfolio duration that is between 0 and 3 years. It normally invests at least 80% of its assets in debt securities. The fund may invest up to 20% of its assets in non-investment grade bonds (commonly called "high yield" or "junk bonds"). It may also invest up to 35% of its assets in assets of foreign issuers, of which 10% (as a percentage of the fund''s assets) may be invested in emerging markets issuers.', 0.0007, 0.0046, 121544, 211500, 251.492, 234.957, 0.9993, 0, 6.65, 26.43, 39.53, 5.13, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 23272884224, "Yield_Rate": 0.004, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.22}', '{"volume_metrics": {"Vol_3M": 121544, "Vol_Recent": 211500}, "moving_averages": {"MA_50": 251.492, "MA_200": 234.957}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6.65, "PE_Ratio": 39.53, "PS_Ratio": 5.13, "PCF_Ratio": 26.43}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2069, 'XPND', 'ETF', 'U.S.A.', 'MFS Blended Research Mid Cap Eq', 'MFS Blended Research Mid Cap Equity Fund R6', 'Dollar', NULL, NULL, 'MFS', 'PCX', NULL, NULL, NULL, '2021-06-14', NULL, 'The investment seeks capital appreciation. The adviser normally invests at least 80% of the fund''s net assets in equity securities of issuers with medium market capitalizations. Equity securities include common stocks, equity interests in real estate investment trusts (REITs), and other securities that represent an ownership interest (or right to acquire an ownership interest) in a company or other issuer. The adviser may invest the fund''s assets in foreign securities.', 0.0065, NULL, 3227, 3330, 21.804, 21.45, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3227, "Vol_Recent": 3330}, "moving_averages": {"MA_50": 21.804, "MA_200": 21.45}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
