INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2008, 'VUSE', 'ETF', 'U.S.', 'BMO Low Volatility Equity Fund ', 'BMO Low Volatility Equity Fund Class A', 'USD', 'Value', 'Medium', 'BMO Funds', 'PCX', 'Mid-Cap Value', 432381504, 0.0106, '2014-01-22', 0.66, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in a broadly diversified portfolio of common stocks of large-sized U.S. companies similar in size, at the time of purchase, to those within the Russell 1000© Index. The Adviser selects low volatility, undervalued stocks using a unique approach which combines the use of proprietary analytical tools and the qualitative judgments of the investment team. This strategy seeks to provide the fund with lower downside risk and meaningful upside participation relative to the Russell 1000© Index.', 0.0048, 0.0043, 22045, 25130, 45.149, 43.646, 0.9991, 0, 1.99, 6.9, 14.82, 0.77, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 432381504, "Yield_Rate": 0.0106, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 0.66}', '{"volume_metrics": {"Vol_3M": 22045, "Vol_Recent": 25130}, "moving_averages": {"MA_50": 45.149, "MA_200": 43.646}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.99, "PE_Ratio": 14.82, "PS_Ratio": 0.77, "PCF_Ratio": 6.9}}');
