INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2038, 'WOMN', 'ETF', 'us', 'BNY Mellon Income Stock Fund - ', 'BNY Mellon Income Stock Fund Class A', 'Dollar', 'Blend', 'Large', 'BNY Mellon Funds', 'PCX', 'Large Blend', 29561784, 0.0517, '2018-08-24', 0.47, 'The investment seeks total return (consisting of capital appreciation and income). The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in stocks. It focuses on dividend-paying stocks and other investments and investment techniques that provide income. The fund emphasizes those stocks with value characteristics, although it may also purchase growth stocks. It may invest in the stocks of companies of any size, although it focuses on large-cap companies. The fund also may invest up to 10% of its assets in convertible securities and up to 10% of its assets in preferred stocks.', 0.0075, 0.0036, 3422, 3830, 34.625, 32.859, 1, 0, 4.48, 16.43, 27.14, 2.87, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 29561784, "Yield_Rate": 0.0517, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.47}', '{"volume_metrics": {"Vol_3M": 3422, "Vol_Recent": 3830}, "moving_averages": {"MA_50": 34.625, "MA_200": 32.859}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.48, "PE_Ratio": 27.14, "PS_Ratio": 2.87, "PCF_Ratio": 16.43}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2039, 'WOOD', 'ETF', 'US', 'BlackRock Managed Income Fund -', 'BlackRock Managed Income Fund Investor C Shares', 'Usd', 'Value', 'Medium', 'BlackRock', 'NGM', 'Natural Resources', 328984544, 0.0135, '2008-06-24', 0.14, 'The investment seeks to maximize current income with consideration for risk-managed total return. The fund may invest up to 100% of its assets in fixed-income securities and up to 30% of its assets in equity securities. It may also gain exposure to such fixed-income securities and equity securities by investing in BlackRock fixed-income and/or equity mutual funds and affiliated and unaffiliated ETFs. With respect to the fund''s fixed-income investments, the fund may invest in fixed-income securities such as corporate bonds and notes, commercial and residential mortgage-backed securities, asset-backed securities, municipal securities, etc.', 0.0046, 0.0048, 20192, 16320, 86.014, 87.96, 0.9943, 0, 1.69, 7.01, 12.62, 1.11, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 328984544, "Yield_Rate": 0.0135, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 20192, "Vol_Recent": 16320}, "moving_averages": {"MA_50": 86.014, "MA_200": 87.96}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9943}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.69, "PE_Ratio": 12.62, "PS_Ratio": 1.11, "PCF_Ratio": 7.01}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2040, 'WTMF', 'ETF', 'USA', 'Brown Advisory Mid-Cap Growth F', 'Brown Advisory Mid-Cap Growth Fund Investor Class', 'Usd', 'Blend', 'Large', 'Brown Advisory Funds', 'PCX', 'Managed Futures', 136264192, 0.0042, '2011-01-05', 0.97, 'The investment seeks to achieve long-term capital appreciation. The Adviser seeks to achieve the fund''s investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of mid-cap domestic companies. The fund invests primarily in companies the Adviser believes possess "3G" criteria: durable growth, sound governance, and scalable go-to-market strategies. It may invest in ETFs and other types of investment companies that have an investment objective similar to the fund''s or that otherwise are permitted investments with the fund''s investment policies described herein.', 0.0065, 0.0087, 27546, 38960, 37.116, 39.73, NULL, NULL, 2.07, 11.5, 24.25, 1.7, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 136264192, "Yield_Rate": 0.0042, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0087, "Turnover_Ratio": 0.97}', '{"volume_metrics": {"Vol_3M": 27546, "Vol_Recent": 38960}, "moving_averages": {"MA_50": 37.116, "MA_200": 39.73}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.07, "PE_Ratio": 24.25, "PS_Ratio": 1.7, "PCF_Ratio": 11.5}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2041, 'WUGI', 'ETF', 'United States', 'BNY Mellon Income Stock Fund - ', 'BNY Mellon Income Stock Fund Class I', 'USD', 'Growth', 'Large', 'BNY Mellon Funds', 'BTS', 'Technology', 51790920, NULL, '2020-03-31', 1.3, 'The investment seeks total return (consisting of capital appreciation and income). The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in stocks. It focuses on dividend-paying stocks and other investments and investment techniques that provide income. The fund emphasizes those stocks with value characteristics, although it may also purchase growth stocks. It may invest in the stocks of companies of any size, although it focuses on large-cap companies. The fund also may invest up to 10% of its assets in convertible securities and up to 10% of its assets in preferred stocks.', 0.0075, 0.0053, 3309, 3790, 63.092, 56.646, 0.9986, 0, 10.73, 31.3, 37.4, 3.18, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 51790920, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 1.3}', '{"volume_metrics": {"Vol_3M": 3309, "Vol_Recent": 3790}, "moving_averages": {"MA_50": 63.092, "MA_200": 56.646}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.73, "PE_Ratio": 37.4, "PS_Ratio": 3.18, "PCF_Ratio": 3