INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2056, 'XHS', 'ETF', 'U.S.A.', 'BlackRock Mid-Cap Growth Equity', 'BlackRock Mid-Cap Growth Equity Portfolio Class R', 'AmericanDollar', 'Blend', 'Medium', 'BlackRock', 'PCX', 'Health', 211576352, 0.0018, '2011-09-28', 0.25, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets in equity securities issued by U.S. mid-capitalization companies which the fund management believes have above-average earnings growth potential. The fund adviser generally defines these companies, at the time of the fund''s investment, as those with market capitalizations comparable in size to the companies in the Russell Midcap© Growth Index. It primarily invests in common stock but also can invest in preferred stock, convertible securities and other equity securities.', 0.0035, 0.0049, 15390, 17260, 104.971, 108.441, 0.9987, 0, 3.81, 8.03, 18.3, 0.66, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 211576352, "Yield_Rate": 0.0018, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0049, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 15390, "Vol_Recent": 17260}, "moving_averages": {"MA_50": 104.971, "MA_200": 108.441}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.81, "PE_Ratio": 18.3, "PS_Ratio": 0.66, "PCF_Ratio": 8.03}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2057, 'XITK', 'ETF', 'America', 'BlackRock Credit Strategies Inc', 'BlackRock Income Fund Investor A Shares', 'US_DOLLAR', 'Growth', 'Medium', 'BlackRock', 'PCX', NULL, 371859264, 0.0006, '2016-01-13', 0.35, 'The investment seeks to provide high current income, with a secondary objective of long-term capital appreciation. The fund invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in fixed-income securities. It may invest in such fixed-income securities of issuers located in the United States and non-U.S. countries, including emerging market countries. The fund may invest in instruments of any credit quality without limitation, including instruments rated below investment grade, which are commonly referred to as "junk bonds."', 0.0045, NULL, 6653, 9250, 222.321, 219.209, NULL, NULL, 7.36, 28.15, NULL, 6.65, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 371859264, "Yield_Rate": 0.0006, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 6653, "Vol_Recent": 9250}, "moving_averages": {"MA_50": 222.321, "MA_200": 219.209}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.36, "PE_Ratio": null, "PS_Ratio": 6.65, "PCF_Ratio": 28.15}}');
