INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2071, 'XRLV', 'ETF', 'United States', 'BMO Mid Cap Value Fund Class R-', 'BMO Mid-Cap Value Fund Class R6', 'DOLLAR', 'Blend', 'Large', 'BMO Funds', 'PCX', 'Large Blend', 50448888, 0.0125, '2015-04-06', 0.84, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in value-oriented common stocks of medium-sized U.S. companies similar in size, at the time of purchase, to those within the Russell Midcap© Value Index. The Adviser selects stocks using a unique, value-oriented approach focusing on high quality companies with long-term capital appreciation potential that are available at reasonable prices, which combines the use of proprietary analytical tools and the qualitative judgments of the investment team.', 0.0025, 0.0036, 1045, 770, 48.723, 46.936, 0.9998, 0, 4.41, 14.88, 23.19, 2, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 50448888, "Yield_Rate": 0.0125, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.84}', '{"volume_metrics": {"Vol_3M": 1045, "Vol_Recent": 770}, "moving_averages": {"MA_50": 48.723, "MA_200": 46.936}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.41, "PE_Ratio": 23.19, "PS_Ratio": 2, "PCF_Ratio": 14.88}}');
