INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2083, 'XVOL', 'ETF', 'U.S.A.', 'UBS U.S. Small Cap Growth Fund ', 'UBS U.S. Small Cap Growth Fund Class A', 'Dollar', 'Blend', 'Large', 'UBS Asset Management', 'PCX', 'Large Blend', 80248464, NULL, '2021-04-21', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (plus borrowings for investment purposes, if any) in equity securities of U.S. small capitalization companies. Small capitalization companies are those companies within the range of the largest and smallest company in the Russell 2000 Index at the time of purchase. Investments in equity securities may include, but are not limited to, common stock and preferred stock; equity securities of real estate investment trusts ("REITs"); and exchange-traded funds ("ETFs"). The fund may invest up to 20% of its net assets in foreign securities.', 0.0083, 0.0036, 11948, 8110, 21.583, 20.985, 0.9986, 0, 4.38, 17.47, 26.3, 2.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 80248464, "Yield_Rate": null, "Expense_Net": 0.0083, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11948, "Vol_Recent": 8110}, "moving_averages": {"MA_50": 21.583, "MA_200": 20.985}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.38, "PE_Ratio": 2