INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2087, 'XYLG', 'ETF', 'us', 'Sterling Capital Special Opport', 'Sterling Capital Special Opportunities Fund Class A', 'USD', 'Blend', 'Large', 'Sterling Capital Funds', 'PCX', NULL, 4174034, NULL, '2020-09-18', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in equity securities. It primarily invests in domestically traded U.S. common stocks and U.S. traded equity stocks of foreign companies, including ADRs. The fund uses a multi-style approach, meaning that it not only invests across different capitalization levels but may target both value- and growth-oriented companies.', 0.006, NULL, 6162, 4810, 31.487, 30.284, 0.9953, 0, 4.21, 17.25, 27.34, 2.94, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 4174034, "Yield_Rate": null, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6162, "Vol_Recent": 4810}, "moving_averages": {"MA_50": 31.487, "MA_200": 30.284}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.21, "PE_Ratio": 27.34, "PS_Ratio": 2.94, "PCF_Ratio": 17.25}}');
