INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2104, 'ZSL', 'ETF', 'United States', 'UBS Global Allocation Fund clas', 'UBS Global Allocation Fund Class P', 'DOLLAR', NULL, NULL, 'UBS Asset Management', 'PCX', 'Trading--Inverse Commodities', 34861008, NULL, '2008-12-01', NULL, 'The investment seeks to maximize total return, consisting of capital appreciation and current income. The fund will invest in securities and derivatives to gain exposure to equity, fixed income, and alternative asset class securities, including, but not limited to, convertible bonds and real estate securities, including real estate investment trusts and real estate operating companies. It may gain exposure to issuers located within and outside the United States, including securities of issuers in both developed (including the United States) and emerging markets countries.', 0.0139, 0.0085, 248719, 216270, 27.136, 25.688, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 34861008, "Yield_Rate": null, "Expense_Net": 0.0139, "Benchmark_Exp": 0.0085, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 248719, "Vol_Recent": 216270}, "moving_averages": {"MA_50": 27.136, "MA_200": 25.688}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2105, 'AAA', 'ETF', 'US', 'BMO Pyrford Intl Stock Fd - Cla', 'BMO Pyrford International Stock Fund Class A', 'DOLLAR', NULL, NULL, 'BMO Funds', 'PCX', NULL, 10019622, NULL, '2020-09-09', NULL, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in equity securities of companies located in a number of countries outside the United States. It invests primarily in companies that are located in the countries included, at the time of purchase, in the MSCI EAFE Index, which includes developed countries outside of North America. Although the fund may invest in companies across all market capitalizations, it invests primarily in companies that, at the time of purchase, have a minimum market capitalization of $2 billion.', 0.0025, NULL, 1312, 3510, 25.013, 25.023, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 10019622, "Yield_Rate": null, "Expense_Net": 0.0025, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1312, "Vol_Recent": 3510}, "moving_averages": {"MA_50": 25.013, "MA_200": 25.023}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2106, 'ACVF', 'ETF', 'usa', 'Boston Partners Long/Short Rese', 'Boston Partners Long/Short Research Fund Institutional Class', 'USD', 'Blend', 'Large', 'Boston Partners', 'PCX', NULL, 7851504, NULL, '2020-10-28', NULL, 'The investment seeks long-term total return. The fund actively invests in long positions in stocks identified by the Adviser as undervalued and takes short positions in stocks that the Adviser has identified as overvalued. The cash proceeds from short sales (i.e. sales of securities the fund does not own) are invested in short-term cash instruments to produce a return on such proceeds just below the federal funds rate. The fund invests, both long and short, in equity securities issued by large-, mid- and small (or "micro") cap companies, as well as other instruments that are convertible into equity securities.', 0.0075, NULL, 12300, 6760, 33.917, 31.995, 1, 0, 3.98, 17.08, 27.9, 2.6, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 7851504, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12300, "Vol_Recent": 6760}, "moving_averages": {"MA_50": 33.917, "MA_200": 31.995}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.98, "PE_Ratio": 27.9, "PS_Ratio": 2.6, "PCF_Ratio": 17.08}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2107, 'ADME', 'ETF', 'UNITED_STATES', 'BlackRock Inflation Protected B', 'BlackRock Inflation Protected Bond Fund Class K', 'US_DOLLAR', 'Growth', 'Large', 'BlackRock', 'BTS', NULL, 226446832, 0.0034, '2016-06-08', 2.3, 'The investment seeks to maximize real return, consistent with preservation of real capital and prudent investment management. The fund invests at least 80% of its assets in inflation-indexed bonds of varying maturities issued by the U.S. and non-U.S. governments, their agencies or instrumentalities, and U.S. and non-U.S. corporations. It may invest up to 20% of its assets in non-investment grade bonds or securities of emerging market issuers. The fund maintains an average portfolio duration that is within Â±20% of the duration of the Bloomberg Barclays U.S. Treasury Inflation Protected Securities Index (the benchmark).', 0.0079, NULL, 34154, 39240, 41.332, 39.527, 0.9993, 0, 5.56, 21.02, 30.74, 4.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 226446832, "Yield_Rate": 0.0034, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": 2.3}', '{"volume_metrics": {"Vol_3M": 34154, "Vol_Recent": 39240}, "moving_averages": {"MA_50": 41.332, "MA_200": 39.527}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.56, "PE_Ratio": 30.74, "PS_Ratio": 4.21, "PCF_Ratio": 21.02}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2108, 'JMUB', 'ETF', 'US', 'Boston Partners Long/Short Equi', 'Boston Partners Long/Short Equity Fund Investor Class', 'USD', NULL, NULL, 'Boston Partners', 'BTS', 'Muni National Interm', 85608224, 0.0166, '2018-10-29', NULL, 'The investment seeks long-term capital appreciation while reducing exposure to general equity market risk and a total return greater than that of the S&P 500© Index over a full market cycle. The fund invests in long positions in stocks identified by the Adviser as undervalued and takes short positions in stocks that the Adviser has identified as overvalued. The Advisor intends, under normal circumstances, to invest at least 80% of its net assets (including borrowings for investment purposes) in equity securities. Under normal circumstances, the Adviser expects that the fund''s long positions will not exceed approximately 125% of the fund''s net assets.', 0.0018, 0.0029, 7735, 4310, 54.882, 55.061, NULL, NULL, NULL, NULL, NULL, NULL, 6.28, 5.44, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 85608224, "Yield_Rate": 0.0166, "Expense_Net": 0.0018, "Benchmark_Exp": 0.0029, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7735, "Vol_Recent": 4310}, "moving_averages": {"MA_50": 54.882, "MA_200": 55.061}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.28, "Duration_Yrs": 5.44}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
