INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2121, 'CPER', 'ETF', 'U.S.', 'Bright Rock Quality Large Cap F', 'Bright Rock Quality Large Cap Fund Institutional Class', 'USD', NULL, NULL, 'Bright Rock', 'PCX', NULL, 311627520, NULL, '2011-11-14', NULL, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets in equity securities of companies with large-sized market capitalizations. The adviser defines large-cap companies as those companies with market capitalizations within the range of companies in the Russell 1000© Index at the time of investment. The fund may invest up to 25% of its net assets in securities of foreign large-cap companies that are traded in the U.S., including companies located in emerging markets, as well as American Depositary Receipts.', 0.008, NULL, 279239, 212380, 26.741, 26.557, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 311627520, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 279239, "Vol_Recent": 212380}, "moving_averages": {"MA_50": 26.741, "MA_200": 26.557}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2122, 'DGLDF', 'ETF', 'usa', 'Bright Rock Mid Cap Growth Fund', 'Bright Rock Mid Cap Growth Fund Institutional Class', 'Dollar', NULL, NULL, 'Bright Rock', 'PNK', 'Trading--Inverse Commodities', 9882672, NULL, '2011-10-14', NULL, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets in equity securities of companies with medium-sized market capitalizations. The adviser defines mid-cap companies as those companies with market capitalizations within the range of companies in the Russell Midcap© Growth Total Return Index at the time of investment. The fund may invest up to 25% of its net assets in securities of foreign mid-cap companies that are traded in the U.S., including companies located in emerging markets, as well as American Depositary Receipts.', 0.0135, 0.0085, 212, 10, 13.425, 13.773, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 9882672, "Yield_Rate": null, "Expense_Net": 0.0135, "Benchmark_Exp": 0.0085, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 212, "Vol_Recent": 10}, "moving_averages": {"MA_50": 13.425, "MA_200": 13.773}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2123, 'DIVB', 'ETF', 'U.S.', 'BlackRock Allocation Target Sha', 'BlackRock Allocation Target Shares Series C Portfolio', 'DOLLAR', 'Value', 'Large', 'BlackRock', 'BTS', NULL, 67180048, 0.0177, '2017-11-07', 0.33, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. The fund will principally invest in the following securities: corporate bonds, notes and debentures; asset-backed securities; commercial and residential mortgage-backed securities; obligations of non-U.S. governments and supra-national organizations, such as the World Bank, which are chartered to promote economic development; collateralized mortgage obligations; U.S. Treasury and agency securities; cash equivalent investments; when-issued and delayed delivery securities; derivatives; and repurchase agreements, etc.', 0.0025, NULL, 26295, 25810, 40.992, 39.36, 0.9964, 0, 3.14, 13.8, 22.36, 2.38, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 67180048, "Yield_Rate": 0.0177, "Expense_Net": 0.0025, "Benchmark_Exp": null, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 26295, "Vol_Recent": 25810}, "moving_averages": {"MA_50": 40.992, "MA_200": 39.36}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9964}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.14, "PE_Ratio": 22.36, "PS_Ratio": 2.38, "PCF_Ratio": 13.8}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2124, 'DSI', 'ETF', 'America', 'Bridgeway Fund Aggressive Inves', 'Bridgeway Aggressive Investors 1 Fund', 'US_DOLLAR', 'Blend', 'Large', 'Bridgeway', 'PCX', 'Large Blend', 3267320832, 0.0101, '2006-11-14', 0.05, 'The investment seeks to exceed the stock market total return (primarily through capital appreciation) at a level of total risk roughly equal to that of the stock market over longer periods of time (three year intervals or more). The fund invests in a diversified portfolio of common stocks of companies of any size that are listed on the New York Stock Exchange, NYSE American and NASDAQ. It may invest in stocks for which there is relatively low market liquidity, as periodically determined by the Adviser based on the stock''s trading volume.', 0.0025, 0.0036, 166028, 204020, 89.102, 83.351, 0.9976, 0, 5.47, 18.03, 29.1, 3.26, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 3267320832, "Yield_Rate": 0.0101, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 166028, "Vol_Recent": 204020}, "moving_averages": {"MA_50": 89.102, "MA_200": 83.351}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.47, "PE_Ratio": 29.1, "PS_Ratio": 3.26, "PCF_Ratio": 18.03}}');
