INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2144, 'EWZ', 'ETF', 'United States', 'iShares Russell 1000 Large-Cap ', 'iShares Russell 1000 Large-Cap Index Fund Investor A Shares', 'USD', 'Blend', 'Large', 'BlackRock', 'PCX', 'Latin America Stock', 6603489792, 0.0222, '2000-07-10', 0.29, 'The investment seeks to match the performance of the Russell 1000© Index, as closely as possible before the deduction of fund expenses. The fund is a "feeder" fund that invests all of its assets in the master portfolio, which has the same investment objective and strategies as the fund. It will be substantially invested in equity securities in the Russell 1000, and will invest, under normal circumstances, at least 80% of its net assets in securities or other financial instruments that are components of or have economic characteristics similar to the securities included in the Russell 1000.', 0.0059, 0.0066, 29066487, 2.788668e+07, 30.831, 35.087, NULL, NULL, 2.42, 6.28, 13.22, 1.71, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 6603489792, "Yield_Rate": 0.0222, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0066, "Turnover_Ratio": 0.29}', '{"volume_metrics": {"Vol_3M": 29066487, "Vol_Recent": 27886680}, "moving_averages": {"MA_50": 30.831, "MA_200": 35.087}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.42, "PE_Ratio": 13.22, "PS_Ratio": 