INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2145, 'EXI', 'ETF', 'America', 'Bridges Investment Fund, Inc.', 'Bridges Investment Fund', 'Dollar', 'Blend', 'Large', 'Bridges', 'PCX', 'Industrials', 447746240, 0.0129, '2006-09-12', 0.08, 'The investment seeks long-term capital appreciation, with a secondary objective of generating a modest amount of current income. The fund invests primarily in a diversified portfolio of common stocks, which fund management believes offers the potential for increased earnings and dividends over time. Normally, such equity securities will represent 60% or more of the fund''s net assets. It may invest up to 15% of its total assets in U.S. dollar-denominated securities of foreign issuers traded on U.S. exchanges, and up to 20% of its total assets in American Depositary Receipts ("ADRs") traded on U.S. exchanges or in the U.S. over-the-counter market.', 0.0046, 0.0046, 7663, 9710, 121.569, 120.052, 0.9969, 0, 3.58, 14.78, 26.87, 1.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 447746240, "Yield_Rate": 0.0129, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.08}', '{"volume_metrics": {"Vol_3M": 7663, "Vol_Recent": 9710}, "moving_averages": {"MA_50": 121.569, "MA_200": 120.052}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9969}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.58, "PE_Ratio": 26.87, "PS_Ratio": 1.92, "PCF_Ratio": 14.78}}');
