INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2182, 'IBHE', 'ETF', 'USA', 'Bridgeway Small Cap Growth Fd C', 'Bridgeway Small Cap Growth Fund', 'usd', NULL, NULL, 'Bridgeway', 'BTS', 'High Yield Bond', 32696460, 0.0532, '2019-05-07', 0.42, 'The investment seeks to provide long-term total return on capital, primarily through capital appreciation. The fund invests in a diversified portfolio of small-cap stocks that are listed on the New York Stock Exchange, NYSE American and NASDAQ. It invests at least 80% of its net assets (plus borrowings for investment purposes) in stocks from among those in the small-cap growth category at the time of purchase. The Adviser selects stocks within the small-cap growth category for the fund using a statistical approach.', 0.0035, 0.0047, 5333, 3860, 24.873, 25.001, NULL, NULL, NULL, NULL, NULL, NULL, 1.95, 1.89, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 32696460, "Yield_Rate": 0.0532, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.42}', '{"volume_metrics": {"Vol_3M": 5333, "Vol_Recent": 3860}, "moving_averages": {"MA_50": 24.873, "MA_200": 25.001}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.95, "Duration_Yrs": 1.89}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2172, 'IBDQ', 'ETF', 'USA', 'BlackRock 40/60 Target Allocati', 'BlackRock 40/60 Target Allocation Fund Class R Shares', 'Usd', NULL, NULL, 'BlackRock', 'PCX', NULL, 1131234688, 0.0216, '2015-03-11', 0.14, 'The investment seeks a balance between long term capital appreciation and high current income, with an emphasis on income. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 40% of its assets and exposure to fixed-income securities in an amount equal to 60% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.001, NULL, 168706, 210550, 26.662, 26.888, NULL, NULL, NULL, NULL, NULL, NULL, 3.76, 3.55, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 1131234688, "Yield_Rate": 0.0216, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 168706, "Vol_Recent": 210550}, "moving_averages": {"MA_50": 26.662, "MA_200": 26.888}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.76, "Duration_Yrs": 3.55}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2173, 'IBDR', 'ETF', 'usa', 'Bramshill Income Performance Fu', 'Bramshill Income Performance Fund Institutional Class', 'Usd', 'Blend', 'Medium', 'Bramshill Investments', 'PCX', NULL, 749377920, 0.0244, '2016-09-13', 0.05, 'The investment seeks to maximize total return. The fund''s investments are comprised of a tactical portfolio of income-producing securities, including up to 80% in investment grade corporate bonds and up to 40% in high yield bonds (i.e. junk bonds). It may also invest up to 70% in preferred stocks, up to 80% in U.S. municipal bonds, and up to 100% in U.S. Treasuries. The fund may also invest up to 15% in fixed income closed-end funds and up to 25% in fixed income exchange traded funds ("ETFs"). It may also invest up to 25% in foreign issuers of U.S. dollar denominated fixed income securities.', 0.001, NULL, 199903, 234930, 26.258, 26.488, NULL, NULL, NULL, NULL, NULL, NULL, 4.88, 4.58, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 749377920, "Yield_Rate": 0.0244, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 199903, "Vol_Recent": 234930}, "moving_averages": {"MA_50": 26.258, "MA_200": 26.488}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.88, "Duration_Yrs": 4.58}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2174, 'IBDS', 'ETF', 'UNITED_STATES', 'BlackRock Advantage Internation', 'BlackRock Advantage International Fund Investor A Shares', 'Usd', NULL, NULL, 'BlackRock', 'PCX', NULL, 472861152, 0.0243, '2017-09-12', 0.1, 'The investment seeks to provide long-term capital appreciation. The fund seeks to invest at least 80% of its net assets plus the amount of any borrowings for investment purposes in non-U.S. equity securities and equity-like instruments of companies that are components of, or have characteristics similar to, the companies included in the MSCI EAFE© Index (the "MSCI EAFE Index") and derivatives that are tied economically to securities of the MSCI EAFE Index. Equity securities include common stock, preferred stock and convertible securities. It primarily seeks to buy common stock and may also invest in preferred stock and convertible securities.', 0.001, NULL, 63380, 70650, 26.721, 26.94, NULL, NULL, NULL, NULL, NULL, NULL, 5.85, 5.38, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 472861152, "Yield_Rate": 0.0243, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 63380, "Vol_Recent": 70650}, "moving_averages": {"MA_50": 26.721, "MA_200": 26.94}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.85, "Duration_Yrs": 5.38}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
