INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2195, 'IDRV', 'ETF', 'United States', 'Bretton Fund', 'Bretton Fund', 'US_DOLLAR', 'Blend', 'Large', 'Bretton Fund', 'PCX', NULL, 388246048, 0.0062, '2019-04-16', 0.19, 'The investment seeks long-term capital appreciation. The fund seeks to achieve long-term capital appreciation by investing in a small number of undervalued securities. It invests primarily in common stocks of companies of all sizes. The fund may also invest in other types of equity securities, as well as fixed income securities. It will normally hold a core position of between 15 to 20 securities. The fund may invest a significant portion of its assets in a particular sector. It is non-diversified.', 0.0047, NULL, 93777, 171780, 52.371, 49.069, 0.9976, 0, 2.32, 9.22, 23.6, 1.35, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 388246048, "Yield_Rate": 0.0062, "Expense_Net": 0.0047, "Benchmark_Exp": null, "Turnover_Ratio": 0.19}', '{"volume_metrics": {"Vol_3M": 93777, "Vol_Recent": 171780}, "moving_averages": {"MA_50": 52.371, "MA_200": 49.069}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.32, "PE_Ratio": 23.6, "PS_Ratio": 1.35, "PCF_Ratio": 9.22}}');
