INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2265, 'MLPB', 'ETF', 'US', 'BlackRock Total Factor Fund - C', 'BlackRock Total Factor Fund Investor A Shares', 'Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Energy Limited Partnership', 223107712, 0.0689, '2015-10-09', NULL, 'The investment seeks total return. The fund invests in a broad range of global asset classes, such as equity securities, fixed and floating rate debt instruments, derivatives, other investment companies, including exchange-traded funds ("ETFs"), real estate investment trusts ("REITs") and commodity-related instruments. It will normally invest in both U.S. and non-U.S. companies, including companies located in emerging markets and in securities denominated in both U.S. dollars and foreign currencies.', 0.0085, 0.0074, 21166, 15820, 16.089, 15.553, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 223107712, "Yield_Rate": 0.0689, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0074, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 21166, "Vol_Recent": 15820}, "moving_averages": {"MA_50": 16.089, "MA_200": 15.553}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2226, 'INDA', 'ETF', 'U.S.', 'BlackRock Advantage ESG Interna', 'BlackRock Advantage ESG International Equity Fund Investor A', 'Dollar', 'Blend', 'Large', 'BlackRock', 'BTS', 'India Equity', 5794894848, 0.0017, '2012-02-02', 0.25, 'The investment seeks to provide long-term capital appreciation. Under normal circumstances, the fund seeks to invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in non-U.S. equity securities and equity-like instruments of companies that are components of, or have characteristics similar to, the companies included in the MSCI EAFE Index and derivatives that are tied economically to securities of the MSCI EAFE Index. From time to time, it may invest in shares of companies through "new issues" or initial public offerings ("IPOs").', 0.0069, 0.0084, 3126380, 4.2685e+06, 49.418, 45.484, NULL, NULL, 3.56, 14.14, 27.29, 2.71, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 5794894848, "Yield_Rate": 0.0017, "Expense_Net": 0.0069, "Benchmark_Exp": 0.0084, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 3126380, "Vol_Recent": 4268500}, "moving_averages": {"MA_50": 49.418, "MA_200": 45.484}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.56, "PE_Ratio": 27.29, "PS_Ratio": 2.71, "PCF_Ratio": 14.14}}');
