INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2274, 'REM', 'ETF', 'UNITED_STATES', NULL, 'Bitcoin Strategy ProFund Investor Class', 'Usd', 'Value', 'Small', 'ProFunds', 'BTS', 'Real Estate', 1565561216, 0.06, '2007-05-01', 0.3, 'The investment seeks capital appreciation. The fund seeks to provide capital appreciation by investing all or substantially all of its assets through actively managed exposure to bitcoin futures contracts. It does not invest directly in bitcoin. The fund does not invest in, or seek exposure to, the current "spot" or cash price of bitcoin. It is non-diversified.', 0.0048, 0.0037, 410822, 612650, 37.189, 36.466, NULL, NULL, 1.09, 6.41, 5.12, 1.65, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 1565561216, "Yield_Rate": 0.06, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.3}', '{"volume_metrics": {"Vol_3M": 410822, "Vol_Recent": 612650}, "moving_averages": {"MA_50": 37.189, "MA_200": 36.466}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.09, "PE_Ratio": 5.12, "PS_Ratio": 1.65, "PCF_Ratio": 6.41}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2276, 'REZ', 'ETF', 'America', 'Brown Advisory Tax-Exempt Bond ', 'Brown Advisory Tax Exempt Bond Fund Institutional Shares', 'Usd', 'Blend', 'Medium', 'Brown Advisory Funds', 'PCX', 'Real Estate', 666235392, 0.0253, '2007-05-01', 0.07, 'The investment seeks to provide a high level of current income exempt from Federal income tax by investing primarily in intermediate-term investment grade municipal bonds. The fund normally will invest at least 80% of the fund''s net assets (plus borrowings for investment purposes) in securities the interest of which is exempt from Federal income taxes and that do not subject shareholders to the federal alternative minimum tax ("AMT"). It may invest up to 20% of its assets in securities that may fully subject shareholders to Federal income tax, including the AMT. The fund is non-diversified.', 0.0048, 0.0037, 147782, 157760, 90.282, 84.257, 0.9956, 0, 2.92, 21.78, 45.41, 10.03, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 666235392, "Yield_Rate": 0.0253, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.07}', '{"volume_metrics": {"Vol_3M": 147782, "Vol_Recent": 157760}, "moving_averages": {"MA_50": 90.282, "MA_200": 84.257}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9956}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.92, "PE_Ratio": 45.41, "PS_Ratio": 10.03, "PCF_Ratio": 21.78}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2277, 'RXI', 'ETF', 'usa', 'BlackRock Technology Opportunit', 'BlackRock Technology Opportunities Fund Class K', 'Dollar', 'Growth', 'Large', 'BlackRock', 'PCX', 'Consumer Cyclical', 462655392, 0.0068, '2006-09-12', 0.34, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets in equity securities issued by U.S. and non-U.S. technology companies in all market capitalization ranges, selected for their rapid and sustainable growth potential from the development, advancement and use of technology. It may invest in both developed and emerging markets. The fund invests primarily in common stock but may also invest in preferred stock and convertible securities. It may also invest in Rule 144A securities, which are privately placed securities purchased by qualified institutional buyers.', 0.0046, 0.0045, 8793, 9570, 176.572, 169.63, 0.9986, 0, 3.73, 13.47, 26.95, 1.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 462655392, "Yield_Rate": 0.0068, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0045, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 8793, "Vol_Recent": 9570}, "moving_averages": {"MA_50": 176.572, "MA_200": 169.63}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.73, "PE_Ratio": 26.95, "PS_Ratio": 1.92, "PCF_Ratio": 13.47}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2278, 'SCJ', 'ETF', 'U.S.A.', 'BTS Tactical Fixed Income Fund ', 'BTS Tactical Fixed Income Fund Class A', 'USD', 'Blend', 'Medium', 'BTS', 'PCX', 'Japan Stock', 71845280, 0.0074, '2007-12-20', 0.1, 'The investment seeks to provide total return. Under normal circumstances, the fund invests (long or short) at least 80% of its assets in fixed income securities of domestic and foreign issuers or counterparties ("80% investment policy"). The Adviser seeks to achieve the fund''s investment objective by investing primarily in a portfolio of fixed income securities without restriction as to maturity, credit quality, type of issuer, country or currency.', 0.0051, 0.004, 11471, 9620, 79.658, 80.911, 0.9953, 0, 1.1, 8.19, 16.42, 0.71, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 71845280, "Yield_Rate": 0.0074, "Expense_Net": 0.0051, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 11471, "Vol_Recent": 9620}, "moving_averages": {"MA_50": 79.658, "MA_200": 80.911}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.1, "PE_Ratio": 16.42, "PS_Ratio": 0.71, "PCF_Ratio": 8.19}}');
