INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2282, 'SMLF', 'ETF', 'U.S.', 'Northern Funds U.S.Treasury Ind', 'Northern U.S. Treasury Index Fund', 'US Dollar', 'Blend', 'Small', 'Northern Funds', 'PCX', 'Small Blend', 1000101120, 0.0106, '2015-04-28', 0.48, 'The investment seeks to provide investment results approximating the performance of the Bloomberg Barclays U.S. Treasury Index. The fund will invest substantially all (and at least 80%) of its net assets in a representative sample of the U.S. Treasury obligations included in the Bloomberg Barclays U.S. Treasury Index. It will buy and sell securities with the goal of achieving an overall duration and total return similar to that of the index. The Bloomberg Barclays U.S. Treasury Index is an unmanaged index that includes a broad range of U.S. Treasury obligations and is considered representative of U.S. Treasury bond performance overall.', 0.003, 0.004, 44226, 40180, 56.564, 54.46, 0.9963, 0, 2.46, 8.77, 15.36, 1.09, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1000101120, "Yield_Rate": 0.0106, "Expense_Net": 0.003, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 44226, "Vol_Recent": 40180}, "moving_averages": {"MA_50": 56.564, "MA_200": 54.46}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9963}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.46, "PE_Ratio": 15.36, "PS_Ratio": 1.09, "PCF_Ratio": 8.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2283, 'SMMD', 'ETF', 'usa', 'DWS Equity 500 Index Fund - Cla', 'DWS Equity 500 Index Fund - Class S', 'Usd', 'Blend', 'Small', 'DWS', 'BTS', NULL, 307516480, 0.0112, '2017-07-06', 0.16, 'The investment seeks to provide investment results that, before expenses, correspond to the total return of common stocks publicly traded in the United States, as represented by the Standard & Poor''s 500 Composite Stock Price Index (S&P 500© Index). Under normal circumstances, the adviser intends to invest at least 80% of assets, determined at the time of purchase, in stocks of companies included in the S&P 500© Index and in derivative instruments, such as futures contracts and options, that provide exposure to the stocks of companies in the index.', 0.0015, NULL, 26514, 36710, 66.929, 65.255, 0.9961, 0, 2.73, 12.48, 21.86, 1.77, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 307516480, "Yield_Rate": 0.0112, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 26514, "Vol_Recent": 36710}, "moving_averages": {"MA_50": 66.929, "MA_200": 65.255}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9961}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.73, "PE_Ratio": 21.86, "PS_Ratio": 1.77, "PCF_Ratio": 12.48}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2284, 'SUB', 'ETF', 'usa', 'Belmont Theta Income Fund Insti', 'Belmont Theta Income Fund Institutional Class', 'US Dollar', NULL, NULL, 'Belmont Capital Group', 'PCX', 'Muni National Short', 5082960896, 0.0102, '2008-11-05', 0.18, 'The investment seeks long-term growth of capital and income generation with limited correlation to equity markets. The fund utilizes an option premium collection strategy that implements a put spread and a call spread on the S&P 500© Index (SPX) to create a number of defined-risk trades. A defined risk trade is essentially where a series of financial instruments (such as options) are entered into where the terms and conditions of the financial instruments are, in combination, designed to limit the overall risk.', 0.0007, 0.0023, 305238, 382550, 107.44, 107.725, NULL, NULL, NULL, NULL, NULL, NULL, 2.1, 1.98, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 5082960896, "Yield_Rate": 0.0102, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 305238, "Vol_Recent": 382550}, "moving_averages": {"MA_50": 107.44, "MA_200": 107.725}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.1, "Duration_Yrs": 1.98}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2292, 'UGA', 'ETF', 'United States', 'iShares MSCI EAFE International', 'iShares MSCI EAFE International Index Fund Class K', 'Dollar', NULL, NULL, 'BlackRock', 'PCX', NULL, 120135544, NULL, '2008-02-26', NULL, 'The investment seeks to match the performance of the MSCI EAFE Index (Europe, Australasia, Far East) in U.S. dollars with net dividends as closely as possible before the deduction of fund expenses. The fund will be substantially invested in securities in the MSCI EAFE Index, and will invest at least 80% of its assets in securities or other financial instruments that are components of or have economic characteristics similar to the securities included in the MSCI EAFE Index.', 0.0075, NULL, 65779, 90960, 40.919, 36.065, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 120135544, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 65779, "Vol_Recent": 90960}, "moving_averages": {"MA_50": 40.919, "MA_200": 36.065}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
