INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2287, 'TFLO', 'ETF', 'United States', 'Baillie Gifford International C', 'Baillie Gifford International Concentrated Growth Equities Fund Class K', 'USD', NULL, NULL, 'Baillie Gifford Funds', 'PCX', 'Ultrashort Bond', 271503904, 0.0005, '2014-02-04', 0.44, 'The investment seeks capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in equity securities. The fund invests in an international portfolio of common stocks and other equity securities of issuers located in countries of developed and emerging markets. It may invest up to 20% of its net assets in common stocks and other equities of companies located in the U.S. The fund may invest in equity securities either directly or indirectly, such as through depositary receipts, and may invest in preferred stocks, convertible securities and warrants. It is non-diversified.', 0.0015, 0.0022, 80811, 50210, 50.267, 50.279, NULL, NULL, NULL, NULL, NULL, NULL, 1.1, 0.01, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 271503904, "Yield_Rate": 0.0005, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 0.44}', '{"volume_metrics": {"Vol_3M": 80811, "Vol_Recent": 50210}, "moving_averages": {"MA_50": 50.267, "MA_200": 50.279}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.1, "Duration_Yrs": 0.01}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
