INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2299, 'USL', 'ETF', 'U.S.A.', 'Boston Trust SMID Cap Fund', 'Boston Trust SMID Cap Fund', 'Usd', NULL, NULL, 'Boston Trust Walden Funds', 'PCX', NULL, 188204144, NULL, '2007-12-06', 0.4954, 'The investment seeks long-term capital growth through an actively managed portfolio of stocks of small and middle capitalization companies. The fund invests, under normal circumstances, at least 80% of its assets in a diversified portfolio of domestic equity securities of small and mid cap companies. For these purposes, the Adviser defines small and mid cap issuers as those with market capitalizations within the range encompassed by the Russell 2500TM Index at the time of purchase. In addition, changes to the composition of the Russell 2500TM Index can change the market capitalization range of the companies included in the index.', 0.0088, NULL, 60253, 113290, 28.138, 24.8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 188204144, "Yield_Rate": null, "Expense_Net": 0.0088, "Benchmark_Exp": null, "Turnover_Ratio": 0.4954}', '{"volume_metrics": {"Vol_3M": 60253, "Vol_Recent": 113290}, "moving_averages": {"MA_50": 28.138, "MA_200": 24.8}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2301, 'VEGI', 'ETF', 'usa', 'American Century Zero Coupon 20', 'American Century Zero Coupon 2025 Fund Investor Class', 'US_DOLLAR', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Natural Resources', 89065976, 0.0124, '2012-01-31', 0.09, 'The investment seeks the highest return consistent with investment in U.S. Treasury securities. The fund invests at least 80% of the value of its net assets in zero-coupon securities. It invests primarily in zero-coupon U.S. Treasury securities and their equivalents (including certain zero-coupon U.S. government agency securities), and may invest up to 20% of its assets in other zero-coupon U.S. government agency securities that are AAA-rated. Zero-coupon securities make no periodic interest or principal payments. The fund is managed to mature in the year 2025 and will be liquidated near the end of its target maturity year.', 0.0039, 0.0048, 13620, 11380, 40.4, 40.087, 0.9966, 0, 2.47, 10.39, 21.55, 1.16, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 89065976, "Yield_Rate": 0.0124, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 13620, "Vol_Recent": 11380}, "moving_averages": {"MA_50": 40.4, "MA_200": 40.087}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9966}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.47, "PE_Ratio": 21.55, "PS_Ratio": 1.16, "PCF_Ratio": 10.39}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2302, 'WPS', 'ETF', 'UNITED_STATES', 'Cboe Vest S&P 500 Buffer Strate', 'CBOE Vest S&P 500 Buffer Strategy Fund Class A Shares', 'Usd', 'Value', 'Medium', 'CBOE Vest', 'PCX', 'Global Real Estate', 80536672, 0.0241, '2007-07-30', 0.16, 'The investment seeks to track, before fees and expenses, the performance of the Cboe© S&P 500© Buffer Protect Index Balanced Series (the "SPRO Index"). The adviser attempts to meet its objective by constructing a portfolio of specially designed options that are similar to options that comprise the indices that underlie the SPRO Index. The SPRO Index is a balanced index that is a composite of the twelve (12) Cboe© S&P 500© Buffer Protect Index Monthly Series that correspond to each month of the year. The fund is non-diversified.', 0.0048, 0.0053, 5352, 8000, 37.789, 38.141, NULL, NULL, 1.02, 14.35, 15.62, 3.71, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 80536672, "Yield_Rate": 0.0241, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 5352, "Vol_Recent": 8000}, "moving_averages": {"MA_50": 37.789, "MA_200": 38.141}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.02, "PE_Ratio": 15.62, "PS_Ratio": 3.71, "PCF_Ratio": 14.35}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2303, 'ZIVZF', 'ETF', 'UNITED_STATES', 'BlackRock U.S. Impact Fund Inve', 'BlackRock U.S. Impact Fund Investor A', 'Dollar', NULL, NULL, 'BlackRock', 'PNK', 'Trading--Miscellaneous', 22840564, NULL, '2010-11-29', NULL, 'The investment seeks total return. Under normal circumstances, the fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in U.S. securities. It will invest primarily in equity securities and other financial instruments that have similar economic characteristics to such securities. The fund may invest in issuers of any market capitalization, including small- to mid-capitalization companies. It is non-diversified.', 0.0135, 0.0087, 919, 2160, 31.791, 31.423, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 22840564, "Yield_Rate": null, "Expense_Net": 0.0135, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 919, "Vol_Recent": 2160}, "moving_averages": {"MA_50": 31.791, "MA_200": 31.423}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2304, 'EEM', 'ETF', 'USA', 'Baird Ultra Short Bond Fund Ins', 'Baird Ultra Short Bond Fund Institutional Class', 'USD', 'Blend', 'Large', 'Baird', 'PCX', 'Diversified Emerging Mkts', 30988068864, 0.0145, '2003-04-07', 0.19, 'The investment seeks current income consistent with preservation of capital. The fund normally invests at least 80% of its net assets in bonds, including the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector entities; asset-backed and mortgage-backed obligations of U.S. and foreign issuers; Corporate debt of U.S. and foreign issuers; money market instruments. It invests primarily in investment-grade debt obligations, rated at the time of purchase by at least one major rating agency, but may invest up to 10% of its net assets in high yield bonds.', 0.0068, 0.0056, 39884565, 5.353158e+07, 50.881, 52.774, 0.9929, 0, 1.97, 9.81, 14.78, 1.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 30988068864, "Yield_Rate": 0.0145, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.19}', '{"volume_metrics": {"Vol_3M": 39884565, "Vol_Recent": 53531580}, "moving_averages": {"MA_50": 50.881, "MA_200": 52.774}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9929}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.97, "PE_Ratio": 14.78, "PS_Ratio": 1.56, "PCF_Ratio": 9.81}}');
